package api

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"net/http"
	"strings"

	"golang.org/x/crypto/bcrypt"
)

func hashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func checkPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

// authMiddleware extracts bearer [REDACTED], loads session+user, sets context.
func (s *Server) authMiddleware(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		authz := r.Header.Get("Authorization")
		token := ""
		if strings.HasPrefix(authz, "Bearer ") {
			token = strings.TrimPrefix(authz, "Bearer ")
		}
		if token == "" {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "missing bearer [REDACTED]")
			return
		}
		ctx := r.Context()
		var userID, activeRole, username string
		var active bool
		err := s.DB.QueryRow(ctx, `SELECT sessions.user_id, coalesce(sessions.active_role,''), users.username, users.active
			FROM sessions JOIN users ON users.id = sessions.user_id WHERE sessions.token=$1`, token).
			Scan(&userID, &activeRole, &username, &active)
		if err != nil || !active {
			writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid session")
			return
		}
		rows, err := s.DB.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
		if err != nil {
			writeErr(w, http.StatusInternalServerError, "internal_error", "")
			return
		}
		var roles []string
		for rows.Next() {
			var role string
			_ = rows.Scan(&role)
			roles = append(roles, role)
		}
		rows.Close()
		ctx = withAuth(ctx, userID, roles, activeRole, username)
		next(w, r.WithContext(ctx))
	}
}

// requireRoleSelected ensures activeRole is set among the roles required for handlers that need one.
func requireRoleSelected(ctx context.Context) bool {
	return activeRoleFrom(ctx) != ""
}

