func (s *Server) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
	var req authenticateReq
	if !readJSON(r, &req) || req.Username == "" || req.Password == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	ctx := r.Context()
	var userID, passHash string
	var active bool
	err := s.DB.QueryRow(ctx, `SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).Scan(&userID, &passHash, &active)
	if err != nil || !active || !checkPassword(passHash, req.Password) {
		s.audit(ctx, "", "", "sign_in", "user", req.Username, false, nil)
		writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
		return
	}
	roles := s.fetchRoles(ctx, userID)
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	token := newToken()
	_, err = s.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, nilIfEmpty(activeRole))
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, activeRole, "sign_in", "user", userID, true, nil)
	writeData(w, http.StatusOK, map[string]interface{}{
		"sessionToken": token,
		"userId":       userID,
		"roles":        roles,
		"activeRole":   activeRole,
	})
}

