	var req selectRoleReq
	if !readJSON(r, &req) || req.Role == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	ctx := r.Context()
	userID := userIDFrom(ctx)
	roles := rolesFrom(ctx)
