	for _, rr := range roles {
		if rr == req.Role {
			found = true
		}
	}
	if !found {
		writeErr(w, http.StatusForbidden, "role_not_held", "user does not hold this role")
		return
	}
	authz := r.Header.Get("Authorization")
	token := authz[len("Bearer "):]
	_, err := s.DB.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, token)
