		}
		_, _ = s.DB.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, req.UserID, c.Code, c.Active, exp)
	}
	actorID := userIDFrom(ctx)
	s.audit(ctx, actorID, "administrator", "update_user_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles})
	writeData(w, http.StatusCreated, map[string]interface{}{
		"userId": req.UserID, "roles": req.Roles, "qualifications": req.Qualifications, "certifications": req.Certifications, "active": *req.Active,
	})
