func isValidRoleStr(r string) bool {
	switch r {
	case "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		return true
	}
	return false
}

func (s *Server) ReadUser(w http.ResponseWriter, r *http.Request, userID string) {
	ctx := r.Context()
	actorRole := activeRoleFrom(ctx)
	actorID := userIDFrom(ctx)
	if actorRole != "administrator" && actorRole != "dispatcher" && actorID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var username, email, fullName, phone string
	var active bool
	err := s.DB.QueryRow(ctx, `SELECT username, coalesce(email,''), coalesce(full_name,''), coalesce(phone,''), active FROM users WHERE id=$1`, userID).
		Scan(&username, &email, &fullName, &phone, &active)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	roles := s.fetchRoles(ctx, userID)
	quals := s.fetchQualifications(ctx, userID)
	certs := s.fetchCertifications(ctx, userID)
	writeData(w, http.StatusOK, map[string]interface{}{
		"userId": userID, "username": username, "email": email, "fullName": fullName, "phone": phone,
		"roles": roles, "qualifications": quals, "certifications": certs, "active": active,
	})
}

func (s *Server) fetchRoles(ctx context.Context, userID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
	out := []string{}
	if err == nil {
		for rows.Next() {
			var r string
			_ = rows.Scan(&r)
			out = append(out, r)
		}
		rows.Close()
	}
	return out
}

func (s *Server) fetchQualifications(ctx context.Context, userID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT qualification FROM user_qualifications WHERE user_id=$1`, userID)
	out := []string{}
	if err == nil {
		for rows.Next() {
			var q string
			_ = rows.Scan(&q)
			out = append(out, q)
		}
		rows.Close()
	}
	return out
}

func (s *Server) fetchCertifications(ctx context.Context, userID string) []certReq {
	rows, err := s.DB.Query(ctx, `SELECT code, active, expires_at FROM user_certifications WHERE user_id=$1`, userID)
	out := []certReq{}
	if err == nil {
		for rows.Next() {
			var c certReq
			var exp *time.Time
			_ = rows.Scan(&c.Code, &c.Active, &exp)
			if exp != nil {
				c.ExpiresAt = isoOf(*exp)
			}
			out = append(out, c)
		}
		rows.Close()
	}
	return out
}

