package api

import (
	"context"
	"encoding/json"
	"math"
	"sync"
)

var svcMu sync.Mutex
var svcVersion int
var svcComputing bool

func (s *Server) bumpNetworkRevision(ctx context.Context) {
	go s.recomputeServiceability(context.Background())
}

// recomputeServiceability computes a new complete serviceability snapshot and publishes it,
// while any concurrent readers continue to see the previous complete version until this
// one is fully written.
func (s *Server) recomputeServiceability(ctx context.Context) {
	svcMu.Lock()
	if svcComputing {
		svcMu.Unlock()
		return
	}
	svcComputing = true
	svcMu.Unlock()
	defer func() {
		svcMu.Lock()
		svcComputing = false
		svcMu.Unlock()
	}()

	rows, err := s.DB.Query(ctx, `SELECT id, name, latitude, longitude, coverage_km FROM locations WHERE active=true AND is_collection_point=true`)
	if err != nil {
		return
	}
	type region struct {
		LocationID string  `json:"locationId"`
		Name       string  `json:"name"`
		Latitude   float64 `json:"latitude"`
		Longitude  float64 `json:"longitude"`
		CoverageKm float64 `json:"coverageKm"`
	}
	var regions []region
	for rows.Next() {
		var reg region
		_ = rows.Scan(&reg.LocationID, &reg.Name, &reg.Latitude, &reg.Longitude, &reg.CoverageKm)
		regions = append(regions, reg)
	}
	rows.Close()
	if regions == nil {
		regions = []region{}
	}
	b, _ := json.Marshal(regions)

	var nextVersion int
	_ = s.DB.QueryRow(ctx, `SELECT coalesce(max(version),0)+1 FROM serviceability_snapshots`).Scan(&nextVersion)
	_, err = s.DB.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete',$1,$2,$3)`, nextVersion, b, len(regions))
	if err != nil {
		return
	}
	svcMu.Lock()
	svcVersion = nextVersion
	svcMu.Unlock()
}

func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	toRad := func(deg float64) float64 { return deg * math.Pi / 180 }
	dLat := toRad(lat2 - lat1)
	dLon := toRad(lon2 - lon1)
