	// 2. find an active laboratory that accepts the sample type
	rows, err := s.DB.Query(ctx, `SELECT l.id, l.latitude, l.longitude FROM locations l
		JOIN laboratory_acceptance a ON a.laboratory_id=l.id AND a.sample_type_id=$1 AND a.accepts=true
		WHERE l.active=true AND l.is_laboratory=true`, sampleTypeID)
	type lab struct {
		ID       string
		Lat, Lng float64
	}
	var labs []lab
	if err == nil {
		for rows.Next() {
			var l lab
			_ = rows.Scan(&l.ID, &l.Lat, &l.Lng)
			labs = append(labs, l)
		}
		rows.Close()
	}
	if len(labs) == 0 {
		res.Reason = "no_accepting_laboratory"
		return res
	}

	// 3. pick nearest lab as target (route existence approximated by distance-based travel time)
	best := labs[0]
	bestDist := haversineKm(lat, lng, best.Lat, best.Lng)
	for _, l := range labs[1:] {
		d := haversineKm(lat, lng, l.Lat, l.Lng)
		if d < bestDist {
			best = l
			bestDist = d
		}
	}
	res.TargetLaboratoryID = best.ID

	// naive travel time estimate: 2 min per km + 30 min handling
	travelMinutes := bestDist*2 + 30
	deadline, ok := parseTime(deliveryDeadlineISO)
	if !ok {
		res.Reason = "no_route"
		return res
	}
	arrival := timeNow().Add(minutesToDuration(travelMinutes))
	if arrival.After(deadline) {
		res.Reason = "deadline_unreachable"
		res.EstimatedArrivalISO = isoOf(arrival)
		return res
	}

	// 4. capacity check at laboratory (regular units available)
	var availUnits int
	_ = s.DB.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM locations WHERE id=$1`, best.ID).Scan(&availUnits)
	if availUnits <= 0 {
		res.Reason = "insufficient_capacity"
		return res
	}

	res.Serviceable = true
	res.Reason = "serviceable"
	res.EstimatedArrivalISO = isoOf(arrival)
	return res
}

