func (s *Server) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "administrator" && role != "node_handler" && role != "laboratory_team" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
