package api

import (
	"net/http"
)

type checkServiceabilityReq struct {
	Origin              coordinateReq `json:"origin"`
	OriginType          string        `json:"originType"`
	OriginNodeID        string        `json:"originNodeId"`
	SampleTypeID        string        `json:"sampleTypeId"`
	RequestedAt         string        `json:"requestedAt"`
	DeliveryDeadline    string        `json:"deliveryDeadline"`
	EarliestCollectionAt string       `json:"earliestCollectionAt"`
	LatestCollectionAt   string       `json:"latestCollectionAt"`
}

func (s *Server) CheckServiceability(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req checkServiceabilityReq
	if !readJSON(r, &req) || req.SampleTypeID == "" || req.RequestedAt == "" || req.DeliveryDeadline == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.Origin.Latitude < -90 || req.Origin.Latitude > 90 || req.Origin.Longitude < -180 || req.Origin.Longitude > 180 {
		writeErr(w, http.StatusBadRequest, "invalid_origin", "")
		return
	}
	reqAt, ok1 := parseTime(req.RequestedAt)
	deadline, ok2 := parseTime(req.DeliveryDeadline)
	if !ok1 || !ok2 {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if !deadline.After(reqAt) {
		writeErr(w, http.StatusBadRequest, "invalid_deadline", "")
		return
	}
	if req.EarliestCollectionAt != "" && req.LatestCollectionAt != "" {
		ea, ok3 := parseTime(req.EarliestCollectionAt)
		la, ok4 := parseTime(req.LatestCollectionAt)
		if !ok3 || !ok4 || la.Before(ea) {
			writeErr(w, http.StatusBadRequest, "invalid_collection_window", "")
			return
		}
	}
	var sampleTypeExists bool
	_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM sample_types WHERE id=$1)`, req.SampleTypeID).Scan(&sampleTypeExists)
	if !sampleTypeExists {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}

	result := s.evaluateServiceability(ctx, req.Origin.Latitude, req.Origin.Longitude, req.SampleTypeID, req.DeliveryDeadline)

	actorID := userIDFrom(ctx)
	role := activeRoleFrom(ctx)
	s.audit(ctx, actorID, role, "check_serviceability", "serviceability", "", true, map[string]interface{}{
		"serviceable": result.Serviceable, "reason": result.Reason,
	})

	resp := map[string]interface{}{
		"serviceable":          result.Serviceable,
		"reason":               result.Reason,
		"serviceabilityVersion": result.Version,
	}
	if result.TargetLaboratoryID != "" {
		resp["targetLaboratoryId"] = result.TargetLaboratoryID
	}
	if result.EstimatedArrivalISO != "" {
		resp["estimatedArrivalAt"] = result.EstimatedArrivalISO
	}
	writeData(w, http.StatusOK, resp)
}

func (s *Server) ReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	snap := s.getLatestServiceabilitySnapshot(ctx)
	regions := snap.Regions
	if regions == nil {
		regions = []map[string]interface{}{}
	}
	writeData(w, http.StatusOK, map[string]interface{}{
		"version":                    snap.Version,
		"status":                     "complete",
		"computedAt":                 snap.ComputedAt,
		"networkRevision":            snap.NetworkRevision,
		"regions":                    regions,
		"activeCollectionPointCount": snap.ActiveCollectionPointCount,
	})
}

