action.file_text:
package api

import (
	"context"
	"time"

	"github.com/google/uuid"
)

type sampleTypeInfo struct {
	ID                         string
	Name                       string
	QualifiedCollectorRequired bool
	RequiredQualification      string
	ContainerType              string
	TemperatureMinC            float64
	TemperatureMaxC            float64
	RequiresCooledRoute        bool
	BatchingAllowed            bool
}

func (s *Server) loadSampleType(ctx context.Context, id string) (sampleTypeInfo, bool) {
	var t sampleTypeInfo
	var reqQual *string
	err := s.DB.QueryRow(ctx, `SELECT id, name, qualified_collector_required, required_qualification, container_type,
		temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed FROM sample_types WHERE id=$1`, id).
		Scan(&t.ID, &t.Name, &t.QualifiedCollectorRequired, &reqQual, &t.ContainerType, &t.TemperatureMinC, &t.TemperatureMaxC, &t.RequiresCooledRoute, &t.BatchingAllowed)
	if err != nil {
		return t, false
	}
	if reqQual != nil {
		t.RequiredQualification = *reqQual
	}
	return t, true
}

// buildJourneyPlan constructs a journey (with stops+assignments) for a sample going from
// an origin collection point to a target laboratory, reserving capacity along the way.
// alreadySealed indicates the sample enters the network already sealed at holderLocationID
// (skipping the collection leg).
type journeyBuildResult struct {
	JourneyID          string
	AssignmentIDs      []string
	TargetLaboratoryID string
	EstimatedDelivery  time.Time
	OK                 bool
	FailureCode        string
}

func (s *Server) buildJourneyPlan(ctx context.Context, sampleID, sampleTypeID string, originLat, originLng float64, collectionPointID string, alreadySealed bool, holderLocationID string, deadline time.Time, cooled bool) journeyBuildResult {
	var res journeyBuildResult

	st, ok := s.loadSampleType(ctx, sampleTypeID)
	if !ok {
		res.FailureCode = "no_route"
		return res
	}

	// find target laboratory that accepts sample type
	rows, err := s.DB.Query(ctx, `SELECT l.id, l.latitude, l.longitude FROM locations l
		JOIN laboratory_acceptance a ON a.laboratory_id=l.id AND a.sample_type_id=$1 AND a.accepts=true
		WHERE l.active=true AND l.is_laboratory=true`, sampleTypeID)
	type lab struct {
		ID       string
		Lat, Lng float64
	}
	var labs []lab
	if err == nil {
		for rows.Next() {
			var l lab
			_ = rows.Scan(&l.ID, &l.Lat, &l.Lng)
			labs = append(labs, l)
		}
		rows.Close()
	}
	if len(labs) == 0 {
		res.FailureCode = "no_valid_route"
		return res
	}

	startNode := collectionPointID
	if alreadySealed {
		startNode = holderLocationID
	}

	// choose nearest reachable lab by path length
	bestLab := ""
	var bestPath []edge
	bestMinutes := -1
	for _, l := range labs {
		path, ok := s.shortestPath(ctx, startNode, l.ID)
		if !ok {
			continue
		}
		total := 0
		for _, e := range path {
			total += e.Minutes
		}
		if bestMinutes == -1 || total < bestMinutes {
			bestMinutes = total
			bestLab = l.ID
			bestPath = path
		}
	}
	if bestLab == "" {
		res.FailureCode = "no_valid_route"
		return res
	}

	handlingBuffer := 30.0
	estimatedDelivery := timeNow().Add(minutesToDuration(float64(bestMinutes) + handlingBuffer))
	if estimatedDelivery.After(deadline) {
		res.FailureCode = "deadline_exceeded"
		return res
	}

	// capacity check along route + laboratory
	if !s.checkAndReserveCapacity(ctx, bestPath, bestLab, cooled) {
		res.FailureCode = "capacity_exhausted"
		return res
	}

	journeyID := uuid.NewString()
	routeMode := "direct"
	if len(bestPath) > 1 {
		routeMode = "multi_stop"
	}
	_, err = s.DB.Exec(ctx, `INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, capacity_used, capacity_available)
		VALUES ($1,1,$2,'active',$3,1,0)`, journeyID, routeMode, estimatedDelivery)
	if err != nil {
		res.FailureCode = "invalid_plan"
		return res
	}
	_, _ = s.DB.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, journeyID, sampleID)

	seq := 0
	if !alreadySealed {
		// stop 0: pickup at collection point
		_, _ = s.DB.Exec(ctx, `INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at)
			VALUES ($1,$2,'pickup',$3, now())`, journeyID, collectionPointID, seq)
		seq++
		aID := uuid.NewString()
		_, _ = s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sample_id, sequence, status, to_location_id, required_qualification)
			VALUES ($1,$2,'collection',$3,$4,'pending',$5,$6)`, aID, journeyID, sampleID, seq, collectionPointID, nilIfEmpty(st.RequiredQualification))
		res.AssignmentIDs = append(res.AssignmentIDs, aID)
	}

	for i, e := range bestPath {
		_, _ = s.DB.Exec(ctx, `INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at)
			VALUES ($1,$2,'handoff',$3, now())`, journeyID, e.To, seq)
		seq++
		aID := uuid.NewString()
		_, _ = s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sample_id, sequence, status, from_location_id, to_location_id)
			VALUES ($1,$2,'transport',$3,$4,'pending',$5,$6)`, aID, journeyID, sampleID, seq, e.From, e.To)
		res.AssignmentIDs = append(res.AssignmentIDs, aID)
		_ = i
	}

	// final delivery stop at laboratory
	_, _ = s.DB.Exec(ctx, `INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at)
		VALUES ($1,$2,'delivery',$3,$4)`, journeyID, bestLab, seq, estimatedDelivery)

	// laboratory assignment for intake operator
	labAID := uuid.NewString()
	_, _ = s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sample_id, sequence, status, laboratory_id, expected_sample_type_id)
		VALUES ($1,$2,'laboratory',$3,$4,'pending',$5,$6)`, labAID, journeyID, sampleID, seq+1, bestLab, sampleTypeID)
	res.AssignmentIDs = append(res.AssignmentIDs, labAID)

	_, _ = s.DB.Exec(ctx, `UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2, updated_at=now() WHERE id=$3`, journeyID, bestLab, sampleID)

	res.JourneyID = journeyID
	res.TargetLaboratoryID = bestLab
	res.EstimatedDelivery = estimatedDelivery
	res.OK = true
	return res
}

func (s *Server) checkAndReserveCapacity(ctx context.Context, path []edge, labID string, cooled bool) bool {
	// verify availability first
	for _, e := range path {
		var avail, cooledAvail int
		_ = s.DB.QueryRow(ctx, `SELECT capacity_units-reserved_units, cooled_capacity_units-cooled_reserved_units FROM connections WHERE id=$1`, e.ConnectionID).Scan(&avail, &cooledAvail)
		if cooled {
			if cooledAvail < 1 {
				return false
			}
		} else if avail < 1 {
			return false
		}
	}
	var labAvail, labCooledAvail int
	_ = s.DB.QueryRow(ctx, `SELECT capacity_units-reserved_units, cooled_capacity_units-cooled_reserved_units FROM locations WHERE id=$1`, labID).Scan(&labAvail, &labCooledAvail)
	if cooled {
		if labCooledAvail < 1 {
			return false
		}
	} else if labAvail < 1 {
		return false
	}
	// reserve
	for _, e := range path {
		if cooled {
			_, _ = s.DB.Exec(ctx, `UPDATE connections SET cooled_reserved_units=cooled_reserved_units+1 WHERE id=$1`, e.ConnectionID)
		} else {
			_, _ = s.DB.Exec(ctx, `UPDATE connections SET reserved_units=reserved_units+1 WHERE id=$1`, e.ConnectionID)
		}
	}
	if cooled {
		_, _ = s.DB.Exec(ctx, `UPDATE locations SET cooled_reserved_units=cooled_reserved_units+1 WHERE id=$1`, labID)
	} else {
		_, _ = s.DB.Exec(ctx, `UPDATE locations SET reserved_units=reserved_units+1 WHERE id=$1`, labID)
	}
	return true
}

func (s *Server) releaseJourneyCapacity(ctx context.Context, journeyID string) {
	rows, err := s.DB.Query(ctx, `SELECT DISTINCT from_location_id, to_location_id FROM assignments WHERE journey_id=$1 AND kind='transport'`, journeyID)
	if err == nil {
		for rows.Next() {
			var from, to *string
			_ = rows.Scan(&from, &to)
			if from != nil && to != nil {
				_, _ = s.DB.Exec(ctx, `UPDATE connections SET reserved_units=GREATEST(reserved_units-1,0) WHERE from_location_id=$1 AND to_location_id=$2`, *from, *to)
			}
		}
		rows.Close()
	}
	var labID *string
	_ = s.DB.QueryRow(ctx, `SELECT laboratory_id FROM assignments WHERE journey_id=$1 AND kind='laboratory' LIMIT 1`, journeyID).Scan(&labID)
	if labID != nil {
		_, _ = s.DB.Exec(ctx, `UPDATE locations SET reserved_units=GREATEST(reserved_units-1,0) WHERE id=$1`, *labID)
	}
}

