package api

import (
        "context"
        "encoding/json"
        "net/http"
        "time"

        "github.com/jackc/pgx/v5"
        "github.com/jackc/pgx/v5/pgxpool"
)

type Server struct {
        DB *pgxpool.Pool
}

type errBody struct {
        Error string `json:"error"`
        Code  string `json:"code"`
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
        w.Header().Set("Content-Type", "application/json")
        w.WriteHeader(status)
        _ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
        writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
        if msg == "" {
                msg = code
        }
        writeJSON(w, status, errBody{Error: msg, Code: code})
}

func readJSON(r *http.Request, v interface{}) bool {
        dec := json.NewDecoder(r.Body)
        if err := dec.Decode(v); err != nil {
                return false
        }
        return true
}

func parseTime(s string) (time.Time, bool) {
        if s == "" {
                return time.Time{}, false
        }
        t, err := time.Parse(time.RFC3339, s)
        if err != nil {
                return time.Time{}, false
        }
        return t, true
}

func nowISO() string {
        return time.Now().UTC().Format(time.RFC3339)
}

func timeNow() time.Time {
        return time.Now().UTC()
}

func minutesToDuration(m float64) time.Duration {
        return time.Duration(m * float64(time.Minute))
}

func isoOrNil(t *time.Time) interface{} {
        if t == nil {
                return nil
        }
        return t.UTC().Format(time.RFC3339)
}

func isoOf(t time.Time) string {
        return t.UTC().Format(time.RFC3339)
}

// noRows helper
func isNoRows(err error) bool {
        return err == pgx.ErrNoRows
}

type ctxKey string

const (
        ctxUserID ctxKey = "userID"
        ctxRoles  ctxKey = "roles"
        ctxActiveRole ctxKey = "activeRole"
        ctxUsername ctxKey = "username"
)

func withAuth(ctx context.Context, userID string, roles []string, activeRole string, username string) context.Context {
        ctx = context.WithValue(ctx, ctxUserID, userID)
        ctx = context.WithValue(ctx, ctxRoles, roles)
        ctx = context.WithValue(ctx, ctxActiveRole, activeRole)
        ctx = context.WithValue(ctx, ctxUsername, username)
        return ctx
}

func userIDFrom(ctx context.Context) string {
        v, _ := ctx.Value(ctxUserID).(string)
        return v
}
func rolesFrom(ctx context.Context) []string {
        v, _ := ctx.Value(ctxRoles).([]string)
        return v
}
func activeRoleFrom(ctx context.Context) string {
        v, _ := ctx.Value(ctxActiveRole).(string)
        return v
}
func usernameFrom(ctx context.Context) string {
        v, _ := ctx.Value(ctxUsername).(string)
        return v
}

func hasRole(ctx context.Context, role string) bool {
        for _, r := range rolesFrom(ctx) {
                if r == role {
                        return true
                }
        }
        return false
}

package api

import (
        "context"
        "crypto/rand"
        "encoding/hex"
        "net/http"
        "strings"

        "golang.org/x/crypto/bcrypt"
)

func hashPassword(pw string) (string, error) {
        b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
        return string(b), err
}

func checkPassword(hash, pw string) bool {
        return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func newToken() string {
        b := make([]byte, 32)
        _, _ = rand.Read(b)
        return hex.EncodeToString(b)
}

// authMiddleware extracts bearer [REDACTED], loads session+user, sets context.
func (s *Server) authMiddleware(next http.HandlerFunc) http.HandlerFunc {
        return func(w http.ResponseWriter, r *http.Request) {
                authz := r.Header.Get("Authorization")
                token := ""
                if strings.HasPrefix(authz, "Bearer ") {
                        token = strings.TrimPrefix(authz, "Bearer ")
                }
                if token == "" {
                        writeErr(w, http.StatusUnauthorized, "unauthorized", "missing bearer [REDACTED]")
                        return
                }
                ctx := r.Context()
                var userID, activeRole, username string
                var active bool
                err := s.DB.QueryRow(ctx, `SELECT sessions.user_id, coalesce(sessions.active_role,''), users.username, users.active
                        FROM sessions JOIN users ON users.id = sessions.user_id WHERE sessions.token=$1`, token).
                        Scan(&userID, &activeRole, &username, &active)
                if err != nil || !active {
                        writeErr(w, http.StatusUnauthorized, "unauthorized", "invalid session")
                        return
                }
                rows, err := s.DB.Query(ctx, `SELECT role FROM user_roles WHERE user_id=$1`, userID)
                if err != nil {
                        writeErr(w, http.StatusInternalServerError, "internal_error", "")
                        return
                }
                var roles []string
                for rows.Next() {
                        var role string
                        _ = rows.Scan(&role)
                        roles = append(roles, role)
                }
                rows.Close()
                ctx = withAuth(ctx, userID, roles, activeRole, username)
                next(w, r.WithContext(ctx))
        }
}

// requireRoleSelected ensures activeRole is set among the roles required for handlers that need one.
func requireRoleSelected(ctx context.Context) bool {
        return activeRoleFrom(ctx) != ""
}

