    18	// recomputeServiceability computes a new complete serviceability snapshot and publishes it,
    19	// while any concurrent readers continue to see the previous complete version until this
    20	// one is fully written.
    21	func (s *Server) recomputeServiceability(ctx context.Context) {
    22		svcMu.Lock()
    23		if svcComputing {
    24			svcMu.Unlock()
    25			return
    26		}
    27		svcComputing = true
    28		svcMu.Unlock()
    29		defer func() {
    30			svcMu.Lock()
    31			svcComputing = false
    32			svcMu.Unlock()
