   130	// evaluateServiceability performs the structural network check for a given origin/sample type/deadline.
   131	func (s *Server) evaluateServiceability(ctx context.Context, lat, lng float64, sampleTypeID string, deliveryDeadlineISO string) serviceabilityResult {
   132		snap := s.getLatestServiceabilitySnapshot(ctx)
   133		res := serviceabilityResult{Version: snap.Version}
   134	
   135		// 1. within coverage of an active collection point
   136		inCoverage := false
   137		for _, reg := range snap.Regions {
   138			rlat, _ := reg["latitude"].(float64)
   139			rlng, _ := reg["longitude"].(float64)
   140			rcov, _ := reg["coverageKm"].(float64)
   141			if haversineKm(lat, lng, rlat, rlng) <= rcov {
   142				inCoverage = true
   143				break
   144			}
   145		}
   146		if !inCoverage {
   147			res.Reason = "outside_service_coverage"
   148			return res
   149		}
   150	
   151		// 2. find an active laboratory that accepts the sample type
   152		rows, err := s.DB.Query(ctx, `SELECT l.id, l.latitude, l.longitude FROM locations l
   153			JOIN laboratory_acceptance a ON a.laboratory_id=l.id AND a.sample_type_id=$1 AND a.accepts=true
   154			WHERE l.active=true AND l.is_laboratory=true`, sampleTypeID)
   155		type lab struct {
   156			ID       string
   157			Lat, Lng float64
   158		}
   159		var labs []lab
   160		if err == nil {
   161			for rows.Next() {
   162				var l lab
   163				_ = rows.Scan(&l.ID, &l.Lat, &l.Lng)
   164				labs = append(labs, l)
   165			}
   166			rows.Close()
   167		}
   168		if len(labs) == 0 {
   169			res.Reason = "no_accepting_laboratory"
   170			return res
   171		}
   172	
   173		// 3. pick nearest lab as target (route existence approximated by distance-based travel time)
   174		best := labs[0]
   175		bestDist := haversineKm(lat, lng, best.Lat, best.Lng)
   176		for _, l := range labs[1:] {
   177			d := haversineKm(lat, lng, l.Lat, l.Lng)
   178			if d < bestDist {
   179				best = l
   180				bestDist = d
   181			}
   182		}
   183		res.TargetLaboratoryID = best.ID
   184	
   185		// naive travel time estimate: 2 min per km + 30 min handling
   186		travelMinutes := bestDist*2 + 30
   187		deadline, ok := parseTime(deliveryDeadlineISO)
   188		if !ok {
   189			res.Reason = "no_route"
   190			return res
   191		}
   192		arrival := timeNow().Add(minutesToDuration(travelMinutes))
   193		if arrival.After(deadline) {
   194			res.Reason = "deadline_unreachable"
   195			res.EstimatedArrivalISO = isoOf(arrival)
   196			return res
   197		}
   198	
   199		// 4. capacity check at laboratory (regular units available)
   200		var availUnits int
   201		_ = s.DB.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM locations WHERE id=$1`, best.ID).Scan(&availUnits)
   202		if availUnits <= 0 {
   203			res.Reason = "insufficient_capacity"
   204			return res
   205		}
   206	
   207		res.Serviceable = true
   208		res.Reason = "serviceable"
   209		res.EstimatedArrivalISO = isoOf(arrival)
   210		return res
   211	}
