    11	
    12	// shortestPath computes minimal travel-time path over active connections between active locations.
    13	func (s *Server) shortestPath(ctx context.Context, from, to string) ([]edge, bool) {
    14		rows, err := s.DB.Query(ctx, `SELECT c.id, c.from_location_id, c.to_location_id, c.travel_minutes, c.cooled
    15			FROM connections c JOIN locations lf ON lf.id=c.from_location_id JOIN locations lt ON lt.id=c.to_location_id
    16			WHERE c.active=true AND lf.active=true AND lt.active=true`)
    17		if err != nil {
    18			return nil, false
    19		}
    20		adjacency := map[string][]edge{}
    21		for rows.Next() {
    22			var e edge
    23			_ = rows.Scan(&e.ConnectionID, &e.From, &e.To, &e.Minutes, &e.Cooled)
    24			adjacency[e.From] = append(adjacency[e.From], e)
    25		}
    26		rows.Close()
    27	
    28		if from == to {
    29			return []edge{}, true
    30		}
    31	
    32		dist := map[string]int{from: 0}
    33		prevEdge := map[string]edge{}
    34		visited := map[string]bool{}
    35		for {
    36			// pick unvisited node with min dist
    37			cur := ""
    38			best := -1
    39			for node, d := range dist {
    40				if visited[node] {
    41					continue
    42				}
    43				if best == -1 || d < best {
    44					best = d
    45					cur = node
    46				}
    47			}
    48			if cur == "" {
    49				break
    50			}
    51			if cur == to {
    52				break
    53			}
    54			visited[cur] = true
    55			for _, e := range adjacency[cur] {
    56				nd := dist[cur] + e.Minutes
    57				if old, ok := dist[e.To]; !ok || nd < old {
    58					dist[e.To] = nd
    59					prevEdge[e.To] = e
    60				}
    61			}
    62		}
    63		if _, ok := dist[to]; !ok {
    64			return nil, false
    65		}
    66		var path []edge
    67		cur := to
    68		for cur != from {
    69			e, ok := prevEdge[cur]
    70			if !ok {
    71				return nil, false
    72			}
    73			path = append([]edge{e}, path...)
    74			cur = e.From
    75		}
    76		return path, true
    77	}
