// assignmentRoleAllowed checks that the active role is compatible with the assignment kind.
func assignmentRoleAllowed(role, kind string) bool {
	switch kind {
	case "collection":
		return role == "collection_professional"
	case "transport":
		return role == "delivery_partner"
	case "node":
		return role == "node_handler"
	case "laboratory":
		return role == "laboratory_team"
	}
	return false
}

type acceptAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req acceptAssignmentReq
	if !readJSON(r, &req) || req.AssignmentID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "accept_assignment") {
		return
	}
	userID := userIDFrom(ctx)
	role := activeRoleFrom(ctx)

	var offeredWorker, kind, status string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(offered_worker_id::text,''), kind, status FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offeredWorker, &kind, &status)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if !assignmentRoleAllowed(role, kind) || offeredWorker != userID || status != "offered" {
		s.audit(ctx, userID, role, "accept_assignment", "assignment", req.AssignmentID, false, nil)
		writeErr(w, http.StatusBadRequest, "ineligible_worker", "")
		return
	}
	_, err = s.DB.Exec(ctx, `UPDATE assignments SET status='accepted', worker_id=$1, updated_at=now() WHERE id=$2`, userID, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, role, "accept_assignment", "assignment", req.AssignmentID, true, nil)
	s.emitEvent(ctx, "assignment_accepted", "assignment", req.AssignmentID, role, userID, map[string]interface{}{"assignmentId": req.AssignmentID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "accept_assignment", http.StatusCreated, map[string]interface{}{
		"assignmentId": req.AssignmentID, "workerId": userID, "status": "accepted",
	})
}

type declineAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	Reason         string `json:"reason"`
	DeclinedAt     string `json:"declinedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req declineAssignmentReq
	if !readJSON(r, &req) || req.AssignmentID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if req.DeclinedAt != "" {
		if _, ok := parseTime(req.DeclinedAt); !ok {
			writeErr(w, http.StatusBadRequest, "invalid_time", "")
			return
		}
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "decline_assignment") {
		return
	}
	userID := userIDFrom(ctx)
	role := activeRoleFrom(ctx)

	var offeredWorker, kind string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(offered_worker_id::text,''), kind FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offeredWorker, &kind)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if offeredWorker != userID {
		writeErr(w, http.StatusBadRequest, "ineligible_worker", "")
		return
	}
	_, err = s.DB.Exec(ctx, `UPDATE assignments SET status='pending', offered_worker_id=NULL, offer_expires_at=NULL,
		declined_worker_ids=array_append(declined_worker_ids,$1::uuid), updated_at=now() WHERE id=$2`, userID, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	_, _ = s.DB.Exec(ctx, `INSERT INTO worker_availability (worker_id, decline_count) VALUES ($1,1)
		ON CONFLICT (worker_id) DO UPDATE SET decline_count=worker_availability.decline_count+1,
		penalized_until=now() + interval '30 minutes'`, userID)

	reoffered := s.reofferAssignment(ctx, req.AssignmentID, kind)

	s.audit(ctx, userID, role, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
	s.emitEvent(ctx, "assignment_declined", "assignment", req.AssignmentID, role, "", map[string]interface{}{"assignmentId": req.AssignmentID})

	resp := map[string]interface{}{
		"assignmentId": req.AssignmentID, "status": "pending", "declinedBy": userID, "declinedAt": nowISO(),
	}
	if reoffered != "" {
		resp["reofferedTo"] = reoffered
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "decline_assignment", http.StatusCreated, resp)
}

// reofferAssignment attempts to offer the assignment to the next eligible worker, considering
// fairness (current workload) and any temporary decline-penalty.
func (s *Server) reofferAssignment(ctx context.KeyValue, assignmentID, kind string) string {
	return s.reofferAssignmentImpl(ctx, assignmentID, kind)
}

