// reofferAssignment attempts to offer the assignment to the next eligible, available worker,
// preferring workers with lower current workload and no active decline-penalty. Returns the
// worker ID offered to, or "" if none is currently eligible.
func (s *Server) reofferAssignment(ctx context.Context, assignmentID, kind string) string {
	role := requiredRoleForKind(kind)
	if role == "" {
		return ""
	}
	var reqQual *string
	var nodeID, labID string
	_ = s.DB.QueryRow(ctx, `SELECT required_qualification, coalesce(node_id::text,''), coalesce(laboratory_id::text,'') FROM assignments WHERE id=$1`, assignmentID).Scan(&reqQual, &nodeID, &labID)

	query := `SELECT u.id FROM users u
		JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
		LEFT JOIN worker_availability wa ON wa.worker_id=u.id
		WHERE u.active=true
		AND (wa.available IS NULL OR wa.available=true)
