    70	func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
    71		const R = 6371.0
    72		toRad := func(deg float64) float64 { return deg * math.Pi / 180 }
    73		dLat := toRad(lat2 - lat1)
    74		dLon := toRad(lon2 - lon1)
    75		a := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(toRad(lat1))*math.Cos(toRad(lat2))*math.Sin(dLon/2)*math.Sin(dLon/2)
    76		c := 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
    77		return R * c
    78	}
