	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "record_handling_checkpoint", http.StatusCreated, map[string]interface{}{
		"checkpointId": checkpointID, "sampleId": req.SampleID, "compliant": compliant, "sampleStatus": newStatus,
	})
