		return
	}
	var pendingCount int
	_ = s.DB.QueryRow(ctx, `SELECT count(*) FROM handoffs WHERE sample_id=$1 AND status='pending'`, req.SampleID).Scan(&pendingCount)
	if pendingCount > 0 {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "")
		return
	}
	if dl, ok := deadline.(interface{ Before(interface{}) bool }); ok {
		_ = dl
	}
	_, err = s.DB.Exec(ctx, `UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2, updated_at=now() WHERE id=$3`,
		req.LaboratoryID, receivedAt, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='completed', updated_at=now() WHERE kind='laboratory' AND sample_id=$1`, req.SampleID)
	var journeyID *string
	_ = s.DB.QueryRow(ctx, `SELECT active_journey_id::text FROM samples WHERE id=$1`, req.SampleID).Scan(&journeyID)
	if journeyID != nil {
		_, _ = s.DB.Exec(ctx, `UPDATE journeys SET status='completed', updated_at=now() WHERE id=$1`, *journeyID)
	}
	s.audit(ctx, userID, role, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	s.emitEvent(ctx, "sample_received", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "confirm_laboratory_receipt", http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "laboratoryId": req.LaboratoryID, "status": "received", "receivedAt": isoOf(receivedAt),
	})
}

