	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (s *Server) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	allowed := role == "collection_professional" || role == "delivery_partner" || role == "node_handler" || role == "laboratory_team"
	if !allowed {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req checkpointReq
	if !readJSON(r, &req) || req.SampleID == "" || req.AssignmentID == "" || req.ContainerType == "" || req.RecordedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	recordedAt, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "record_handling_checkpoint") {
		return
	}
	userID := userIDFrom(ctx)

	var holderID, sampleStatus, sampleTypeID string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(current_holder_id::text,''), status, sample_type_id FROM samples WHERE id=$1`, req.SampleID).
		Scan(&holderID, &sampleStatus, &sampleTypeID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if holderID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if sampleStatus == "received" || sampleStatus == "expired" || sampleStatus == "cancelled" {
		writeErr(w, http.StatusConflict, "terminal_sample", "")
		return
	}
	st, _ := s.loadSampleType(ctx, sampleTypeID)
	compliant := true
	if req.ContainerType != st.ContainerType || req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}
	checkpointID := uuid.NewString()
	_, err = s.DB.Exec(ctx, `INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant, recorded_by)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, checkpointID, req.SampleID, req.AssignmentID, nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, recordedAt, compliant, userID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	newStatus := sampleStatus
	if !compliant {
		newStatus = "exception"
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET status='exception', exception=$1, updated_at=now() WHERE id=$2`,
			[]byte(`{"reason":"handling_noncompliant"}`), req.SampleID)
	}
	s.audit(ctx, userID, role, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	if !compliant {
		s.emitEvent(ctx, "sample_exception", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID, "reason": "handling_noncompliant"})
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "record_handling_checkpoint", http.StatusCreated, map[string]interface{}{
		"checkpointId": checkpointID, "sampleId": req.SampleID, "compliant": compliant, "sampleStatus": newStatus,
	})
}

