	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "record_laboratory_exception", http.StatusCreated, map[string]interface{}{
		"exceptionId": exceptionID, "sampleId": req.SampleID, "status": "exception", "reason": req.Reason,
	})
