package api

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/google/uuid"
)

type collectSealReq struct {
	SampleID              string  `json:"sampleId"`
	AssignmentID          string  `json:"assignmentId"`
	CollectedAt           string  `json:"collectedAt"`
	ContainerType         string  `json:"containerType"`
	ObservedTemperatureC  float64 `json:"observedTemperatureC"`
	IdempotencyKey        string  `json:"idempotencyKey"`
}

func (s *Server) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	if role != "collection_professional" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req collectSealReq
	if !readJSON(r, &req) || req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" || req.ContainerType == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	collectedAt, ok := parseTime(req.CollectedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "collect_and_seal_sample") {
		return
	}
	userID := userIDFrom(ctx)

	var worker, status, sampleStatus, sampleTypeID string
	var earliestT, latestT *interface{}
	_ = earliestT
	_ = latestT
	err := s.DB.QueryRow(ctx, `SELECT coalesce(a.worker_id::text,''), a.status, s.status, s.sample_type_id FROM assignments a
		JOIN samples s ON s.id=a.sample_id WHERE a.id=$1 AND a.sample_id=$2 AND a.kind='collection'`, req.AssignmentID, req.SampleID).
		Scan(&worker, &status, &sampleStatus, &sampleTypeID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if worker != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if status != "accepted" && status != "in_progress" {
		writeErr(w, http.StatusConflict, "assignment_inactive", "")
		return
	}
	if sampleStatus != "requested" && sampleStatus != "collection_ready" {
		writeErr(w, http.StatusConflict, "invalid_sample_state", "")
		return
	}
	var earliest, latest *string
	_ = s.DB.QueryRow(ctx, `SELECT to_char(earliest_collection_at,'YYYY-MM-DD"T"HH24:MI:SS"Z"'), to_char(latest_collection_at,'YYYY-MM-DD"T"HH24:MI:SS"Z"')
		FROM requests r JOIN samples s ON s.request_id=r.id WHERE s.id=$1`, req.SampleID).Scan(&earliest, &latest)
	if earliest != nil && latest != nil {
		el, _ := parseTime(*earliest)
		ll, _ := parseTime(*latest)
		if collectedAt.Before(el) || collectedAt.After(ll) {
			writeErr(w, http.StatusConflict, "outside_collection_window", "")
			return
		}
	}

	st, _ := s.loadSampleType(ctx, sampleTypeID)
	compliant := true
	if req.ContainerType != st.ContainerType || req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}

	if req.QualificationRequired(st) {
		var qualified bool
		_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM user_qualifications WHERE user_id=$1 AND qualification=$2)`, userID, st.RequiredQualification).Scan(&qualified)
		if !qualified {
			writeErr(w, http.StatusConflict, "certification_inactive", "")
			return
		}
	}

	newStatus := "sealed"
	if !compliant {
		newStatus = "exception"
	}
	_, err = s.DB.Exec(ctx, `UPDATE samples SET status=$1, sealed=true, sealed_at=$2, current_holder_id=$3, updated_at=now() WHERE id=$4`,
		newStatus, collectedAt, userID, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	if !compliant {
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET exception=$1 WHERE id=$2`, []byte(`{"reason":"handling_noncompliant"}`), req.SampleID)
	}
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, req.AssignmentID)
	_, _ = s.DB.Exec(ctx, `INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, recorded_at, compliant, recorded_by)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, collectedAt, compliant, userID)

	s.audit(ctx, userID, role, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]interface{}{
		"assignmentId": req.AssignmentID, "compliant": compliant,
	})
	s.emitEvent(ctx, "sample_sealed", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID})

	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "collect_and_seal_sample", http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "status": "sealed", "currentHolderId": userID, "sealedAt": isoOf(collectedAt), "handlingCompliant": compliant,
	})
}

func (r collectSealReq) QualificationRequired(st sampleTypeInfo) bool {
	return st.QualifiedCollectorRequired && st.RequiredQualification != ""
}

type checkpointReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	LocationID           string  `json:"locationId"`
	ContainerType        string  `json:"containerType"`
