		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if _, ok := parseTime(req.ObservedAt); !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "record_laboratory_exception") {
		return
	}
	userID := userIDFrom(ctx)
	var assignedLoc *string
	_ = s.DB.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE id=$1`, userID).Scan(&assignedLoc)
	if assignedLoc == nil || *assignedLoc != req.LaboratoryID {
		writeErr(w, http.StatusForbidden, "wrong_laboratory_operator", "")
		return
	}
	var exists string
	err := s.DB.QueryRow(ctx, `SELECT id FROM samples WHERE id=$1`, req.SampleID).Scan(&exists)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	exceptionID := uuid.NewString()
	detail := map[string]interface{}{"reason": req.Reason, "exceptionId": exceptionID, "laboratoryId": req.LaboratoryID}
	b, _ := jsonMarshal(detail)
	_, err = s.DB.Exec(ctx, `UPDATE samples SET status='exception', exception=$1, updated_at=now() WHERE id=$2`, b, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, role, "record_laboratory_exception", "sample", req.SampleID, true, map[string]interface{}{"reason": req.Reason})
	s.emitEvent(ctx, "sample_exception", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID, "reason": req.Reason})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "record_laboratory_exception", http.StatusCreated, map[string]interface{}{
		"exceptionId": exceptionID, "sampleId": req.SampleID, "status": "exception", "reason": req.Reason,
	})
}

