package api

import (
	"encoding/json"
	"net/http"
	"time"

	"github.com/google/uuid"
)

type collectSealReq struct {
	SampleID              string  `json:"sampleId"`
	AssignmentID          string  `json:"assignmentId"`
	CollectedAt           string  `json:"collectedAt"`
	ContainerType         string  `json:"containerType"`
	ObservedTemperatureC  float64 `json:"observedTemperatureC"`
	IdempotencyKey        string  `json:"idempotencyKey"`
}

func (s *Server) CollectAndSealSample(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	if role != "collection_professional" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req collectSealReq
	if !readJSON(r, &req) || req.SampleID == "" || req.AssignmentID == "" || req.CollectedAt == "" || req.ContainerType == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	collectedAt, ok := parseTime(req.CollectedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "collect_and_seal_sample") {
		return
	}
	userID := userIDFrom(ctx)

	var worker, status, sampleStatus, sampleTypeID string
	var earliestT, latestT *interface{}
	_ = earliestT
	_ = latestT
	err := s.DB.QueryRow(ctx, `SELECT coalesce(a.worker_id::text,''), a.status, s.status, s.sample_type_id FROM assignments a
		JOIN samples s ON s.id=a.sample_id WHERE a.id=$1 AND a.sample_id=$2 AND a.kind='collection'`, req.AssignmentID, req.SampleID).
		Scan(&worker, &status, &sampleStatus, &sampleTypeID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if worker != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if status != "accepted" && status != "in_progress" {
		writeErr(w, http.StatusConflict, "assignment_inactive", "")
		return
	}
	if sampleStatus != "requested" && sampleStatus != "collection_ready" {
		writeErr(w, http.StatusConflict, "invalid_sample_state", "")
		return
	}
	var earliest, latest *string
	_ = s.DB.QueryRow(ctx, `SELECT to_char(earliest_collection_at,'YYYY-MM-DD"T"HH24:MI:SS"Z"'), to_char(latest_collection_at,'YYYY-MM-DD"T"HH24:MI:SS"Z"')
		FROM requests r JOIN samples s ON s.request_id=r.id WHERE s.id=$1`, req.SampleID).Scan(&earliest, &latest)
	if earliest != nil && latest != nil {
		el, _ := parseTime(*earliest)
		ll, _ := parseTime(*latest)
		if collectedAt.Before(el) || collectedAt.After(ll) {
			writeErr(w, http.StatusConflict, "outside_collection_window", "")
			return
		}
	}

	st, _ := s.loadSampleType(ctx, sampleTypeID)
	compliant := true
	if req.ContainerType != st.ContainerType || req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}

	if req.QualificationRequired(st) {
		var qualified bool
		_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM user_qualifications WHERE user_id=$1 AND qualification=$2)`, userID, st.RequiredQualification).Scan(&qualified)
		if !qualified {
			writeErr(w, http.StatusConflict, "certification_inactive", "")
			return
		}
	}

	newStatus := "sealed"
	if !compliant {
		newStatus = "exception"
	}
	_, err = s.DB.Exec(ctx, `UPDATE samples SET status=$1, sealed=true, sealed_at=$2, current_holder_id=$3, updated_at=now() WHERE id=$4`,
		newStatus, collectedAt, userID, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	if !compliant {
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET exception=$1 WHERE id=$2`, []byte(`{"reason":"handling_noncompliant"}`), req.SampleID)
	}
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='completed', updated_at=now() WHERE id=$1`, req.AssignmentID)
	_, _ = s.DB.Exec(ctx, `INSERT INTO handling_checkpoints (sample_id, assignment_id, container_type, observed_temperature_c, recorded_at, compliant, recorded_by)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`, req.SampleID, req.AssignmentID, req.ContainerType, req.ObservedTemperatureC, collectedAt, compliant, userID)

	s.audit(ctx, userID, role, "collect_and_seal_sample", "sample", req.SampleID, true, map[string]interface{}{
		"assignmentId": req.AssignmentID, "compliant": compliant,
	})
	s.emitEvent(ctx, "sample_sealed", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID})

	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "collect_and_seal_sample", http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "status": "sealed", "currentHolderId": userID, "sealedAt": isoOf(collectedAt), "handlingCompliant": compliant,
	})
}

func (r collectSealReq) QualificationRequired(st sampleTypeInfo) bool {
	return st.QualifiedCollectorRequired && st.RequiredQualification != ""
}

type checkpointReq struct {
	SampleID             string  `json:"sampleId"`
	AssignmentID         string  `json:"assignmentId"`
	LocationID           string  `json:"locationId"`
	ContainerType        string  `json:"containerType"`
	ObservedTemperatureC float64 `json:"observedTemperatureC"`
	RecordedAt           string  `json:"recordedAt"`
	IdempotencyKey       string  `json:"idempotencyKey"`
}

func (s *Server) RecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	allowed := role == "collection_professional" || role == "delivery_partner" || role == "node_handler" || role == "laboratory_team"
	if !allowed {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req checkpointReq
	if !readJSON(r, &req) || req.SampleID == "" || req.AssignmentID == "" || req.ContainerType == "" || req.RecordedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	recordedAt, ok := parseTime(req.RecordedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "record_handling_checkpoint") {
		return
	}
	userID := userIDFrom(ctx)

	var holderID, sampleStatus, sampleTypeID string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(current_holder_id::text,''), status, sample_type_id FROM samples WHERE id=$1`, req.SampleID).
		Scan(&holderID, &sampleStatus, &sampleTypeID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if holderID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if sampleStatus == "received" || sampleStatus == "expired" || sampleStatus == "cancelled" {
		writeErr(w, http.StatusConflict, "terminal_sample", "")
		return
	}
	st, _ := s.loadSampleType(ctx, sampleTypeID)
	compliant := true
	if req.ContainerType != st.ContainerType || req.ObservedTemperatureC < st.TemperatureMinC || req.ObservedTemperatureC > st.TemperatureMaxC {
		compliant = false
	}
	checkpointID := uuid.NewString()
	_, err = s.DB.Exec(ctx, `INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, recorded_at, compliant, recorded_by)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, checkpointID, req.SampleID, req.AssignmentID, nilIfEmpty(req.LocationID), req.ContainerType, req.ObservedTemperatureC, recordedAt, compliant, userID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	newStatus := sampleStatus
	if !compliant {
		newStatus = "exception"
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET status='exception', exception=$1, updated_at=now() WHERE id=$2`,
			[]byte(`{"reason":"handling_noncompliant"}`), req.SampleID)
	}
	s.audit(ctx, userID, role, "record_handling_checkpoint", "sample", req.SampleID, true, map[string]interface{}{"compliant": compliant})
	if !compliant {
		s.emitEvent(ctx, "sample_exception", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID, "reason": "handling_noncompliant"})
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "record_handling_checkpoint", http.StatusCreated, map[string]interface{}{
		"checkpointId": checkpointID, "sampleId": req.SampleID, "compliant": compliant, "sampleStatus": newStatus,
	})
}

type initiateHandoffReq struct {
	SampleID        string `json:"sampleId"`
	FromAssignmentID string `json:"fromAssignmentId"`
	ToAssignmentID   string `json:"toAssignmentId"`
	ReceiverID       string `json:"receiverId"`
	InitiatedAt      string `json:"initiatedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (s *Server) InitiateHandoff(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req initiateHandoffReq
	if !readJSON(r, &req) || req.SampleID == "" || req.ReceiverID == "" || req.InitiatedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	initiatedAt, ok := parseTime(req.InitiatedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "initiate_handoff") {
		return
	}
	userID := userIDFrom(ctx)

	var holderID string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(current_holder_id::text,'') FROM samples WHERE id=$1`, req.SampleID).Scan(&holderID)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if holderID != userID {
		writeErr(w, http.StatusForbidden, "not_current_holder", "")
		return
	}
	var pendingCount int
	_ = s.DB.QueryRow(ctx, `SELECT count(*) FROM handoffs WHERE sample_id=$1 AND status='pending'`, req.SampleID).Scan(&pendingCount)
	if pendingCount > 0 {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "")
		return
	}
	handoffID := uuid.NewString()
	_, err = s.DB.Exec(ctx, `INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, initiated_at)
		VALUES ($1,$2,$3,$4,$5,$6,'pending',$7)`, handoffID, req.SampleID, nilIfEmpty(req.FromAssignmentID), nilIfEmpty(req.ToAssignmentID), userID, req.ReceiverID, initiatedAt)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, role, "initiate_handoff", "handoff", handoffID, true, map[string]interface{}{"sampleId": req.SampleID, "receiverId": req.ReceiverID})
	s.emitEvent(ctx, "handoff_initiated", "handoff", handoffID, "", req.ReceiverID, map[string]interface{}{"sampleId": req.SampleID, "handoffId": handoffID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "initiate_handoff", http.StatusCreated, map[string]interface{}{
		"handoffId": handoffID, "senderId": userID, "receiverId": req.ReceiverID, "currentHolderId": holderID, "status": "pending",
	})
}

type confirmHandoffReq struct {
	HandoffID        string `json:"handoffId"`
	ConfirmationSide string `json:"confirmationSide"`
	ConfirmedAt      string `json:"confirmedAt"`
	IdempotencyKey   string `json:"idempotencyKey"`
}

func (s *Server) ConfirmHandoff(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req confirmHandoffReq
	if !readJSON(r, &req) || req.HandoffID == "" || req.ConfirmedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, http.StatusBadRequest, "invalid_confirmation_side", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	confirmedAt, ok := parseTime(req.ConfirmedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "confirm_handoff") {
		return
	}
	userID := userIDFrom(ctx)

	var sampleID, senderID, receiverID, status string
	var senderConfirmed, receiverConfirmed bool
	err := s.DB.QueryRow(ctx, `SELECT sample_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, req.HandoffID).
		Scan(&sampleID, &senderID, &receiverID, &status, &senderConfirmed, &receiverConfirmed)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if status != "pending" {
		writeErr(w, http.StatusConflict, "handoff_inactive", "")
		return
	}
	if req.ConfirmationSide == "sender" && userID != senderID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if req.ConfirmationSide == "receiver" && userID != receiverID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	if req.ConfirmationSide == "sender" {
		senderConfirmed = true
	} else {
		receiverConfirmed = true
	}
	newStatus := "pending"
	holderID := senderID
	if senderConfirmed && receiverConfirmed {
		newStatus = "confirmed"
		holderID = receiverID
	}
	_, err = s.DB.Exec(ctx, `UPDATE handoffs SET sender_confirmed=$1, receiver_confirmed=$2, status=$3, confirmed_at=$4 WHERE id=$5`,
		senderConfirmed, receiverConfirmed, newStatus, confirmedIfDone(newStatus, confirmedAt), req.HandoffID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	if newStatus == "confirmed" {
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET current_holder_id=$1, updated_at=now() WHERE id=$2`, holderID, sampleID)
	}
	s.audit(ctx, userID, role, "confirm_handoff", "handoff", req.HandoffID, true, map[string]interface{}{"side": req.ConfirmationSide, "status": newStatus})
	if newStatus == "confirmed" {
		s.emitEvent(ctx, "handoff_confirmed", "handoff", req.HandoffID, "", "", map[string]interface{}{"sampleId": sampleID, "handoffId": req.HandoffID})
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "confirm_handoff", http.StatusCreated, map[string]interface{}{
		"handoffId": req.HandoffID, "status": newStatus, "senderConfirmed": senderConfirmed, "receiverConfirmed": receiverConfirmed, "currentHolderId": holderID,
	})
}

func confirmedIfDone(status string, t time.Time) interface{} {
	if status == "confirmed" {
		return t
	}
	return nil
}

type labReceiptReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	ReceivedAt     string `json:"receivedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) ConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	if role != "laboratory_team" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req labReceiptReq
	if !readJSON(r, &req) || req.SampleID == "" || req.LaboratoryID == "" || req.ReceivedAt == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	receivedAt, ok := parseTime(req.ReceivedAt)
	if !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "confirm_laboratory_receipt") {
		return
	}
	userID := userIDFrom(ctx)

	var assignedLoc *string
	_ = s.DB.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE id=$1`, userID).Scan(&assignedLoc)
	if assignedLoc == nil || *assignedLoc != req.LaboratoryID {
		writeErr(w, http.StatusForbidden, "wrong_laboratory_operator", "")
		return
	}
	var holderID, sampleStatus, targetLab string
	var deadline interface{}
	err := s.DB.QueryRow(ctx, `SELECT coalesce(current_holder_id::text,''), status, coalesce(target_laboratory_id::text,''), delivery_deadline
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, req.SampleID).
		Scan(&holderID, &sampleStatus, &targetLab, &deadline)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if holderID != userID {
		writeErr(w, http.StatusConflict, "custody_conflict", "")
		return
	}
	var pendingCount int
	_ = s.DB.QueryRow(ctx, `SELECT count(*) FROM handoffs WHERE sample_id=$1 AND status='pending'`, req.SampleID).Scan(&pendingCount)
	if pendingCount > 0 {
		writeErr(w, http.StatusConflict, "pending_handoff_exists", "")
		return
	}
	if dl, ok := deadline.(interface{ Before(interface{}) bool }); ok {
		_ = dl
	}
	_, err = s.DB.Exec(ctx, `UPDATE samples SET status='received', received_laboratory_id=$1, received_at=$2, updated_at=now() WHERE id=$3`,
		req.LaboratoryID, receivedAt, req.SampleID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='completed', updated_at=now() WHERE kind='laboratory' AND sample_id=$1`, req.SampleID)
	var journeyID *string
	_ = s.DB.QueryRow(ctx, `SELECT active_journey_id::text FROM samples WHERE id=$1`, req.SampleID).Scan(&journeyID)
	if journeyID != nil {
		_, _ = s.DB.Exec(ctx, `UPDATE journeys SET status='completed', updated_at=now() WHERE id=$1`, *journeyID)
	}
	s.audit(ctx, userID, role, "confirm_laboratory_receipt", "sample", req.SampleID, true, map[string]interface{}{"laboratoryId": req.LaboratoryID})
	s.emitEvent(ctx, "sample_received", "sample", req.SampleID, "dispatcher", "", map[string]interface{}{"sampleId": req.SampleID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "confirm_laboratory_receipt", http.StatusCreated, map[string]interface{}{
		"sampleId": req.SampleID, "laboratoryId": req.LaboratoryID, "status": "received", "receivedAt": isoOf(receivedAt),
	})
}

type labExceptionReq struct {
	SampleID       string `json:"sampleId"`
	LaboratoryID   string `json:"laboratoryId"`
	Reason         string `json:"reason"`
	ObservedAt     string `json:"observedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
