}

func (s *Server) SetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if activeRoleFrom(ctx) == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req setWorkerAvailabilityReq
	if !readJSON(r, &req) || req.WorkerID == "" || req.Available == nil || req.CapacityUnits == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if *req.CapacityUnits < 0 {
		writeErr(w, http.StatusBadRequest, "invalid_capacity", "")
		return
	}
	userID := userIDFrom(ctx)
	role := activeRoleFrom(ctx)
	if userID != req.WorkerID && role != "administrator" && role != "dispatcher" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var exists string
	err := s.DB.QueryRow(ctx, `SELECT id FROM users WHERE id=$1`, req.WorkerID).Scan(&exists)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	_, err = s.DB.Exec(ctx, `INSERT INTO worker_availability (worker_id, available, capacity_units) VALUES ($1,$2,$3)
		ON CONFLICT (worker_id) DO UPDATE SET available=$2, capacity_units=$3`, req.WorkerID, *req.Available, *req.CapacityUnits)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, role, "set_worker_availability", "worker", req.WorkerID, true, map[string]interface{}{"available": *req.Available, "capacityUnits": *req.CapacityUnits})
	writeData(w, http.StatusOK, map[string]interface{}{"workerId": req.WorkerID, "available": *req.Available, "capacityUnits": *req.CapacityUnits})
}

type updateProgressReq struct {
	AssignmentID   string `json:"assignmentId"`
	Status         string `json:"status"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

var validProgressStatuses = map[string]bool{
	"at_pickup": true, "picked_up": true, "in_transit": true, "arrived": true, "delivered": true, "in_progress": true, "completed": true,
}

func (s *Server) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req updateProgressReq
	if !readJSON(r, &req) || req.AssignmentID == "" || !validProgressStatuses[req.Status] {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if _, ok := parseTime(req.OccurredAt); !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "update_assignment_progress") {
		return
	}
	userID := userIDFrom(ctx)

	var worker, kind, sampleID, curStatus string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(worker_id::text,''), kind, sample_id::text, status FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&worker, &kind, &sampleID, &curStatus)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if worker != userID || !assignmentRoleAllowed(role, kind) {
		writeErr(w, http.StatusForbidden, "ineligible_worker", "")
		return
	}
	if curStatus != "accepted" && curStatus != "in_progress" {
		writeErr(w, http.StatusConflict, "assignment_inactive", "")
		return
	}
	newAssignmentStatus := "in_progress"
	if req.Status == "delivered" || req.Status == "completed" {
		newAssignmentStatus = "completed"
	}
	_, err = s.DB.Exec(ctx, `UPDATE assignments SET status=$1, updated_at=now() WHERE id=$2`, newAssignmentStatus, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, role, "update_assignment_progress", "assignment", req.AssignmentID, true, map[string]interface{}{"status": req.Status})
	s.emitEvent(ctx, "assignment_progress", "assignment", req.AssignmentID, "dispatcher", "", map[string]interface{}{"assignmentId": req.AssignmentID, "status": req.Status})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "update_assignment_progress", http.StatusCreated, map[string]interface{}{
		"assignmentId": req.AssignmentID, "sampleId": sampleID, "status": req.Status,
	})
}

