package api

import (
	"context"
	"fmt"
	"net/http"
	"time"
)

// assignmentRoleAllowed checks that the active role is compatible with the assignment kind.
func assignmentRoleAllowed(role, kind string) bool {
	switch kind {
	case "collection":
		return role == "collection_professional"
	case "transport":
		return role == "delivery_partner"
	case "node":
		return role == "node_handler"
	case "laboratory":
		return role == "laboratory_team"
	}
	return false
}

type acceptAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) AcceptAssignment(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req acceptAssignmentReq
	if !readJSON(r, &req) || req.AssignmentID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "accept_assignment") {
		return
	}
	userID := userIDFrom(ctx)

	var offeredWorker, kind, status string
	var offerExpires *time.Time
	err := s.DB.QueryRow(ctx, `SELECT coalesce(offered_worker_id::text,''), kind, status, offer_expires_at FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offeredWorker, &kind, &status, &offerExpires)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if offerExpires != nil && offerExpires.Before(timeNow()) && status == "offered" {
		s.reofferAssignment(ctx, req.AssignmentID, kind)
		writeErr(w, http.StatusConflict, "offer_not_available", "")
		return
	}
	if !assignmentRoleAllowed(role, kind) || offeredWorker != userID || status != "offered" {
		s.audit(ctx, userID, role, "accept_assignment", "assignment", req.AssignmentID, false, nil)
		writeErr(w, http.StatusBadRequest, "ineligible_worker", "")
		return
	}
	_, err = s.DB.Exec(ctx, `UPDATE assignments SET status='accepted', worker_id=$1, updated_at=now() WHERE id=$2`, userID, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	s.audit(ctx, userID, role, "accept_assignment", "assignment", req.AssignmentID, true, nil)
	s.emitEvent(ctx, "assignment_accepted", "assignment", req.AssignmentID, role, userID, map[string]interface{}{"assignmentId": req.AssignmentID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "accept_assignment", http.StatusCreated, map[string]interface{}{
		"assignmentId": req.AssignmentID, "workerId": userID, "status": "accepted",
	})
}

type declineAssignmentReq struct {
	AssignmentID   string `json:"assignmentId"`
	Reason         string `json:"reason"`
	DeclinedAt     string `json:"declinedAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

func (s *Server) DeclineAssignment(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	if activeRoleFrom(ctx) == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req declineAssignmentReq
	if !readJSON(r, &req) || req.AssignmentID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if req.DeclinedAt != "" {
		if _, ok := parseTime(req.DeclinedAt); !ok {
			writeErr(w, http.StatusBadRequest, "invalid_time", "")
			return
		}
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "decline_assignment") {
		return
	}
	userID := userIDFrom(ctx)
	role := activeRoleFrom(ctx)

	var offeredWorker, kind string
	err := s.DB.QueryRow(ctx, `SELECT coalesce(offered_worker_id::text,''), kind FROM assignments WHERE id=$1`, req.AssignmentID).
		Scan(&offeredWorker, &kind)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if offeredWorker != userID {
		writeErr(w, http.StatusBadRequest, "ineligible_worker", "")
		return
	}
	_, err = s.DB.Exec(ctx, `UPDATE assignments SET status='pending', offered_worker_id=NULL, offer_expires_at=NULL,
		declined_worker_ids=array_append(declined_worker_ids,$1::uuid), updated_at=now() WHERE id=$2`, userID, req.AssignmentID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	_, _ = s.DB.Exec(ctx, `INSERT INTO worker_availability (worker_id, decline_count) VALUES ($1,1)
		ON CONFLICT (worker_id) DO UPDATE SET decline_count=worker_availability.decline_count+1,
		penalized_until=now() + interval '30 minutes'`, userID)

	reoffered := s.reofferAssignment(ctx, req.AssignmentID, kind)

	s.audit(ctx, userID, role, "decline_assignment", "assignment", req.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
	s.emitEvent(ctx, "assignment_declined", "assignment", req.AssignmentID, role, "", map[string]interface{}{"assignmentId": req.AssignmentID})

	resp := map[string]interface{}{
		"assignmentId": req.AssignmentID, "status": "pending", "declinedBy": userID, "declinedAt": nowISO(),
	}
	if reoffered != "" {
		resp["reofferedTo"] = reoffered
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "decline_assignment", http.StatusCreated, resp)
}

// requiredRoleForKind maps an assignment kind to the role eligible to hold it.
func requiredRoleForKind(kind string) string {
	switch kind {
	case "collection":
		return "collection_professional"
	case "transport":
		return "delivery_partner"
	case "node":
		return "node_handler"
	case "laboratory":
		return "laboratory_team"
	}
	return ""
}

// reofferAssignment attempts to offer the assignment to the next eligible, available worker,
// preferring workers with lower current workload and no active decline-penalty. Returns the
// worker ID offered to, or "" if none is currently eligible.
func (s *Server) reofferAssignment(ctx context.Context, assignmentID, kind string) string {
	role := requiredRoleForKind(kind)
	if role == "" {
		return ""
	}
	var reqQual *string
	var nodeID, labID string
	_ = s.DB.QueryRow(ctx, `SELECT required_qualification, coalesce(node_id::text,''), coalesce(laboratory_id::text,'') FROM assignments WHERE id=$1`, assignmentID).Scan(&reqQual, &nodeID, &labID)

	query := `SELECT u.id FROM users u
		JOIN user_roles ur ON ur.user_id=u.id AND ur.role=$1
		LEFT JOIN worker_availability wa ON wa.worker_id=u.id
		WHERE u.active=true
		AND (wa.available IS NULL OR wa.available=true)
		AND NOT (u.id = ANY(SELECT unnest(declined_worker_ids) FROM assignments WHERE id=$2))`
	args := []interface{}{role, assignmentID}
	if reqQual != nil && *reqQual != "" {
		query += ` AND EXISTS (SELECT 1 FROM user_qualifications q WHERE q.user_id=u.id AND q.qualification=$3)`
		args = append(args, *reqQual)
	}
	if kind == "node" && nodeID != "" {
		query += fmt.Sprintf(` AND u.assigned_location_id=$%d`, len(args)+1)
		args = append(args, nodeID)
	}
	if kind == "laboratory" && labID != "" {
		query += fmt.Sprintf(` AND u.assigned_location_id=$%d`, len(args)+1)
		args = append(args, labID)
	}
	query += ` ORDER BY (wa.penalized_until IS NOT NULL AND wa.penalized_until > now()) ASC,
		(SELECT count(*) FROM assignments a2 WHERE a2.worker_id=u.id AND a2.status IN ('accepted','in_progress')) ASC,
		u.id ASC LIMIT 1`

	var workerID string
	err := s.DB.QueryRow(ctx, query, args...).Scan(&workerID)
	if err != nil {
		// no eligible worker found
		_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='exception', updated_at=now() WHERE id=$1`, assignmentID)
		var sampleID string
		_ = s.DB.QueryRow(ctx, `SELECT sample_id FROM assignments WHERE id=$1`, assignmentID).Scan(&sampleID)
		if sampleID != "" {
			_, _ = s.DB.Exec(ctx, `UPDATE samples SET exception=$1, updated_at=now() WHERE id=$2`,
				[]byte(`{"reason":"no_qualified_worker_available"}`), sampleID)
			s.emitEvent(ctx, "sample_exception", "sample", sampleID, "dispatcher", "", map[string]interface{}{
				"assignmentId": assignmentID, "reason": "no_qualified_worker_available",
			})
		}
		return ""
	}
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='offered', offered_worker_id=$1, offer_expires_at=now() + interval '5 minutes', updated_at=now() WHERE id=$2`, workerID, assignmentID)
	s.emitEvent(ctx, "assignment_offered", "assignment", assignmentID, role, workerID, map[string]interface{}{"assignmentId": assignmentID})
	return workerID
}

