	s.audit(ctx, userID, role, "record_worker_location", "assignment", req.AssignmentID, true, map[string]interface{}{"sequence": *req.Sequence})
	s.emitEvent(ctx, "worker_location", "worker", userID, "dispatcher", "", map[string]interface{}{
