   154	func (s *Server) ConfigureCapacity(w http.ResponseWriter, r *http.Request) {
   155		ctx := r.Context()
   156		role := activeRoleFrom(ctx)
   157		if role != "administrator" && role != "node_handler" && role != "laboratory_team" {
   158			writeErr(w, http.StatusForbidden, "forbidden", "")
   159			return
   160		}
   161		var req struct {
   162			ResourceID          string `json:"resourceId"`
   163			CapacityUnits       *int   `json:"capacityUnits"`
   164			CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
   165		}
   166		if !readJSON(r, &req) || req.ResourceID == "" || req.CapacityUnits == nil {
   167			writeErr(w, http.StatusBadRequest, "invalid_json", "")
   168			return
   169		}
   170		if *req.CapacityUnits < 0 {
   171			writeErr(w, http.StatusBadRequest, "invalid_capacity", "")
   172			return
   173		}
   174		cooled := 0
   175		if req.CooledCapacityUnits != nil {
   176			cooled = *req.CooledCapacityUnits
   177		}
   178		// Non-admin roles may only configure capacity at their assigned location.
   179		if role == "node_handler" || role == "laboratory_team" {
   180			var assignedID *string
   181			_ = s.DB.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE id=$1`, userIDFrom(ctx)).Scan(&assignedID)
   182			if assignedID == nil || *assignedID != req.ResourceID {
   183				writeErr(w, http.StatusForbidden, "forbidden", "")
   184				return
   185			}
   186		}
   187		// try location first, then connection
   188		tag, err := s.DB.Exec(ctx, `UPDATE locations SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3 AND reserved_units<=$1 AND cooled_reserved_units<=$2`, *req.CapacityUnits, cooled, req.ResourceID)
   189		if err == nil && tag.RowsAffected() > 0 {
   190			s.audit(ctx, userIDFrom(ctx), role, "configure_capacity", "location", req.ResourceID, true, nil)
   191			writeData(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
   192			return
   193		}
   194		var locExists bool
   195		_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM locations WHERE id=$1)`, req.ResourceID).Scan(&locExists)
   196		if locExists {
   197			writeErr(w, http.StatusConflict, "capacity_reserved", "")
   198			return
   199		}
   200		tag2, err2 := s.DB.Exec(ctx, `UPDATE connections SET capacity_units=$1, cooled_capacity_units=$2, updated_at=now() WHERE id=$3 AND reserved_units<=$1 AND cooled_reserved_units<=$2`, *req.CapacityUnits, cooled, req.ResourceID)
   201		if err2 == nil && tag2.RowsAffected() > 0 {
   202			s.audit(ctx, userIDFrom(ctx), role, "configure_capacity", "connection", req.ResourceID, true, nil)
   203			writeData(w, http.StatusOK, map[string]interface{}{"resourceId": req.ResourceID, "capacityUnits": *req.CapacityUnits, "cooledCapacityUnits": cooled})
   204			return
   205		}
   206		var connExists bool
   207		_ = s.DB.QueryRow(ctx, `SELECT EXISTS(SELECT 1 FROM connections WHERE id=$1)`, req.ResourceID).Scan(&connExists)
   208		if connExists {
   209			writeErr(w, http.StatusConflict, "capacity_reserved", "")
   210			return
   211		}
   212		writeErr(w, http.StatusBadRequest, "invalid_capacity", "resource not found")
   213	}
