package api

import (
	"context"
	"net/http"
	"strings"
)

func (s *Server) sampleTimeline(ctx context.Context, sampleID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, action, coalesce(actor_id::text,''), coalesce(role,''), entity_type, entity_id, success, occurred_at, details
		FROM audit_log WHERE entity_id=$1 ORDER BY occurred_at ASC`, sampleID)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var action, actorID, role, entityType, entityID string
		var success bool
		var occurredAt interface{}
		var details []byte
		_ = rows.Scan(&id, &action, &actorID, &role, &entityType, &entityID, &success, &occurredAt, &details)
		out = append(out, map[string]interface{}{
			"eventId": id, "action": action, "actorId": actorID, "role": role,
			"entityType": entityType, "entityId": entityID, "success": success,
			"occurredAt": isoOrInterface(occurredAt), "details": jsonBytesToMap(details),
		})
	}
	return out
}

func isoOrInterface(v interface{}) interface{} {
	if t, ok := v.(interface{ String() string }); ok {
		return t.String()
	}
	return v
}

func jsonBytesToMap(b []byte) map[string]interface{} {
	out := map[string]interface{}{}
	if len(b) == 0 {
		return out
	}
	_ = decodeJSON(b, &out)
	return out
}

func (s *Server) ReadSampleState(w http.ResponseWriter, r *http.Request, sampleID string) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	userID := userIDFrom(ctx)

	var requesterID, sampleTypeID, status, containerType string
	var tempMin, tempMax float64
	var originLat, originLng float64
	var originType string
	var requestedAt, deadline interface{}
	var activeJourney, targetLab *string
	var lat, lng *float64
	var locRecordedAt interface{}
	var requestID string
	err := s.DB.QueryRow(ctx, `SELECT s.request_id, coalesce(s.requester_id::text,''), s.sample_type_id, s.status, r.container_type,
		r.temperature_min_c, r.temperature_max_c, r.origin_latitude, r.origin_longitude, r.origin_type, r.requested_at, r.delivery_deadline,
		s.active_journey_id::text, coalesce(s.target_laboratory_id::text,''), s.latest_latitude, s.latest_longitude, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&requestID, &requesterID, &sampleTypeID, &status, &containerType, &tempMin, &tempMax, &originLat, &originLng, &originType,
			&requestedAt, &deadline, &activeJourney, &targetLab, &lat, &lng, &locRecordedAt)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if role == "requester" && requesterID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	incompat := s.fetchIncompatibleTypes(ctx, sampleTypeID)
	timeline := s.sampleTimeline(ctx, sampleID)
	stale := isStale(locRecordedAt)

	serviceability := "serviceable"
	resp := map[string]interface{}{
		"sampleId": sampleID, "requestId": requestID, "requesterId": requesterID,
		"origin": map[string]interface{}{"latitude": originLat, "longitude": originLng},
		"originType": originType, "requestedAt": isoOrInterface(requestedAt), "deliveryDeadline": isoOrInterface(deadline),
		"sampleTypeId": sampleTypeID, "containerType": containerType, "temperatureMinC": tempMin, "temperatureMaxC": tempMax,
		"incompatibleSampleTypes": incompat, "serviceability": serviceability,
		"activeAssignmentIds": s.fetchActiveAssignmentIDs(ctx, sampleID),
		"state": map[string]interface{}{"status": status},
		"timeline": timeline, "locationStale": stale,
	}
	if activeJourney != nil {
		resp["activeJourneyId"] = *activeJourney
	}
	if targetLab != nil && *targetLab != "" {
		resp["targetLaboratoryId"] = *targetLab
	}
	if lat != nil && lng != nil {
		resp["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
	}
	if locRecordedAt != nil {
		resp["locationRecordedAt"] = isoOrInterface(locRecordedAt)
	}
	writeData(w, http.StatusOK, resp)
}

func isStale(recordedAt interface{}) bool {
	t, ok := recordedAt.(interface{ Before(u interface{ Before(interface{}) bool }) bool })
	_ = t
	_ = ok
	return staleFromRaw(recordedAt)
}

