type readSampleLifecycleReq struct {
	SampleID string `json:"sampleId"`
}

func (s *Server) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	userID := userIDFrom(ctx)
	var req readSampleLifecycleReq
	if !readJSON(r, &req) || req.SampleID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	var requesterID, status string
	var sealed bool
	var activeJourney, holderID, receivedLab *string
	var exception []byte
	err := s.DB.QueryRow(ctx, `SELECT coalesce(requester_id::text,''), status, sealed, active_journey_id::text, current_holder_id::text, received_laboratory_id::text, exception FROM samples WHERE id=$1`, req.SampleID).
		Scan(&requesterID, &status, &sealed, &activeJourney, &holderID, &receivedLab, &exception)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if role == "requester" && requesterID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	completedLegs := s.fetchCompletedLegIDs(ctx, req.SampleID)
	timeline := s.sampleTimeline(ctx, req.SampleID)
	var lat, lng *float64
	var locRecordedAt interface{}
	_ = s.DB.QueryRow(ctx, `SELECT latest_latitude, latest_longitude, location_recorded_at FROM samples WHERE id=$1`, req.SampleID).Scan(&lat, &lng, &locRecordedAt)

	resp := map[string]interface{}{
		"sampleId": req.SampleID, "status": status, "sealed": sealed,
		"completedLegIds": completedLegs, "activeReplacementPlanIds": []string{},
		"timeline": timeline, "locationStale": staleFromRaw(locRecordedAt),
	}
	if activeJourney != nil {
		resp["activeJourneyId"] = *activeJourney
	}
	if holderID != nil {
		resp["currentHolderId"] = *holderID
	}
	if receivedLab != nil {
		resp["receivedLaboratoryId"] = *receivedLab
	}
	if len(exception) > 0 {
		resp["exception"] = jsonBytesToMap(exception)
	}
	var pendingHandoffID string
	_ = s.DB.QueryRow(ctx, `SELECT id::text FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, req.SampleID).Scan(&pendingHandoffID)
	if pendingHandoffID != "" {
		resp["pendingHandoffId"] = pendingHandoffID
	}
	if lat != nil && lng != nil {
		resp["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
	}
	if locRecordedAt != nil {
		resp["locationRecordedAt"] = isoOrInterface(locRecordedAt)
	}
	writeData(w, http.StatusOK, resp)
}

