type listRoleWorkReq struct {
	Role   string `json:"role"`
	Status string `json:"status"`
}

func (s *Server) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	activeRole := activeRoleFrom(ctx)
	if activeRole == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req listRoleWorkReq
	_ = readJSON(r, &req)
	if req.Role != "" && req.Role != activeRole {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	userID := userIDFrom(ctx)
	pending, inProgress, completed := s.buildRoleWork(ctx, activeRole, userID)
	writeData(w, http.StatusOK, map[string]interface{}{
		"pending": pending, "inProgress": inProgress, "completed": completed,
	})
}

func (s *Server) buildRoleWork(ctx context.Context, role, userID string) ([]map[string]interface{}, []map[string]interface{}, []map[string]interface{}) {
	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	if role == "requester" {
		rows, err := s.DB.Query(ctx, `SELECT id::text, status FROM samples WHERE requester_id=$1`, userID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status string
				_ = rows.Scan(&id, &status)
				item := map[string]interface{}{"kind": "sample", "sampleId": id, "status": status, "history": s.sampleTimeline(ctx, id), "locationStale": false}
				if status == "received" || status == "cancelled" || status == "expired" {
					completed = append(completed, item)
				} else {
					inProgress = append(inProgress, item)
				}
			}
		}
		return pending, inProgress, completed
	}

	// worker roles: filter assignments by kind mapped from role
	kind := roleToKind(role)
	if kind == "" {
		return pending, inProgress, completed
	}
	rows, err := s.DB.Query(ctx, `SELECT id::text, sample_id::text, status, coalesce(offered_worker_id::text,''), coalesce(worker_id::text,'') FROM assignments
		WHERE kind=$1 AND (offered_worker_id=$2 OR worker_id=$2)`, kind, userID)
	if err != nil {
		return pending, inProgress, completed
	}
	defer rows.Close()
	for rows.Next() {
		var id, sampleID, status, offered, worker string
		_ = rows.Scan(&id, &sampleID, &status, &offered, &worker)
		item := map[string]interface{}{"kind": kind, "assignmentId": id, "sampleId": sampleID, "status": status, "history": s.sampleTimeline(ctx, id)}
		switch status {
		case "offered":
			pending = append(pending, item)
		case "completed", "cancelled":
			completed = append(completed, item)
		default:
			inProgress = append(inProgress, item)
		}
	}
	return pending, inProgress, completed
}

func roleToKind(role string) string {
	switch role {
	case "collection_professional":
		return "collection"
	case "delivery_partner":
		return "transport"
	case "node_handler":
		return "node"
	case "laboratory_team":
		return "laboratory"
	}
	return ""
}

func (s *Server) ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "dispatcher" && role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req struct {
		Filters map[string]interface{} `json:"filters"`
	}
	_ = readJSON(r, &req)

	samples := s.fetchOpsSamples(ctx)
	workers := s.fetchOpsWorkers(ctx)
	locations := s.fetchOpsLocations(ctx)
	connections := s.fetchOpsConnections(ctx)

	writeData(w, http.StatusOK, map[string]interface{}{
		"samples": samples, "workers": workers, "locations": locations, "connections": connections,
		"routes": []map[string]interface{}{}, "handoffs": []map[string]interface{}{}, "delays": []map[string]interface{}{},
		"exceptions": s.fetchOpsExceptions(ctx),
		"assignmentCountSpread":     0,
		"ineligibleAssignmentCount": s.countIneligibleAssignments(ctx),
	})
}

func (s *Server) fetchOpsSamples(ctx context.Context) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT s.id::text, s.status, s.request_id::text, r.origin_latitude, r.origin_longitude, r.delivery_deadline,
		coalesce(s.current_holder_id::text,''), coalesce(s.active_journey_id::text,''), s.latest_latitude, s.latest_longitude, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id`)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, status, requestID, holder, journey string
		var lat, lng float64
		var deadline interface{}
		var slat, slng *float64
		var locRecorded interface{}
		_ = rows.Scan(&id, &status, &requestID, &lat, &lng, &deadline, &holder, &journey, &slat, &slng, &locRecorded)
		m := map[string]interface{}{
			"sampleId": id, "status": status, "requestId": requestID,
			"origin": map[string]interface{}{"latitude": lat, "longitude": lng},
			"deliveryDeadline": isoOrInterface(deadline), "locationStale": staleFromRaw(locRecorded),
		}
		if holder != "" {
			m["currentHolderId"] = holder
		}
		if journey != "" {
			m["activeJourneyId"] = journey
		}
		if slat != nil && slng != nil {
			m["latestLocation"] = map[string]interface{}{"latitude": *slat, "longitude": *slng}
		}
		if locRecorded != nil {
			m["locationRecordedAt"] = isoOrInterface(locRecorded)
		}
		out = append(out, m)
	}
	return out
}

func (s *Server) fetchOpsWorkers(ctx context.Context) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT u.id::text, coalesce(u.full_name,''), coalesce(wa.available, true), coalesce(wa.capacity_units,1)
		FROM users u LEFT JOIN worker_availability wa ON wa.worker_id=u.id
		JOIN user_roles ur ON ur.user_id=u.id AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
		GROUP BY u.id, u.full_name, wa.available, wa.capacity_units`)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, name string
		var available bool
		var capacity int
		_ = rows.Scan(&id, &name, &available, &capacity)
		var assignCount int
		_ = s.DB.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, id).Scan(&assignCount)
		roles := s.fetchRoles(ctx, id)
		var lat, lng *float64
		var recAt interface{}
		_ = s.DB.QueryRow(ctx, `SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=$1 ORDER BY sequence DESC LIMIT 1`, id).Scan(&lat, &lng, &recAt)
		status := "unavailable"
		if available {
			status = "available"
		}
		m := map[string]interface{}{
			"workerId": id, "fullName": name, "roles": roles, "available": available, "status": status,
			"capacityUnits": capacity, "assignmentCount": assignCount, "locationStale": staleFromRaw(recAt),
		}
		if lat != nil && lng != nil {
			m["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
		}
		if recAt != nil {
			m["locationRecordedAt"] = isoOrInterface(recAt)
		}
		out = append(out, m)
	}
	return out
}

func (s *Server) fetchOpsLocations(ctx context.Context) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id::text, name, latitude, longitude, active, coverage_km, handling_minutes,
		is_collection_point, is_transfer_point, is_hub, is_laboratory, capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM locations`)
