package api

import (
	"context"
	"net/http"
	"strings"
)

func (s *Server) sampleTimeline(ctx context.Context, sampleID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, action, coalesce(actor_id::text,''), coalesce(role,''), entity_type, entity_id, success, occurred_at, details
		FROM audit_log WHERE entity_id=$1 ORDER BY occurred_at ASC`, sampleID)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var action, actorID, role, entityType, entityID string
		var success bool
		var occurredAt interface{}
		var details []byte
		_ = rows.Scan(&id, &action, &actorID, &role, &entityType, &entityID, &success, &occurredAt, &details)
		out = append(out, map[string]interface{}{
			"eventId": id, "action": action, "actorId": actorID, "role": role,
			"entityType": entityType, "entityId": entityID, "success": success,
			"occurredAt": isoOrInterface(occurredAt), "details": jsonBytesToMap(details),
		})
	}
	return out
}

func isoOrInterface(v interface{}) interface{} {
	if t, ok := v.(interface{ String() string }); ok {
		return t.String()
	}
	return v
}

func jsonBytesToMap(b []byte) map[string]interface{} {
	out := map[string]interface{}{}
	if len(b) == 0 {
		return out
	}
	_ = decodeJSON(b, &out)
	return out
}

func (s *Server) ReadSampleState(w http.ResponseWriter, r *http.Request, sampleID string) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	userID := userIDFrom(ctx)

	var requesterID, sampleTypeID, status, containerType string
	var tempMin, tempMax float64
	var originLat, originLng float64
	var originType string
	var requestedAt, deadline interface{}
	var activeJourney, targetLab *string
	var lat, lng *float64
	var locRecordedAt interface{}
	var requestID string
	err := s.DB.QueryRow(ctx, `SELECT s.request_id, coalesce(s.requester_id::text,''), s.sample_type_id, s.status, r.container_type,
		r.temperature_min_c, r.temperature_max_c, r.origin_latitude, r.origin_longitude, r.origin_type, r.requested_at, r.delivery_deadline,
		s.active_journey_id::text, coalesce(s.target_laboratory_id::text,''), s.latest_latitude, s.latest_longitude, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&requestID, &requesterID, &sampleTypeID, &status, &containerType, &tempMin, &tempMax, &originLat, &originLng, &originType,
			&requestedAt, &deadline, &activeJourney, &targetLab, &lat, &lng, &locRecordedAt)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if role == "requester" && requesterID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	incompat := s.fetchIncompatibleTypes(ctx, sampleTypeID)
	timeline := s.sampleTimeline(ctx, sampleID)
	stale := isStale(locRecordedAt)

	serviceability := "serviceable"
	resp := map[string]interface{}{
		"sampleId": sampleID, "requestId": requestID, "requesterId": requesterID,
		"origin": map[string]interface{}{"latitude": originLat, "longitude": originLng},
		"originType": originType, "requestedAt": isoOrInterface(requestedAt), "deliveryDeadline": isoOrInterface(deadline),
		"sampleTypeId": sampleTypeID, "containerType": containerType, "temperatureMinC": tempMin, "temperatureMaxC": tempMax,
		"incompatibleSampleTypes": incompat, "serviceability": serviceability,
		"activeAssignmentIds": s.fetchActiveAssignmentIDs(ctx, sampleID),
		"state": map[string]interface{}{"status": status},
		"timeline": timeline, "locationStale": stale,
	}
	if activeJourney != nil {
		resp["activeJourneyId"] = *activeJourney
	}
	if targetLab != nil && *targetLab != "" {
		resp["targetLaboratoryId"] = *targetLab
	}
	if lat != nil && lng != nil {
		resp["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
	}
	if locRecordedAt != nil {
		resp["locationRecordedAt"] = isoOrInterface(locRecordedAt)
	}
	writeData(w, http.StatusOK, resp)
}

func isStale(recordedAt interface{}) bool {
	t, ok := recordedAt.(interface{ Before(u interface{ Before(interface{}) bool }) bool })
	_ = t
	_ = ok
	return staleFromRaw(recordedAt)
}

func (s *Server) fetchIncompatibleTypes(ctx context.Context, sampleTypeID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT incompatible_sample_type_id::text FROM sample_type_incompatibilities WHERE sample_type_id=$1`, sampleTypeID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

func (s *Server) fetchActiveAssignmentIDs(ctx context.Context, sampleID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT id::text FROM assignments WHERE sample_id=$1 AND status NOT IN ('completed','cancelled')`, sampleID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

type readSampleLifecycleReq struct {
	SampleID string `json:"sampleId"`
}

func (s *Server) ReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	userID := userIDFrom(ctx)
	var req readSampleLifecycleReq
	if !readJSON(r, &req) || req.SampleID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	var requesterID, status string
	var sealed bool
	var activeJourney, holderID, receivedLab *string
	var exception []byte
	err := s.DB.QueryRow(ctx, `SELECT coalesce(requester_id::text,''), status, sealed, active_journey_id::text, current_holder_id::text, received_laboratory_id::text, exception FROM samples WHERE id=$1`, req.SampleID).
		Scan(&requesterID, &status, &sealed, &activeJourney, &holderID, &receivedLab, &exception)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	if role == "requester" && requesterID != userID {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	completedLegs := s.fetchCompletedLegIDs(ctx, req.SampleID)
	timeline := s.sampleTimeline(ctx, req.SampleID)
	var lat, lng *float64
	var locRecordedAt interface{}
	_ = s.DB.QueryRow(ctx, `SELECT latest_latitude, latest_longitude, location_recorded_at FROM samples WHERE id=$1`, req.SampleID).Scan(&lat, &lng, &locRecordedAt)

	resp := map[string]interface{}{
		"sampleId": req.SampleID, "status": status, "sealed": sealed,
		"completedLegIds": completedLegs, "activeReplacementPlanIds": []string{},
		"timeline": timeline, "locationStale": staleFromRaw(locRecordedAt),
	}
	if activeJourney != nil {
		resp["activeJourneyId"] = *activeJourney
	}
	if holderID != nil {
		resp["currentHolderId"] = *holderID
	}
	if receivedLab != nil {
		resp["receivedLaboratoryId"] = *receivedLab
	}
	if len(exception) > 0 {
		resp["exception"] = jsonBytesToMap(exception)
	}
	var pendingHandoffID string
	_ = s.DB.QueryRow(ctx, `SELECT id::text FROM handoffs WHERE sample_id=$1 AND status='pending' LIMIT 1`, req.SampleID).Scan(&pendingHandoffID)
	if pendingHandoffID != "" {
		resp["pendingHandoffId"] = pendingHandoffID
	}
	if lat != nil && lng != nil {
		resp["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
	}
	if locRecordedAt != nil {
		resp["locationRecordedAt"] = isoOrInterface(locRecordedAt)
	}
	writeData(w, http.StatusOK, resp)
}

func (s *Server) fetchCompletedLegIDs(ctx context.Context, sampleID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT id::text FROM assignments WHERE sample_id=$1 AND status='completed'`, sampleID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

type readJourneyPlanReq struct {
	JourneyID string `json:"journeyId"`
}

func (s *Server) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	userID := userIDFrom(ctx)
	var req readJourneyPlanReq
	if !readJSON(r, &req) || req.JourneyID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	var planVersion int
	var routeMode, status string
	var estDelivery interface{}
	var totalCost float64
	var capUsed, capAvail int
	err := s.DB.QueryRow(ctx, `SELECT plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available FROM journeys WHERE id=$1`, req.JourneyID).
		Scan(&planVersion, &routeMode, &status, &estDelivery, &totalCost, &capUsed, &capAvail)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	sampleIDs := s.fetchJourneySamples(ctx, req.JourneyID)
	stops := s.fetchJourneyStops(ctx, req.JourneyID)
	legs := s.fetchJourneyLegs(ctx, req.JourneyID)

	if role == "requester" {
		var owns bool
		for _, sid := range sampleIDs {
			var reqOwner string
			_ = s.DB.QueryRow(ctx, `SELECT coalesce(requester_id::text,'') FROM samples WHERE id=$1`, sid).Scan(&reqOwner)
			if reqOwner == userID {
				owns = true
				break
			}
		}
		if !owns {
			writeErr(w, http.StatusForbidden, "forbidden", "")
			return
		}
		writeData(w, http.StatusOK, map[string]interface{}{
			"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
			"estimatedDeliveryAt": isoOrInterface(estDelivery), "totalCostUnits": totalCost,
			"sampleIds": sampleIDs, "orderedStops": stops, "legs": legs,
		})
		return
	}
	if role == "collection_professional" || role == "delivery_partner" || role == "node_handler" || role == "laboratory_team" {
		assignmentIDs := s.fetchWorkerAssignmentIDsForJourney(ctx, req.JourneyID, userID)
		if len(assignmentIDs) == 0 {
			writeErr(w, http.StatusForbidden, "forbidden", "")
			return
		}
		writeData(w, http.StatusOK, map[string]interface{}{
			"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
			"estimatedDeliveryAt": isoOrInterface(estDelivery), "scope": "assigned_legs",
			"assignmentIds": assignmentIDs, "sampleIds": sampleIDs, "legs": legs, "orderedStops": stops,
		})
		return
	}
	// dispatcher / administrator full view
	writeData(w, http.StatusOK, map[string]interface{}{
		"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
		"estimatedDeliveryAt": isoOrInterface(estDelivery), "totalCostUnits": totalCost,
		"capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": sampleIDs, "orderedStops": stops, "legs": legs,
	})
}

func (s *Server) fetchJourneySamples(ctx context.Context, journeyID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT sample_id::text FROM journey_samples WHERE journey_id=$1`, journeyID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

func (s *Server) fetchJourneyStops(ctx context.Context, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id::text, location_id::text, stop_type, sequence, estimated_at, dwell_minutes, completed_at FROM journey_stops WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, locID, stopType string
		var seq, dwell int
		var estAt, completedAt interface{}
		_ = rows.Scan(&id, &locID, &stopType, &seq, &estAt, &dwell, &completedAt)
		m := map[string]interface{}{
			"stopId": id, "locationId": locID, "stopType": stopType, "sequence": seq,
			"estimatedAt": isoOrInterface(estAt), "dwellMinutes": dwell,
		}
		if completedAt != nil {
			m["completedAt"] = isoOrInterface(completedAt)
		}
		out = append(out, m)
	}
	return out
}

func (s *Server) fetchJourneyLegs(ctx context.Context, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id::text, sequence, status, coalesce(from_location_id::text,''), coalesce(to_location_id::text,''), coalesce(worker_id::text,''), sample_id::text FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, status, from, to, worker, sampleID string
		var seq int
		_ = rows.Scan(&id, &seq, &status, &from, &to, &worker, &sampleID)
		m := map[string]interface{}{"assignmentId": id, "sequence": seq, "status": status, "sampleId": sampleID}
		if from != "" {
			m["fromLocationId"] = from
		}
		if to != "" {
			m["toLocationId"] = to
		}
		if worker != "" {
			m["workerId"] = worker
		}
		out = append(out, m)
	}
	return out
}

func (s *Server) fetchWorkerAssignmentIDsForJourney(ctx context.Context, journeyID, workerID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT id::text FROM assignments WHERE journey_id=$1 AND (worker_id=$2 OR offered_worker_id=$2)`, journeyID, workerID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

type listRoleWorkReq struct {
	Role   string `json:"role"`
	Status string `json:"status"`
}

func (s *Server) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	activeRole := activeRoleFrom(ctx)
	if activeRole == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req listRoleWorkReq
	_ = readJSON(r, &req)
	if req.Role != "" && req.Role != activeRole {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	userID := userIDFrom(ctx)
	pending, inProgress, completed := s.buildRoleWork(ctx, activeRole, userID)
	writeData(w, http.StatusOK, map[string]interface{}{
		"pending": pending, "inProgress": inProgress, "completed": completed,
	})
}

func (s *Server) buildRoleWork(ctx context.Context, role, userID string) ([]map[string]interface{}, []map[string]interface{}, []map[string]interface{}) {
	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	if role == "requester" {
		rows, err := s.DB.Query(ctx, `SELECT id::text, status FROM samples WHERE requester_id=$1`, userID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status string
				_ = rows.Scan(&id, &status)
				item := map[string]interface{}{"kind": "sample", "sampleId": id, "status": status, "history": s.sampleTimeline(ctx, id), "locationStale": false}
				if status == "received" || status == "cancelled" || status == "expired" {
					completed = append(completed, item)
				} else {
					inProgress = append(inProgress, item)
				}
			}
		}
		return pending, inProgress, completed
	}

	// worker roles: filter assignments by kind mapped from role
	kind := roleToKind(role)
	if kind == "" {
		return pending, inProgress, completed
	}
	rows, err := s.DB.Query(ctx, `SELECT id::text, sample_id::text, status, coalesce(offered_worker_id::text,''), coalesce(worker_id::text,'') FROM assignments
		WHERE kind=$1 AND (offered_worker_id=$2 OR worker_id=$2)`, kind, userID)
	if err != nil {
		return pending, inProgress, completed
	}
	defer rows.Close()
	for rows.Next() {
		var id, sampleID, status, offered, worker string
		_ = rows.Scan(&id, &sampleID, &status, &offered, &worker)
		item := map[string]interface{}{"kind": kind, "assignmentId": id, "sampleId": sampleID, "status": status, "history": s.sampleTimeline(ctx, id)}
		switch status {
		case "offered":
			pending = append(pending, item)
		case "completed", "cancelled":
			completed = append(completed, item)
		default:
			inProgress = append(inProgress, item)
		}
	}
	return pending, inProgress, completed
}

func roleToKind(role string) string {
	switch role {
	case "collection_professional":
		return "collection"
	case "delivery_partner":
		return "transport"
	case "node_handler":
		return "node"
	case "laboratory_team":
		return "laboratory"
	}
	return ""
}

func (s *Server) ReadOperationsState(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "dispatcher" && role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req struct {
		Filters map[string]interface{} `json:"filters"`
	}
	_ = readJSON(r, &req)

	samples := s.fetchOpsSamples(ctx)
	workers := s.fetchOpsWorkers(ctx)
	locations := s.fetchOpsLocations(ctx)
	connections := s.fetchOpsConnections(ctx)

	writeData(w, http.StatusOK, map[string]interface{}{
		"samples": samples, "workers": workers, "locations": locations, "connections": connections,
		"routes": []map[string]interface{}{}, "handoffs": []map[string]interface{}{}, "delays": []map[string]interface{}{},
		"exceptions": s.fetchOpsExceptions(ctx),
		"assignmentCountSpread":     0,
		"ineligibleAssignmentCount": s.countIneligibleAssignments(ctx),
	})
}

func (s *Server) fetchOpsSamples(ctx context.Context) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT s.id::text, s.status, s.request_id::text, r.origin_latitude, r.origin_longitude, r.delivery_deadline,
		coalesce(s.current_holder_id::text,''), coalesce(s.active_journey_id::text,''), s.latest_latitude, s.latest_longitude, s.location_recorded_at
		FROM samples s JOIN requests r ON r.id=s.request_id`)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, status, requestID, holder, journey string
		var lat, lng float64
		var deadline interface{}
		var slat, slng *float64
		var locRecorded interface{}
		_ = rows.Scan(&id, &status, &requestID, &lat, &lng, &deadline, &holder, &journey, &slat, &slng, &locRecorded)
		m := map[string]interface{}{
			"sampleId": id, "status": status, "requestId": requestID,
			"origin": map[string]interface{}{"latitude": lat, "longitude": lng},
			"deliveryDeadline": isoOrInterface(deadline), "locationStale": staleFromRaw(locRecorded),
		}
		if holder != "" {
			m["currentHolderId"] = holder
		}
		if journey != "" {
			m["activeJourneyId"] = journey
		}
		if slat != nil && slng != nil {
			m["latestLocation"] = map[string]interface{}{"latitude": *slat, "longitude": *slng}
		}
		if locRecorded != nil {
			m["locationRecordedAt"] = isoOrInterface(locRecorded)
		}
		out = append(out, m)
	}
	return out
}

func (s *Server) fetchOpsWorkers(ctx context.Context) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT u.id::text, coalesce(u.full_name,''), coalesce(wa.available, true), coalesce(wa.capacity_units,1)
		FROM users u LEFT JOIN worker_availability wa ON wa.worker_id=u.id
		JOIN user_roles ur ON ur.user_id=u.id AND ur.role IN ('collection_professional','delivery_partner','node_handler','laboratory_team')
		GROUP BY u.id, u.full_name, wa.available, wa.capacity_units`)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, name string
		var available bool
		var capacity int
		_ = rows.Scan(&id, &name, &available, &capacity)
		var assignCount int
		_ = s.DB.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, id).Scan(&assignCount)
		roles := s.fetchRoles(ctx, id)
		var lat, lng *float64
		var recAt interface{}
		_ = s.DB.QueryRow(ctx, `SELECT latitude, longitude, recorded_at FROM worker_locations WHERE worker_id=$1 ORDER BY sequence DESC LIMIT 1`, id).Scan(&lat, &lng, &recAt)
		status := "unavailable"
		if available {
			status = "available"
		}
		m := map[string]interface{}{
			"workerId": id, "fullName": name, "roles": roles, "available": available, "status": status,
			"capacityUnits": capacity, "assignmentCount": assignCount, "locationStale": staleFromRaw(recAt),
		}
		if lat != nil && lng != nil {
			m["latestLocation"] = map[string]interface{}{"latitude": *lat, "longitude": *lng}
		}
		if recAt != nil {
			m["locationRecordedAt"] = isoOrInterface(recAt)
		}
		out = append(out, m)
	}
	return out
}

