func (s *Server) fetchOpsConnections(ctx context.Context) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id::text, from_location_id::text, to_location_id::text, travel_minutes, cost_units, cooled, active,
		capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units FROM connections`)
