func (s *Server) sampleTimeline(ctx context.Context, sampleID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id, action, coalesce(actor_id::text,''), coalesce(role,''), entity_type, entity_id, success, occurred_at, details
		FROM audit_log WHERE entity_id=$1 ORDER BY occurred_at ASC`, sampleID)
	out := []map[string]interface{}{}
