	Status string `json:"status"`
}

func (s *Server) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	activeRole := activeRoleFrom(ctx)
	if activeRole == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	var req listRoleWorkReq
	_ = readJSON(r, &req)
	if req.Role != "" && req.Role != activeRole {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	userID := userIDFrom(ctx)
	pending, inProgress, completed := s.buildRoleWork(ctx, activeRole, userID)
	writeData(w, http.StatusOK, map[string]interface{}{
		"pending": pending, "inProgress": inProgress, "completed": completed,
	})
}

func (s *Server) buildRoleWork(ctx context.Context, role, userID string) ([]map[string]interface{}, []map[string]interface{}, []map[string]interface{}) {
	pending := []map[string]interface{}{}
	inProgress := []map[string]interface{}{}
	completed := []map[string]interface{}{}

	if role == "requester" {
		rows, err := s.DB.Query(ctx, `SELECT id::text, status FROM samples WHERE requester_id=$1`, userID)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status string
				_ = rows.Scan(&id, &status)
				item := map[string]interface{}{"kind": "sample", "sampleId": id, "status": status, "history": s.sampleTimeline(ctx, id), "locationStale": false}
				if status == "received" || status == "cancelled" || status == "expired" {
					completed = append(completed, item)
				} else {
					inProgress = append(inProgress, item)
				}
			}
		}
		return pending, inProgress, completed
	}

	// worker roles: filter assignments by kind mapped from role
	kind := roleToKind(role)
	if kind == "" {
		return pending, inProgress, completed
	}
	rows, err := s.DB.Query(ctx, `SELECT id::text, sample_id::text, status, coalesce(offered_worker_id::text,''), coalesce(worker_id::text,'') FROM assignments
		WHERE kind=$1 AND (offered_worker_id=$2 OR worker_id=$2)`, kind, userID)
	if err != nil {
		return pending, inProgress, completed
	}
	defer rows.Close()
	for rows.Next() {
		var id, sampleID, status, offered, worker string
		_ = rows.Scan(&id, &sampleID, &status, &offered, &worker)
		item := map[string]interface{}{"kind": kind, "assignmentId": id, "sampleId": sampleID, "status": status, "history": s.sampleTimeline(ctx, id)}
		switch status {
		case "offered":
			pending = append(pending, item)
		case "completed", "cancelled":
			completed = append(completed, item)
		default:
			inProgress = append(inProgress, item)
		}
	}
	return pending, inProgress, completed
}

func roleToKind(role string) string {
	switch role {
	case "collection_professional":
		return "collection"
	case "delivery_partner":
		return "transport"
	case "node_handler":
		return "node"
	case "laboratory_team":
		return "laboratory"
	}
	return ""
}

