func (s *Server) ReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	userID := userIDFrom(ctx)
	var req readJourneyPlanReq
	if !readJSON(r, &req) || req.JourneyID == "" {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	var planVersion int
	var routeMode, status string
	var estDelivery interface{}
	var totalCost float64
	var capUsed, capAvail int
	err := s.DB.QueryRow(ctx, `SELECT plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available FROM journeys WHERE id=$1`, req.JourneyID).
		Scan(&planVersion, &routeMode, &status, &estDelivery, &totalCost, &capUsed, &capAvail)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return
	}
	sampleIDs := s.fetchJourneySamples(ctx, req.JourneyID)
	stops := s.fetchJourneyStops(ctx, req.JourneyID)
	legs := s.fetchJourneyLegs(ctx, req.JourneyID)

	if role == "requester" {
		var owns bool
		for _, sid := range sampleIDs {
			var reqOwner string
			_ = s.DB.QueryRow(ctx, `SELECT coalesce(requester_id::text,'') FROM samples WHERE id=$1`, sid).Scan(&reqOwner)
			if reqOwner == userID {
				owns = true
				break
			}
		}
		if !owns {
			writeErr(w, http.StatusForbidden, "forbidden", "")
			return
		}
		writeData(w, http.StatusOK, map[string]interface{}{
			"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
			"estimatedDeliveryAt": isoOrInterface(estDelivery), "totalCostUnits": totalCost,
			"sampleIds": sampleIDs, "orderedStops": stops, "legs": legs,
		})
		return
	}
	if role == "collection_professional" || role == "delivery_partner" || role == "node_handler" || role == "laboratory_team" {
		assignmentIDs := s.fetchWorkerAssignmentIDsForJourney(ctx, req.JourneyID, userID)
		if len(assignmentIDs) == 0 {
			writeErr(w, http.StatusForbidden, "forbidden", "")
			return
		}
		writeData(w, http.StatusOK, map[string]interface{}{
			"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
			"estimatedDeliveryAt": isoOrInterface(estDelivery), "scope": "assigned_legs",
			"assignmentIds": assignmentIDs, "sampleIds": sampleIDs, "legs": legs, "orderedStops": stops,
		})
		return
	}
	// dispatcher / administrator full view
	writeData(w, http.StatusOK, map[string]interface{}{
		"journeyId": req.JourneyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
		"estimatedDeliveryAt": isoOrInterface(estDelivery), "totalCostUnits": totalCost,
		"capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": sampleIDs, "orderedStops": stops, "legs": legs,
	})
}

