type searchAuditReq struct {
	Query      string `json:"query"`
	ActorID    string `json:"actorId"`
	EntityType string `json:"entityType"`
	EntityID   string `json:"entityId"`
	Action     string `json:"action"`
	Role       string `json:"role"`
	Success    *bool  `json:"success"`
	FromTime   string `json:"fromTime"`
	ToTime     string `json:"toTime"`
	Limit      *int   `json:"limit"`
	Offset     *int   `json:"offset"`
	Order      string `json:"order"`
}

func (s *Server) SearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role != "dispatcher" && role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req searchAuditReq
	if !readJSON(r, &req) {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	limit := 500
	if req.Limit != nil {
		if *req.Limit < 1 || *req.Limit > 5000 {
			writeErr(w, http.StatusBadRequest, "invalid_limit", "")
			return
		}
		limit = *req.Limit
	}
	offset := 0
	if req.Offset != nil {
		if *req.Offset < 0 {
			writeErr(w, http.StatusBadRequest, "invalid_offset", "")
			return
		}
		offset = *req.Offset
	}
	order := "newest_first"
	if req.Order != "" {
		if req.Order != "newest_first" && req.Order != "oldest_first" {
			writeErr(w, http.StatusBadRequest, "invalid_order", "")
			return
		}
		order = req.Order
	}
	var fromT, toT interface{}
	if req.FromTime != "" {
		t, ok := parseTime(req.FromTime)
		if !ok {
			writeErr(w, http.StatusBadRequest, "invalid_time", "")
			return
		}
		fromT = t
	}
	if req.ToTime != "" {
		t, ok := parseTime(req.ToTime)
		if !ok {
			writeErr(w, http.StatusBadRequest, "invalid_time", "")
			return
		}
		toT = t
	}

	where := []string{"1=1"}
	args := []interface{}{}
	addArg := func(cond string, val interface{}) {
		args = append(args, val)
		where = append(where, strings.Replace(cond, "?", argN(len(args)), 1))
	}
	if req.ActorID != "" {
		addArg("actor_id = ?", req.ActorID)
	}
	if req.EntityType != "" {
		addArg("entity_type = ?", req.EntityType)
	}
	if req.EntityID != "" {
		addArg("entity_id = ?", req.EntityID)
	}
	if req.Action != "" {
		addArg("action = ?", req.Action)
	}
	if req.Role != "" {
		addArg("role = ?", req.Role)
	}
	if req.Success != nil {
		addArg("success = ?", *req.Success)
	}
	if fromT != nil {
		addArg("occurred_at >= ?", fromT)
	}
	if toT != nil {
		addArg("occurred_at <= ?", toT)
	}
	if req.Query != "" {
		addArg("(action ILIKE ? OR entity_type ILIKE ? OR entity_id ILIKE ?)", "%"+req.Query+"%")
		// add same value twice more for other placeholders
		args = append(args, "%"+req.Query+"%", "%"+req.Query+"%")
	}

	whereSQL := strings.Join(where, " AND ")
	var total int
	countQuery := `SELECT count(*) FROM audit_log WHERE ` + whereSQL
	_ = s.DB.QueryRow(ctx, countQuery, args...).Scan(&total)

	orderSQL := "occurred_at DESC"
	if order == "oldest_first" {
		orderSQL = "occurred_at ASC"
	}
	q := `SELECT id, coalesce(actor_id::text,''), role, action, entity_type, coalesce(entity_id,''), success, occurred_at, details
		FROM audit_log WHERE ` + whereSQL + ` ORDER BY ` + orderSQL + fmtLimitOffset(len(args)+1, len(args)+2)
	args2 := append(args, limit, offset)
	rows, err := s.DB.Query(ctx, q, args2...)
	entries := []map[string]interface{}{}
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id int64
			var actorID, role2, action, entityType, entityID string
			var success bool
			var occurredAt interface{}
			var details []byte
			_ = rows.Scan(&id, &actorID, &role2, &action, &entityType, &entityID, &success, &occurredAt, &details)
			entries = append(entries, map[string]interface{}{
				"auditId": intToStr(id), "actorId": actorID, "role": role2, "actorRole": role2,
				"action": action, "entityType": entityType, "entityId": entityID,
				"success": success, "occurredAt": isoOrInterface(occurredAt), "details": jsonBytesToMap(details),
			})
		}
	}
	hasMore := offset+len(entries) < total
	resp := map[string]interface{}{
		"entries": entries, "total": total, "returned": len(entries), "offset": offset, "limit": limit, "order": order, "hasMore": hasMore,
	}
	if hasMore {
		resp["nextOffset"] = offset + len(entries)
	}
	s.audit(ctx, userIDFrom(ctx), role, "search_audit_trail", "audit", "", true, map[string]interface{}{"query": req.Query})
	writeData(w, http.StatusOK, resp)
}

func argN(n int) string {
	return "$" + intToStr(int64(n))
}

func fmtLimitOffset(limitIdx, offsetIdx int) string {
	return " LIMIT $" + intToStr(int64(limitIdx)) + " OFFSET $" + intToStr(int64(offsetIdx))
}

func intToStr(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

func (s *Server) ReadUIBootstrap(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	userID := userIDFrom(ctx)
	if userID == "" {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "")
		return
	}
	username := usernameFrom(ctx)
	var fullName string
	_ = s.DB.QueryRow(ctx, `SELECT coalesce(full_name,'') FROM users WHERE id=$1`, userID).Scan(&fullName)
	roles := s.fetchRoles(ctx, userID)
	activeRole := activeRoleFrom(ctx)
	userObj := map[string]interface{}{
		"userId": userID, "username": username, "fullName": fullName, "roles": roles,
		"activeRole": activeRole, "roleSelectionRequired": activeRole == "" && len(roles) > 1,
	}
	resp := map[string]interface{}{
		"user": userObj, "serverTime": nowISO(),
	}
	if activeRole == "requester" {
		rows, err := s.DB.Query(ctx, `SELECT id::text, status FROM samples WHERE requester_id=$1`, userID)
		samples := []map[string]interface{}{}
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var id, status string
				_ = rows.Scan(&id, &status)
				samples = append(samples, map[string]interface{}{"sampleId": id, "status": status})
			}
		}
		resp["requesterSamples"] = samples
	}
	if activeRole == "dispatcher" || activeRole == "administrator" {
		resp["operations"] = map[string]interface{}{
			"samples": s.fetchOpsSamples(ctx), "workers": s.fetchOpsWorkers(ctx),
			"locations": s.fetchOpsLocations(ctx), "connections": s.fetchOpsConnections(ctx),
			"routes": []map[string]interface{}{}, "handoffs": []map[string]interface{}{}, "delays": []map[string]interface{}{},
			"exceptions": s.fetchOpsExceptions(ctx), "assignmentCountSpread": 0,
			"ineligibleAssignmentCount": s.countIneligibleAssignments(ctx),
		}
	}
	writeData(w, http.StatusOK, resp)
}

