func (s *Server) fetchJourneyLegs(ctx context.Context, journeyID string) []map[string]interface{} {
	rows, err := s.DB.Query(ctx, `SELECT id::text, sequence, status, coalesce(from_location_id::text,''), coalesce(to_location_id::text,''), coalesce(worker_id::text,''), sample_id::text FROM assignments WHERE journey_id=$1 ORDER BY sequence ASC`, journeyID)
	out := []map[string]interface{}{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id, status, from, to, worker, sampleID string
		var seq int
		_ = rows.Scan(&id, &seq, &status, &from, &to, &worker, &sampleID)
		m := map[string]interface{}{"assignmentId": id, "sequence": seq, "status": status, "sampleId": sampleID}
		if from != "" {
			m["fromLocationId"] = from
		}
		if to != "" {
			m["toLocationId"] = to
		}
		if worker != "" {
			m["workerId"] = worker
		}
		out = append(out, m)
	}
	return out
