func (s *Server) fetchWorkerAssignmentIDsForJourney(ctx context.Context, journeyID, workerID string) []string {
	rows, err := s.DB.Query(ctx, `SELECT id::text FROM assignments WHERE journey_id=$1 AND (worker_id=$2 OR offered_worker_id=$2)`, journeyID, workerID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
