    22	func (s *Server) loadSampleType(ctx context.Context, id string) (sampleTypeInfo, bool) {
    23		var t sampleTypeInfo
    24		var reqQual *string
    25		err := s.DB.QueryRow(ctx, `SELECT id, name, qualified_collector_required, required_qualification, container_type,
    26			temperature_min_c, temperature_max_c, requires_cooled_route, batching_allowed FROM sample_types WHERE id=$1`, id).
    27			Scan(&t.ID, &t.Name, &t.QualifiedCollectorRequired, &reqQual, &t.ContainerType, &t.TemperatureMinC, &t.TemperatureMaxC, &t.RequiresCooledRoute, &t.BatchingAllowed)
    28		if err != nil {
    29			return t, false
    30		}
    31		if reqQual != nil {
    32			t.RequiredQualification = *reqQual
    33		}
    34		return t, true
    35	}
    36	
    37	// buildJourneyPlan constructs a journey (with stops+assignments) for a sample going from
    38	// an origin collection point to a target laboratory, reserving capacity along the way.
    39	// alreadySealed indicates the sample enters the network already sealed at holderLocationID
    40	// (skipping the collection leg).
    41	type journeyBuildResult struct {
    42		JourneyID          string
    43		AssignmentIDs      []string
    44		TargetLaboratoryID string
    45		EstimatedDelivery  time.Time
    46		OK                 bool
    47		FailureCode        string
    48	}
    49	
    50	func (s *Server) buildJourneyPlan(ctx context.Context, sampleID, sampleTypeID string, originLat, originLng float64, collectionPointID string, alreadySealed bool, holderLocationID string, deadline time.Time, cooled bool) journeyBuildResult {
    51		var res journeyBuildResult
    52	
    53		st, ok := s.loadSampleType(ctx, sampleTypeID)
    54		if !ok {
    55			res.FailureCode = "no_route"
    56			return res
    57		}
    58	
    59		// find target laboratory that accepts sample type
    60		rows, err := s.DB.Query(ctx, `SELECT l.id, l.latitude, l.longitude FROM locations l
    61			JOIN laboratory_acceptance a ON a.laboratory_id=l.id AND a.sample_type_id=$1 AND a.accepts=true
    62			WHERE l.active=true AND l.is_laboratory=true`, sampleTypeID)
    63		type lab struct {
    64			ID       string
    65			Lat, Lng float64
    66		}
    67		var labs []lab
    68		if err == nil {
    69			for rows.Next() {
    70				var l lab
    71				_ = rows.Scan(&l.ID, &l.Lat, &l.Lng)
    72				labs = append(labs, l)
    73			}
    74			rows.Close()
    75		}
    76		if len(labs) == 0 {
    77			res.FailureCode = "no_valid_route"
    78			return res
    79		}
    80	
    81		startNode := collectionPointID
    82		if alreadySealed {
    83			startNode = holderLocationID
    84		}
    85	
    86		// choose nearest reachable lab by path length
    87		bestLab := ""
    88		var bestPath []edge
    89		bestMinutes := -1
    90		for _, l := range labs {
    91			path, ok := s.shortestPath(ctx, startNode, l.ID)
    92			if !ok {
    93				continue
    94			}
    95			total := 0
    96			for _, e := range path {
    97				total += e.Minutes
    98			}
    99			if bestMinutes == -1 || total < bestMinutes {
   100				bestMinutes = total
   101				bestLab = l.ID
   102				bestPath = path
   103			}
   104		}
   105		if bestLab == "" {
   106			res.FailureCode = "no_valid_route"
   107			return res
   108		}
   109	
   110		handlingBuffer := 30.0
   111		estimatedDelivery := timeNow().Add(minutesToDuration(float64(bestMinutes) + handlingBuffer))
   112		if estimatedDelivery.After(deadline) {
   113			res.FailureCode = "deadline_exceeded"
   114			return res
   115		}
   116	
   117		// capacity check along route + laboratory
   118		if !s.checkAndReserveCapacity(ctx, bestPath, bestLab, cooled) {
   119			res.FailureCode = "capacity_exhausted"
   120			return res
   121		}
   122	
   123		journeyID := uuid.NewString()
   124		routeMode := "direct"
   125		if len(bestPath) > 1 {
   126			routeMode = "multi_stop"
   127		}
   128		_, err = s.DB.Exec(ctx, `INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, capacity_used, capacity_available)
   129			VALUES ($1,1,$2,'active',$3,1,0)`, journeyID, routeMode, estimatedDelivery)
   130		if err != nil {
   131			res.FailureCode = "invalid_plan"
   132			return res
   133		}
   134		_, _ = s.DB.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, journeyID, sampleID)
   135	
   136		seq := 0
   137		if !alreadySealed {
   138			// stop 0: pickup at collection point
   139			_, _ = s.DB.Exec(ctx, `INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at)
   140				VALUES ($1,$2,'pickup',$3, now())`, journeyID, collectionPointID, seq)
   141			seq++
   142			aID := uuid.NewString()
   143			_, _ = s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sample_id, sequence, status, to_location_id, required_qualification)
   144				VALUES ($1,$2,'collection',$3,$4,'pending',$5,$6)`, aID, journeyID, sampleID, seq, collectionPointID, nilIfEmpty(st.RequiredQualification))
   145			res.AssignmentIDs = append(res.AssignmentIDs, aID)
   146		}
   147	
   148		for i, e := range bestPath {
   149			_, _ = s.DB.Exec(ctx, `INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at)
   150				VALUES ($1,$2,'handoff',$3, now())`, journeyID, e.To, seq)
   151			seq++
   152			aID := uuid.NewString()
   153			_, _ = s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sample_id, sequence, status, from_location_id, to_location_id)
   154				VALUES ($1,$2,'transport',$3,$4,'pending',$5,$6)`, aID, journeyID, sampleID, seq, e.From, e.To)
   155			res.AssignmentIDs = append(res.AssignmentIDs, aID)
   156			_ = i
   157		}
   158	
   159		// final delivery stop at laboratory
   160		_, _ = s.DB.Exec(ctx, `INSERT INTO journey_stops (journey_id, location_id, stop_type, sequence, estimated_at)
   161			VALUES ($1,$2,'delivery',$3,$4)`, journeyID, bestLab, seq, estimatedDelivery)
   162	
   163		// laboratory assignment for intake operator
   164		labAID := uuid.NewString()
   165		_, _ = s.DB.Exec(ctx, `INSERT INTO assignments (id, journey_id, kind, sample_id, sequence, status, laboratory_id, expected_sample_type_id)
   166			VALUES ($1,$2,'laboratory',$3,$4,'pending',$5,$6)`, labAID, journeyID, sampleID, seq+1, bestLab, sampleTypeID)
   167		res.AssignmentIDs = append(res.AssignmentIDs, labAID)
   168	
   169		_, _ = s.DB.Exec(ctx, `UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2, updated_at=now() WHERE id=$3`, journeyID, bestLab, sampleID)
   170	
   171		res.JourneyID = journeyID
   172		res.TargetLaboratoryID = bestLab
   173		res.EstimatedDelivery = estimatedDelivery
   174		res.OK = true
   175		return res
   176	}
   177	
   178	func (s *Server) checkAndReserveCapacity(ctx context.Context, path []edge, labID string, cooled bool) bool {
   179		// verify availability first
   180		for _, e := range path {
   181			var avail, cooledAvail int
   182			_ = s.DB.QueryRow(ctx, `SELECT capacity_units-reserved_units, cooled_capacity_units-cooled_reserved_units FROM connections WHERE id=$1`, e.ConnectionID).Scan(&avail, &cooledAvail)
   183			if cooled {
   184				if cooledAvail < 1 {
   185					return false
   186				}
   187			} else if avail < 1 {
   188				return false
   189			}
   190		}
   191		var labAvail, labCooledAvail int
   192		_ = s.DB.QueryRow(ctx, `SELECT capacity_units-reserved_units, cooled_capacity_units-cooled_reserved_units FROM locations WHERE id=$1`, labID).Scan(&labAvail, &labCooledAvail)
   193		if cooled {
   194			if labCooledAvail < 1 {
   195				return false
   196			}
   197		} else if labAvail < 1 {
   198			return false
   199		}
   200		// reserve
   201		for _, e := range path {
   202			if cooled {
   203				_, _ = s.DB.Exec(ctx, `UPDATE connections SET cooled_reserved_units=cooled_reserved_units+1 WHERE id=$1`, e.ConnectionID)
   204			} else {
   205				_, _ = s.DB.Exec(ctx, `UPDATE connections SET reserved_units=reserved_units+1 WHERE id=$1`, e.ConnectionID)
   206			}
   207		}
   208		if cooled {
   209			_, _ = s.DB.Exec(ctx, `UPDATE locations SET cooled_reserved_units=cooled_reserved_units+1 WHERE id=$1`, labID)
   210		} else {
   211			_, _ = s.DB.Exec(ctx, `UPDATE locations SET reserved_units=reserved_units+1 WHERE id=$1`, labID)
   212		}
   213		return true
   214	}
   215	
   216	func (s *Server) releaseJourneyCapacity(ctx context.Context, journeyID string) {
   217		rows, err := s.DB.Query(ctx, `SELECT DISTINCT from_location_id, to_location_id FROM assignments WHERE journey_id=$1 AND kind='transport'`, journeyID)
   218		if err == nil {
   219			for rows.Next() {
   220				var from, to *string
   221				_ = rows.Scan(&from, &to)
   222				if from != nil && to != nil {
   223					_, _ = s.DB.Exec(ctx, `UPDATE connections SET reserved_units=GREATEST(reserved_units-1,0) WHERE from_location_id=$1 AND to_location_id=$2`, *from, *to)
   224				}
   225			}
   226			rows.Close()
   227		}
   228		var labID *string
   229		_ = s.DB.QueryRow(ctx, `SELECT laboratory_id FROM assignments WHERE journey_id=$1 AND kind='laboratory' LIMIT 1`, journeyID).Scan(&labID)
   230		if labID != nil {
   231			_, _ = s.DB.Exec(ctx, `UPDATE locations SET reserved_units=GREATEST(reserved_units-1,0) WHERE id=$1`, *labID)
   232		}
   233	}
   234

