type mergeJourneysReq struct {
	TargetJourneyID     string   `json:"targetJourneyId"`
	ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
	SourceJourneyIDs    []string `json:"sourceJourneyIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (s *Server) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req mergeJourneysReq
	if !readJSON(r, &req) || req.TargetJourneyID == "" || req.ExpectedPlanVersion == nil || len(req.SourceJourneyIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "merge_journeys") {
		return
	}
	ok, planVersion, _ := s.journeyMutationGuard(w, r, req.TargetJourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}
	for _, srcID := range req.SourceJourneyIDs {
		var srcStatus string
		err := s.DB.QueryRow(ctx, `SELECT status FROM journeys WHERE id=$1`, srcID).Scan(&srcStatus)
		if err != nil {
			writeErr(w, http.StatusNotFound, "not_found", "")
			return
		}
		if srcStatus != "active" {
			writeErr(w, http.StatusConflict, "inactive_plan", "")
			return
		}
		sids := s.fetchJourneySamples(ctx, srcID)
		for _, sid := range sids {
			_, _ = s.DB.Exec(ctx, `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, srcID, sid)
			_, _ = s.DB.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
			_, _ = s.DB.Exec(ctx, `UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status NOT IN ('completed','cancelled')`, req.TargetJourneyID, srcID, sid)
			_, _ = s.DB.Exec(ctx, `UPDATE samples SET active_journey_id=$1, updated_at=now() WHERE id=$2`, req.TargetJourneyID, sid)
		}
		_, _ = s.DB.Exec(ctx, `UPDATE journeys SET status='merged', updated_at=now() WHERE id=$1`, srcID)
	}
	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET plan_version=$1, updated_at=now() WHERE id=$2`, planVersion+1, req.TargetJourneyID)

	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sourceJourneyIds": req.SourceJourneyIDs})
	s.emitEvent(ctx, "journeys_merged", "journey", req.TargetJourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.TargetJourneyID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "merge_journeys", http.StatusCreated, s.journeyPlanFull(ctx, req.TargetJourneyID))
}

type editActivePlanReq struct {
	JourneyID           string                 `json:"journeyId"`
	ExpectedPlanVersion *int                   `json:"expectedPlanVersion"`
	ChangeType          string                 `json:"changeType"`
	Changes             map[string]interface{} `json:"changes"`
	IdempotencyKey       string                 `json:"idempotencyKey"`
}

var validChangeTypes = map[string]bool{
	"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
	"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
	"cancel_work": true, "reroute": true, "replace_route": true,
}

func (s *Server) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req editActivePlanReq
	if !readJSON(r, &req) || req.JourneyID == "" || req.ExpectedPlanVersion == nil || !validChangeTypes[req.ChangeType] || req.Changes == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "edit_active_plan") {
		return
	}
	ok, planVersion, _ := s.journeyMutationGuard(w, r, req.JourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}

	switch req.ChangeType {
	case "replace_worker", "reassign_worker":
		assignmentID, _ := req.Changes["assignmentId"].(string)
		newWorkerID, _ := req.Changes["workerId"].(string)
		if assignmentID == "" || newWorkerID == "" {
			writeErr(w, http.StatusBadRequest, "invalid_worker", "")
			return
		}
		var curStatus string
		err := s.DB.QueryRow(ctx, `SELECT status FROM assignments WHERE id=$1 AND journey_id=$2`, assignmentID, req.JourneyID).Scan(&curStatus)
		if err != nil {
			writeErr(w, http.StatusNotFound, "not_found", "")
			return
		}
		if curStatus == "completed" {
			writeErr(w, http.StatusConflict, "completed_work_immutable", "")
			return
		}
		_, _ = s.DB.Exec(ctx, `UPDATE assignments SET worker_id=$1, offered_worker_id=NULL, status='offered', offer_expires_at=now()+interval '5 minutes', updated_at=now() WHERE id=$2`, newWorkerID, assignmentID)
	case "cancel_work":
		assignmentID, _ := req.Changes["assignmentId"].(string)
		if assignmentID == "" {
			writeErr(w, http.StatusBadRequest, "invalid_json", "")
			return
		}
		var curStatus string
		err := s.DB.QueryRow(ctx, `SELECT status FROM assignments WHERE id=$1 AND journey_id=$2`, assignmentID, req.JourneyID).Scan(&curStatus)
		if err != nil {
			writeErr(w, http.StatusNotFound, "not_found", "")
			return
		}
		if curStatus == "completed" {
			writeErr(w, http.StatusConflict, "completed_work_immutable", "")
			return
		}
		_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now() WHERE id=$1`, assignmentID)
	default:
		// generic changes recorded but not deeply modeled; still bump plan version.
	}

	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET plan_version=$1, updated_at=now() WHERE id=$2`, planVersion+1, req.JourneyID)
	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
	s.emitEvent(ctx, "plan_edited", "journey", req.JourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.JourneyID, "changeType": req.ChangeType})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "edit_active_plan", http.StatusCreated, s.journeyPlanFull(ctx, req.JourneyID))
}

type reportDisruptionReq struct {
	ResourceType   string `json:"resourceType"`
	ResourceID     string `json:"resourceId"`
	Reason         string `json:"reason"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

var validResourceTypes = map[string]bool{
	"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true,
}

func (s *Server) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	if role != "dispatcher" && role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req reportDisruptionReq
	if !readJSON(r, &req) || !validResourceTypes[req.ResourceType] || req.ResourceID == "" || req.OccurredAt == "" {
		if req.ResourceType != "" && !validResourceTypes[req.ResourceType] {
			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "")
			return
		}
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if _, ok := parseTime(req.OccurredAt); !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "report_disruption") {
		return
	}

	affected := s.findAffectedSamples(ctx, req.ResourceType, req.ResourceID)
	replacementPlanIDs := []string{}
	overallStatus := "not_required"
	for _, sampleID := range affected {
		var journeyID string
		_ = s.DB.QueryRow(ctx, `SELECT coalesce(active_journey_id::text,'') FROM samples WHERE id=$1`, sampleID).Scan(&journeyID)
		if journeyID == "" {
			continue
		}
		replanStatus, replacementID := s.replanJourney(ctx, journeyID, req.Reason)
		if replacementID != "" {
			replacementPlanIDs = append(replacementPlanIDs, replacementID)
		}
		overallStatus = combineReplanStatus(overallStatus, replanStatus)
	}

	disruptionID := uuid.NewString()
	_, _ = s.DB.Exec(ctx, `INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, disruptionID, req.ResourceType, req.ResourceID, nilIfEmpty(req.Reason), req.OccurredAt, toUUIDArray(affected), toUUIDArray(replacementPlanIDs), overallStatus)

	s.audit(ctx, userIDFrom(ctx), role, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"affectedSampleIds": affected, "replanStatus": overallStatus})
	s.emitEvent(ctx, "disruption_reported", req.ResourceType, req.ResourceID, "dispatcher", "", map[string]interface{}{"disruptionId": disruptionID, "replanStatus": overallStatus})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "report_disruption", http.StatusCreated, map[string]interface{}{
		"disruptionId": disruptionID, "affectedSampleIds": emptyIfNil(affected),
		"replacementPlanIds": emptyIfNil(replacementPlanIDs), "replanStatus": overallStatus,
	})
}

func combineReplanStatus(cur, next string) string {
	priority := map[string]int{"not_required": 0, "replaced": 1, "expired": 2, "exception": 3}
	if priority[next] > priority[cur] {
		return next
	}
	return cur
}

func toUUIDArray(ids []string) []string {
	if ids == nil {
		return []string{}
	}
	return ids
}

func (s *Server) findAffectedSamples(ctx context.Context2, resourceType, resourceID string) []string {
	var query string
	switch resourceType {
	case "worker":
		query = `SELECT DISTINCT sample_id::text FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled')`
	case "location", "node", "laboratory":
		query = `SELECT DISTINCT sample_id::text FROM assignments WHERE (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1) AND status NOT IN ('completed','cancelled')`
	case "connection", "route":
		query = `SELECT DISTINCT a.sample_id::text FROM assignments a JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id
			WHERE c.id=$1 AND a.status NOT IN ('completed','cancelled')`
	default:
		return []string{}
	}
	rows, err := s.DB.Query(ctx, query, resourceID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}
"}

