package api

import (
	"net/http"

	"github.com/google/uuid"
)

// journeyMutationGuard verifies caller role and loads the current plan_version/status for a
// journey, returning the sample ids in that journey.
func (s *Server) journeyMutationGuard(w http.ResponseWriter, r *http.Request, journeyID string, expectedVersion int) (ok bool, planVersion int, status string) {
	role := activeRoleFrom(r.Context())
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return false, 0, ""
	}
	if role != "dispatcher" && role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return false, 0, ""
	}
	err := s.DB.QueryRow(r.Context(), `SELECT plan_version, status FROM journeys WHERE id=$1`, journeyID).Scan(&planVersion, &status)
	if err != nil {
		writeErr(w, http.StatusNotFound, "not_found", "")
		return false, 0, ""
	}
	if planVersion != expectedVersion {
		writeErr(w, http.StatusConflict, "stale_plan", "")
		return false, 0, ""
	}
	if status != "active" {
		writeErr(w, http.StatusConflict, "inactive_plan", "")
		return false, 0, ""
	}
	return true, planVersion, status
}

type cancelJourneyReq struct {
	JourneyID           string `json:"journeyId"`
	ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
	Reason              string `json:"reason"`
	IdempotencyKey      string `json:"idempotencyKey"`
}

func (s *Server) CancelJourney(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req cancelJourneyReq
	if !readJSON(r, &req) || req.JourneyID == "" || req.ExpectedPlanVersion == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeErr(w, http.StatusBadRequest, "invalid_plan_version", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "cancel_journey") {
		return
	}
	ok, _, _ := s.journeyMutationGuard(w, r, req.JourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}
	sampleIDs := s.fetchJourneySamples(ctx, req.JourneyID)
	// only unfinished (non-completed) assignments are cancelled; completed work preserved.
	_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status NOT IN ('completed','cancelled')`, req.JourneyID)
	s.releaseJourneyCapacity(ctx, req.JourneyID)
	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET status='cancelled', updated_at=now() WHERE id=$1`, req.JourneyID)
	for _, sid := range sampleIDs {
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET status='cancelled', active_journey_id=NULL, updated_at=now() WHERE id=$1`, sid)
	}
	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "cancel_journey", "journey", req.JourneyID, true, map[string]interface{}{"reason": req.Reason})
	s.emitEvent(ctx, "journey_cancelled", "journey", req.JourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.JourneyID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "cancel_journey", http.StatusCreated, map[string]interface{}{
		"journeyId": req.JourneyID, "status": "cancelled", "sampleIds": sampleIDs,
	})
}

type rerouteJourneyReq struct {
	JourneyID           string `json:"journeyId"`
	ExpectedPlanVersion *int   `json:"expectedPlanVersion"`
	Reason              string `json:"reason"`
	IdempotencyKey      string `json:"idempotencyKey"`
}

func (s *Server) RerouteJourney(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req rerouteJourneyReq
	if !readJSON(r, &req) || req.JourneyID == "" || req.ExpectedPlanVersion == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if *req.ExpectedPlanVersion < 1 {
		writeErr(w, http.StatusBadRequest, "invalid_plan_version", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "reroute_journey") {
		return
	}
	ok, _, _ := s.journeyMutationGuard(w, r, req.JourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}
	replanStatus, replacementID := s.replanJourney(ctx, req.JourneyID, req.Reason)
	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "reroute_journey", "journey", req.JourneyID, true, map[string]interface{}{"replanStatus": replanStatus})
	s.emitEvent(ctx, "journey_rerouted", "journey", req.JourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": replanStatus})
	resp := map[string]interface{}{"journeyId": req.JourneyID, "replanStatus": replanStatus}
	if replacementID != "" {
		resp["replacementPlanId"] = replacementID
	}
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "reroute_journey", http.StatusCreated, resp)
}

// replanJourney attempts to build a fresh route for the unfinished portion of a journey.
// It preserves completed assignments/stops and marks the old journey superseded.
func (s *Server) replanJourney(ctx context.Context2, journeyID, reason string) (string, string) {
	sampleIDs := s.fetchJourneySamples(ctx, journeyID)
	if len(sampleIDs) == 0 {
		return "not_required", ""
	}
	sampleID := sampleIDs[0]
	var sampleTypeID, status string
	var deadline interface{}
	var holderID *string
	err := s.DB.QueryRow(ctx, `SELECT s.sample_type_id, s.status, r.delivery_deadline, s.current_holder_id::text FROM samples s JOIN requests r ON r.id=s.request_id WHERE s.id=$1`, sampleID).
		Scan(&sampleTypeID, &status, &deadline, &holderID)
	if err != nil {
		return "exception", ""
	}
	if status == "completed" || status == "received" {
		return "not_required", ""
	}
	dl, ok := deadline.(interface{})
	_ = dl
	_ = ok

	// Determine current location to restart routing from: current holder's location if known,
	// otherwise the last completed stop, otherwise fail as expired.
	var fromNodeID string
	if holderID != nil {
		_ = s.DB.QueryRow(ctx, `SELECT assigned_location_id::text FROM users WHERE id=$1`, *holderID).Scan(&fromNodeID)
	}
	if fromNodeID == "" {
		_ = s.DB.QueryRow(ctx, `SELECT location_id::text FROM journey_stops WHERE journey_id=$1 AND completed_at IS NOT NULL ORDER BY sequence DESC LIMIT 1`, journeyID).Scan(&fromNodeID)
	}
	if fromNodeID == "" {
		_ = s.DB.QueryRow(ctx, `SELECT location_id::text FROM journey_stops WHERE journey_id=$1 ORDER BY sequence ASC LIMIT 1`, journeyID).Scan(&fromNodeID)
	}
	if fromNodeID == "" {
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET status='expired', updated_at=now() WHERE id=$1`, sampleID)
		return "expired", ""
	}

	st, _ := s.loadSampleType(ctx, sampleTypeID)
	deadlineT, _ := deadline.(timeType)

	build := s.buildJourneyPlan(ctx, sampleID, sampleTypeID, 0, 0, fromNodeID, true, fromNodeID, deadlineT, st.RequiresCooledRoute)
	if !build.OK {
		if build.FailureCode == "deadline_exceeded" {
			_, _ = s.DB.Exec(ctx, `UPDATE samples SET status='expired', updated_at=now() WHERE id=$1`, sampleID)
			return "expired", ""
		}
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET exception=$1, updated_at=now() WHERE id=$2`,
			jsonMap(map[string]interface{}{"reason": build.FailureCode}), sampleID)
		return "exception", ""
	}

	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET status='superseded', replan_status='replaced', updated_at=now() WHERE id=$1`, journeyID)
	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET parent_journey_id=$1, plan_version=1 WHERE id=$2`, journeyID, build.JourneyID)
	_, _ = s.DB.Exec(ctx, `UPDATE samples SET status='in_transit', updated_at=now() WHERE id=$1`, sampleID)
	return "replaced", build.JourneyID
}

type splitJourneyReq struct {
	JourneyID           string   `json:"journeyId"`
	ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
	SampleIDs           []string `json:"sampleIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (s *Server) SplitJourney(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req splitJourneyReq
	if !readJSON(r, &req) || req.JourneyID == "" || req.ExpectedPlanVersion == nil || len(req.SampleIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "split_journey") {
		return
	}
	ok, planVersion, _ := s.journeyMutationGuard(w, r, req.JourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}
	allSamples := s.fetchJourneySamples(ctx, req.JourneyID)
	splitSet := map[string]bool{}
	for _, id := range req.SampleIDs {
		splitSet[id] = true
	}
	remaining := []string{}
	for _, id := range allSamples {
		if !splitSet[id] {
			remaining = append(remaining, id)
		}
	}
	if len(remaining) == 0 || len(req.SampleIDs) == 0 {
		writeErr(w, http.StatusConflict, "invalid_split", "")
		return
	}

	newJourneyID := uuid.NewString()
	_, err := s.DB.Exec(ctx, `INSERT INTO journeys (id, plan_version, route_mode, status, estimated_delivery_at, capacity_used, capacity_available)
		SELECT $1, 1, route_mode, 'active', estimated_delivery_at, capacity_used, capacity_available FROM journeys WHERE id=$2`, newJourneyID, req.JourneyID)
	if err != nil {
		writeErr(w, http.StatusInternalServerError, "internal_error", "")
		return
	}
	for _, sid := range req.SampleIDs {
		_, _ = s.DB.Exec(ctx, `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, req.JourneyID, sid)
		_, _ = s.DB.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2)`, newJourneyID, sid)
		_, _ = s.DB.Exec(ctx, `UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status NOT IN ('completed','cancelled')`, newJourneyID, req.JourneyID, sid)
		_, _ = s.DB.Exec(ctx, `UPDATE samples SET active_journey_id=$1, updated_at=now() WHERE id=$2`, newJourneyID, sid)
	}
	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET plan_version=$1, updated_at=now() WHERE id=$2`, planVersion+1, req.JourneyID)

	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "split_journey", "journey", req.JourneyID, true, map[string]interface{}{"splitJourneyId": newJourneyID})
	s.emitEvent(ctx, "journey_split", "journey", req.JourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.JourneyID, "splitJourneyId": newJourneyID})

	origJourney := s.journeyPlanFull(ctx, req.JourneyID)
	splitJourney := s.journeyPlanFull(ctx, newJourneyID)
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "split_journey", http.StatusCreated, map[string]interface{}{
		"journey": origJourney, "splitJourney": splitJourney,
	})
}

func (s *Server) journeyPlanFull(ctx context.Context2, journeyID string) map[string]interface{} {
	var planVersion int
	var routeMode, status string
	var estDelivery interface{}
	var totalCost float64
	var capUsed, capAvail int
	_ = s.DB.QueryRow(ctx, `SELECT plan_version, route_mode, status, estimated_delivery_at, total_cost_units, capacity_used, capacity_available FROM journeys WHERE id=$1`, journeyID).
		Scan(&planVersion, &routeMode, &status, &estDelivery, &totalCost, &capUsed, &capAvail)
	return map[string]interface{}{
		"journeyId": journeyID, "planVersion": planVersion, "routeMode": routeMode, "status": status,
		"estimatedDeliveryAt": isoOrInterface(estDelivery), "totalCostUnits": totalCost,
		"capacityUsed": capUsed, "capacityAvailable": capAvail,
		"sampleIds": s.fetchJourneySamples(ctx, journeyID), "orderedStops": s.fetchJourneyStops(ctx, journeyID), "legs": s.fetchJourneyLegs(ctx, journeyID),
	}
}

type mergeJourneysReq struct {
	TargetJourneyID     string   `json:"targetJourneyId"`
	ExpectedPlanVersion *int     `json:"expectedPlanVersion"`
	SourceJourneyIDs    []string `json:"sourceJourneyIds"`
	IdempotencyKey      string   `json:"idempotencyKey"`
}

func (s *Server) MergeJourneys(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req mergeJourneysReq
	if !readJSON(r, &req) || req.TargetJourneyID == "" || req.ExpectedPlanVersion == nil || len(req.SourceJourneyIDs) == 0 {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "merge_journeys") {
		return
	}
	ok, planVersion, _ := s.journeyMutationGuard(w, r, req.TargetJourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}
	for _, srcID := range req.SourceJourneyIDs {
		var srcStatus string
		err := s.DB.QueryRow(ctx, `SELECT status FROM journeys WHERE id=$1`, srcID).Scan(&srcStatus)
		if err != nil {
			writeErr(w, http.StatusNotFound, "not_found", "")
			return
		}
		if srcStatus != "active" {
			writeErr(w, http.StatusConflict, "inactive_plan", "")
			return
		}
		sids := s.fetchJourneySamples(ctx, srcID)
		for _, sid := range sids {
			_, _ = s.DB.Exec(ctx, `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, srcID, sid)
			_, _ = s.DB.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.TargetJourneyID, sid)
			_, _ = s.DB.Exec(ctx, `UPDATE assignments SET journey_id=$1 WHERE journey_id=$2 AND sample_id=$3 AND status NOT IN ('completed','cancelled')`, req.TargetJourneyID, srcID, sid)
			_, _ = s.DB.Exec(ctx, `UPDATE samples SET active_journey_id=$1, updated_at=now() WHERE id=$2`, req.TargetJourneyID, sid)
		}
		_, _ = s.DB.Exec(ctx, `UPDATE journeys SET status='merged', updated_at=now() WHERE id=$1`, srcID)
	}
	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET plan_version=$1, updated_at=now() WHERE id=$2`, planVersion+1, req.TargetJourneyID)

	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "merge_journeys", "journey", req.TargetJourneyID, true, map[string]interface{}{"sourceJourneyIds": req.SourceJourneyIDs})
	s.emitEvent(ctx, "journeys_merged", "journey", req.TargetJourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.TargetJourneyID})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "merge_journeys", http.StatusCreated, s.journeyPlanFull(ctx, req.TargetJourneyID))
}

type editActivePlanReq struct {
	JourneyID           string                 `json:"journeyId"`
	ExpectedPlanVersion *int                   `json:"expectedPlanVersion"`
	ChangeType          string                 `json:"changeType"`
	Changes             map[string]interface{} `json:"changes"`
	IdempotencyKey       string                 `json:"idempotencyKey"`
}

var validChangeTypes = map[string]bool{
	"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
	"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
	"cancel_work": true, "reroute": true, "replace_route": true,
}

func (s *Server) EditActivePlan(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	var req editActivePlanReq
	if !readJSON(r, &req) || req.JourneyID == "" || req.ExpectedPlanVersion == nil || !validChangeTypes[req.ChangeType] || req.Changes == nil {
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "edit_active_plan") {
		return
	}
	ok, planVersion, _ := s.journeyMutationGuard(w, r, req.JourneyID, *req.ExpectedPlanVersion)
	if !ok {
		return
	}

	switch req.ChangeType {
	case "replace_worker", "reassign_worker":
		assignmentID, _ := req.Changes["assignmentId"].(string)
		newWorkerID, _ := req.Changes["workerId"].(string)
		if assignmentID == "" || newWorkerID == "" {
			writeErr(w, http.StatusBadRequest, "invalid_worker", "")
			return
		}
		var curStatus string
		err := s.DB.QueryRow(ctx, `SELECT status FROM assignments WHERE id=$1 AND journey_id=$2`, assignmentID, req.JourneyID).Scan(&curStatus)
		if err != nil {
			writeErr(w, http.StatusNotFound, "not_found", "")
			return
		}
		if curStatus == "completed" {
			writeErr(w, http.StatusConflict, "completed_work_immutable", "")
			return
		}
		_, _ = s.DB.Exec(ctx, `UPDATE assignments SET worker_id=$1, offered_worker_id=NULL, status='offered', offer_expires_at=now()+interval '5 minutes', updated_at=now() WHERE id=$2`, newWorkerID, assignmentID)
	case "cancel_work":
		assignmentID, _ := req.Changes["assignmentId"].(string)
		if assignmentID == "" {
			writeErr(w, http.StatusBadRequest, "invalid_json", "")
			return
		}
		var curStatus string
		err := s.DB.QueryRow(ctx, `SELECT status FROM assignments WHERE id=$1 AND journey_id=$2`, assignmentID, req.JourneyID).Scan(&curStatus)
		if err != nil {
			writeErr(w, http.StatusNotFound, "not_found", "")
			return
		}
		if curStatus == "completed" {
			writeErr(w, http.StatusConflict, "completed_work_immutable", "")
			return
		}
		_, _ = s.DB.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now() WHERE id=$1`, assignmentID)
	default:
		// generic changes recorded but not deeply modeled; still bump plan version.
	}

	_, _ = s.DB.Exec(ctx, `UPDATE journeys SET plan_version=$1, updated_at=now() WHERE id=$2`, planVersion+1, req.JourneyID)
	role := activeRoleFrom(ctx)
	s.audit(ctx, userIDFrom(ctx), role, "edit_active_plan", "journey", req.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
	s.emitEvent(ctx, "plan_edited", "journey", req.JourneyID, "dispatcher", "", map[string]interface{}{"journeyId": req.JourneyID, "changeType": req.ChangeType})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "edit_active_plan", http.StatusCreated, s.journeyPlanFull(ctx, req.JourneyID))
}

type reportDisruptionReq struct {
	ResourceType   string `json:"resourceType"`
	ResourceID     string `json:"resourceId"`
	Reason         string `json:"reason"`
	OccurredAt     string `json:"occurredAt"`
	IdempotencyKey string `json:"idempotencyKey"`
}

var validResourceTypes = map[string]bool{
	"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true,
}

func (s *Server) ReportDisruption(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	role := activeRoleFrom(ctx)
	if role == "" {
		writeErr(w, http.StatusConflict, "role_not_selected", "")
		return
	}
	if role != "dispatcher" && role != "administrator" {
		writeErr(w, http.StatusForbidden, "forbidden", "")
		return
	}
	var req reportDisruptionReq
	if !readJSON(r, &req) || !validResourceTypes[req.ResourceType] || req.ResourceID == "" || req.OccurredAt == "" {
		if req.ResourceType != "" && !validResourceTypes[req.ResourceType] {
			writeErr(w, http.StatusBadRequest, "invalid_resource_type", "")
			return
		}
		writeErr(w, http.StatusBadRequest, "invalid_json", "")
		return
	}
	if req.IdempotencyKey == "" {
		writeErr(w, http.StatusBadRequest, "idempotency_required", "")
		return
	}
	if _, ok := parseTime(req.OccurredAt); !ok {
		writeErr(w, http.StatusBadRequest, "invalid_time", "")
		return
	}
	if s.replayIfPresent(w, ctx, req.IdempotencyKey, "report_disruption") {
		return
	}

	affected := s.findAffectedSamples(ctx, req.ResourceType, req.ResourceID)
	replacementPlanIDs := []string{}
	overallStatus := "not_required"
	for _, sampleID := range affected {
		var journeyID string
		_ = s.DB.QueryRow(ctx, `SELECT coalesce(active_journey_id::text,'') FROM samples WHERE id=$1`, sampleID).Scan(&journeyID)
		if journeyID == "" {
			continue
		}
		replanStatus, replacementID := s.replanJourney(ctx, journeyID, req.Reason)
		if replacementID != "" {
			replacementPlanIDs = append(replacementPlanIDs, replacementID)
		}
		overallStatus = combineReplanStatus(overallStatus, replanStatus)
	}

	disruptionID := uuid.NewString()
	_, _ = s.DB.Exec(ctx, `INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, affected_sample_ids, replacement_plan_ids, replan_status)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, disruptionID, req.ResourceType, req.ResourceID, nilIfEmpty(req.Reason), req.OccurredAt, toUUIDArray(affected), toUUIDArray(replacementPlanIDs), overallStatus)

	s.audit(ctx, userIDFrom(ctx), role, "report_disruption", req.ResourceType, req.ResourceID, true, map[string]interface{}{"affectedSampleIds": affected, "replanStatus": overallStatus})
	s.emitEvent(ctx, "disruption_reported", req.ResourceType, req.ResourceID, "dispatcher", "", map[string]interface{}{"disruptionId": disruptionID, "replanStatus": overallStatus})
	s.writeIdempotentData(w, ctx, req.IdempotencyKey, "report_disruption", http.StatusCreated, map[string]interface{}{
		"disruptionId": disruptionID, "affectedSampleIds": emptyIfNil(affected),
		"replacementPlanIds": emptyIfNil(replacementPlanIDs), "replanStatus": overallStatus,
	})
}

func combineReplanStatus(cur, next string) string {
	priority := map[string]int{"not_required": 0, "replaced": 1, "expired": 2, "exception": 3}
	if priority[next] > priority[cur] {
		return next
	}
	return cur
}

func toUUIDArray(ids []string) []string {
	if ids == nil {
		return []string{}
	}
	return ids
}

func (s *Server) findAffectedSamples(ctx context.Context2, resourceType, resourceID string) []string {
	var query string
	switch resourceType {
	case "worker":
		query = `SELECT DISTINCT sample_id::text FROM assignments WHERE worker_id=$1 AND status NOT IN ('completed','cancelled')`
	case "location", "node", "laboratory":
		query = `SELECT DISTINCT sample_id::text FROM assignments WHERE (from_location_id=$1 OR to_location_id=$1 OR node_id=$1 OR laboratory_id=$1) AND status NOT IN ('completed','cancelled')`
	case "connection", "route":
		query = `SELECT DISTINCT a.sample_id::text FROM assignments a JOIN connections c ON c.from_location_id=a.from_location_id AND c.to_location_id=a.to_location_id
			WHERE c.id=$1 AND a.status NOT IN ('completed','cancelled')`
	default:
		return []string{}
	}
	rows, err := s.DB.Query(ctx, query, resourceID)
	out := []string{}
	if err != nil {
		return out
	}
	defer rows.Close()
	for rows.Next() {
		var id string
		_ = rows.Scan(&id)
		out = append(out, id)
	}
	return out
}

