        "github.com/jackc/pgx/v5"
        "github.com/jackc/pgx/v5/pgxpool"
)

type Server struct {
        DB *pgxpool.Pool
}

type errBody struct {
        Error string `json:"error"`
        Code  string `json:"code"`
}

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
        w.Header().Set("Content-Type", "application/json")
        w.WriteHeader(status)
        _ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
        writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeErr(w http.ResponseWriter, status int, code, msg string) {
        if msg == "" {
                msg = code
        }
        writeJSON(w, status, errBody{Error: msg, Code: code})
}

func readJSON(r *http.Request, v interface{}) bool {
        dec := json.NewDecoder(r.Body)
        if err := dec.Decode(v); err != nil {
                return false
        }
        return true
}

func parseTime(s string) (time.Time, bool) {
        if s == "" {
                return time.Time{}, false
        }
        t, err := time.Parse(time.RFC3339, s)
        if err != nil {
                return time.Time{}, false
        }
        return t, true
}

func nowISO() string {
        return time.Now().UTC().Format(time.RFC3339)
}

func timeNow() time.Time {
        return time.Now().UTC()
}

func minutesToDuration(m float64) time.Duration {
        return time.Duration(m * float64(time.Minute))
}

func isoOrNil(t *time.Time) interface{} {
        if t == nil {
                return nil
        }
        return t.UTC().Format(time.RFC3339)
}

func isoOf(t time.Time) string {
        return t.UTC().Format(time.RFC3339)
}

// noRows helper
func isNoRows(err error) bool {
        return err == pgx.ErrNoRows
}

func decodeJSON(b []byte, v interface{}) error {
        return json.Unmarshal(b, v)
}

const staleThreshold = 10 * time.Minute

// staleFromRaw reports whether a recorded-at value (typically a *time.Time or time.Time
// scanned from the database) is older than the staleness threshold, or unknown (nil).
func staleFromRaw(v interface{}) bool {
        switch t := v.(type) {
        case time.Time:
                return time.Since(t) > staleThreshold
        case *time.Time:
                if t == nil {
                        return true
                }
                return time.Since(*t) > staleThreshold
        default:
                return true
        }
}

type ctxKey string

const (
        ctxUserID ctxKey = "userID"
        ctxRoles  ctxKey = "roles"
        ctxActiveRole ctxKey = "activeRole"
        ctxUsername ctxKey = "username"
)

func withAuth(ctx context.Context, userID string, roles []string, activeRole string, username string) context.Context {
        ctx = context.WithValue(ctx, ctxUserID, userID)
        ctx = context.WithValue(ctx, ctxRoles, roles)
        ctx = context.WithValue(ctx, ctxActiveRole, activeRole)
        ctx = context.WithValue(ctx, ctxUsername, username)
        return ctx
}

func userIDFrom(ctx context.Context) string {
        v, _ := ctx.Value(ctxUserID).(string)
        return v
}
func rolesFrom(ctx context.Context) []string {
        v, _ := ctx.Value(ctxRoles).([]string)
        return v
}
func activeRoleFrom(ctx context.Context) string {
        v, _ := ctx.Value(ctxActiveRole).(string)
        return v
}
func usernameFrom(ctx context.Context) string {
        v, _ := ctx.Value(ctxUsername).(string)
        return v
}

func hasRole(ctx context.Context, role string) bool {
        for _, r := range rolesFrom(ctx) {
                if r == role {
                        return true
                }
        }
        return false
}

