type authenticateReq struct {
        Username string `json:"username"`
        Password string `json:"password"`
}

func (s *Server) AuthenticateUser(w http.ResponseWriter, r *http.Request) {
        var req authenticateReq
        if !readJSON(r, &req) || req.Username == "" || req.Password == "" {
                writeErr(w, http.StatusBadRequest, "invalid_json", "")
                return
        }
        ctx := r.Context()
        var userID, passHash string
        var active bool
        err := s.DB.QueryRow(ctx, `SELECT id, password_hash, active FROM users WHERE username=$1`, req.Username).Scan(&userID, &passHash, &active)
        if err != nil || !active || !checkPassword(passHash, req.Password) {
                s.audit(ctx, "", "", "sign_in", "user", req.Username, false, nil)
                writeErr(w, http.StatusUnauthorized, "invalid_credentials", "invalid username or password")
                return
        }
        roles := s.fetchRoles(ctx, userID)
        activeRole := ""
        if len(roles) == 1 {
                activeRole = roles[0]
        }
        token := newToken()
        _, err = s.DB.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, userID, nilIfEmpty(activeRole))
        if err != nil {
                writeErr(w, http.StatusInternalServerError, "internal_error", "")
                return
        }
        s.audit(ctx, userID, activeRole, "sign_in", "user", userID, true, nil)
        writeData(w, http.StatusOK, map[string]interface{}{
                "sessionToken": token,
                "userId":       userID,
                "roles":        roles,
                "activeRole":   activeRole,
        })
}

type selectRoleReq struct {
        Role string `json:"role"`
}

func (s *Server) SelectActiveRole(w http.ResponseWriter, r *http.Request) {
        var req selectRoleReq
        if !readJSON(r, &req) || req.Role == "" {
                writeErr(w, http.StatusBadRequest, "invalid_json", "")
                return
        }
        ctx := r.Context()
        userID := userIDFrom(ctx)
        roles := rolesFrom(ctx)
        found := false
        for _, rr := range roles {
                if rr == req.Role {
                        found = true
                }
        }
        if !found {
                writeErr(w, http.StatusForbidden, "role_not_held", "user does not hold this role")
                return
        }
        authz := r.Header.Get("Authorization")
        token := authz[len("Bearer "):]
        _, err := s.DB.Exec(ctx, `UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, token)
        if err != nil {
                writeErr(w, http.StatusInternalServerError, "internal_error", "")
                return
        }
        s.audit(ctx, userID, req.Role, "select_active_role", "user", userID, true, map[string]interface{}{"role": req.Role})
        writeData(w, http.StatusOK, map[string]interface{}{"activeRole": req.Role, "roles": roles})
}

type createUserReq struct {
        Username         string   `json:"username"`
        InitialPassword  string   `json:"initialPassword"`
        Email            string   `json:"email"`
        FullName         string   `json:"fullName"`
        Phone            string   `json:"phone"`
        Roles            []string `json:"roles"`
        Qualifications   []string `json:"qualifications"`
        Certifications   []certReq `json:"certifications"`
        Active           *bool    `json:"active"`
        AssignedLocationID string `json:"assignedLocationId"`
}

type certReq struct {
        Code      string  `json:"code"`
        Active    bool    `json:"active"`
        ExpiresAt string  `json:"expiresAt"`
}

func (s *Server) CreateUser(w http.ResponseWriter, r *http.Request) {
        ctx := r.Context()
        if activeRoleFrom(ctx) != "administrator" {
                writeErr(w, http.StatusForbidden, "forbidden", "administrator role required")
                return
        }
        var req createUserReq
        if !readJSON(r, &req) || req.Username == "" || req.InitialPassword == "" || len(req.Roles) == 0 {
                writeErr(w, http.StatusBadRequest, "invalid_json", "")
                return
        }
        for _, rl := range req.Roles {
                if !isValidRoleStr(rl) {
                        writeErr(w, http.StatusBadRequest, "invalid_user", "invalid role")
                        return
                }
        }
        active := true
        if req.Active != nil {
                active = *req.Active
        }
        var existing string
        err := s.DB.QueryRow(ctx, `SELECT id FROM users WHERE username=$1`, req.Username).Scan(&existing)
        if err == nil {
                writeErr(w, http.StatusConflict, "username_exists", "")
                return
        }
        hash, _ := hashPassword(req.InitialPassword)
        userID := uuid.NewString()
        var locID interface{}
        if req.AssignedLocationID != "" {
                locID = req.AssignedLocationID
        }
        _, err = s.DB.Exec(ctx, `INSERT INTO users (id, username, password_hash, email, full_name, phone, active, assigned_location_id)
                VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, userID, req.Username, hash, nilIfEmpty(req.Email), nilIfEmpty(req.FullName), nilIfEmpty(req.Phone), active, locID)
        if err != nil {
                writeErr(w, http.StatusInternalServerError, "internal_error", "")
                return
        }
        for _, rl := range req.Roles {
                _, _ = s.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2) ON CONFLICT DO NOTHING`, userID, rl)
        }
        for _, q := range req.Qualifications {
                _, _ = s.DB.Exec(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2) ON CONFLICT DO NOTHING`, userID, q)
        }
        for _, c := range req.Certifications {
                var exp interface{}
                if t, ok := parseTime(c.ExpiresAt); ok {
                        exp = t
                }
                _, _ = s.DB.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, userID, c.Code, c.Active, exp)
        }
        actorID := userIDFrom(ctx)
        s.audit(ctx, actorID, "administrator", "create_user", "user", userID, true, map[string]interface{}{"username": req.Username, "roles": req.Roles})
        writeData(w, http.StatusCreated, map[string]interface{}{
                "userId": userID, "username": req.Username, "email": req.Email, "fullName": req.FullName, "phone": req.Phone,
                "roles": req.Roles, "qualifications": req.Qualifications, "certifications": req.Certifications, "active": active,
        })
}

type updateUserAccessReq struct {
        UserID             string    `json:"userId"`
        Roles              []string  `json:"roles"`
        Qualifications     []string  `json:"qualifications"`
        Certifications     []certReq `json:"certifications"`
        Active             *bool     `json:"active"`
        AssignedLocationID string    `json:"assignedLocationId"`
}

func (s *Server) UpdateUserAccess(w http.ResponseWriter, r *http.Request) {
        ctx := r.Context()
        if activeRoleFrom(ctx) != "administrator" {
                writeErr(w, http.StatusForbidden, "forbidden", "")
                return
        }
        var req updateUserAccessReq
        if !readJSON(r, &req) || req.UserID == "" || len(req.Roles) == 0 || req.Active == nil {
                writeErr(w, http.StatusBadRequest, "invalid_json", "")
                return
        }
        var exists string
        err := s.DB.QueryRow(ctx, `SELECT id FROM users WHERE id=$1`, req.UserID).Scan(&exists)
        if err != nil {
                writeErr(w, http.StatusNotFound, "not_found", "")
                return
        }
        var locID interface{}
        if req.AssignedLocationID != "" {
                locID = req.AssignedLocationID
        }
        _, err = s.DB.Exec(ctx, `UPDATE users SET active=$1, assigned_location_id=$2, updated_at=now() WHERE id=$3`, *req.Active, locID, req.UserID)
        if err != nil {
                writeErr(w, http.StatusInternalServerError, "internal_error", "")
                return
        }
        _, _ = s.DB.Exec(ctx, `DELETE FROM user_roles WHERE user_id=$1`, req.UserID)
        for _, rl := range req.Roles {
                _, _ = s.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.UserID, rl)
        }
        _, _ = s.DB.Exec(ctx, `DELETE FROM user_qualifications WHERE user_id=$1`, req.UserID)
        for _, q := range req.Qualifications {
                _, _ = s.DB.Exec(ctx, `INSERT INTO user_qualifications (user_id, qualification) VALUES ($1,$2) ON CONFLICT DO NOTHING`, req.UserID, q)
        }
        _, _ = s.DB.Exec(ctx, `DELETE FROM user_certifications WHERE user_id=$1`, req.UserID)
        for _, c := range req.Certifications {
                var exp interface{}
                if t, ok := parseTime(c.ExpiresAt); ok {
                        exp = t
                }
                _, _ = s.DB.Exec(ctx, `INSERT INTO user_certifications (user_id, code, active, expires_at) VALUES ($1,$2,$3,$4)`, req.UserID, c.Code, c.Active, exp)
        }
        actorID := userIDFrom(ctx)
        s.audit(ctx, actorID, "administrator", "update_user_access", "user", req.UserID, true, map[string]interface{}{"roles": req.Roles})
        writeData(w, http.StatusCreated, map[string]interface{}{
                "userId": req.UserID, "roles": req.Roles, "qualifications": req.Qualifications, "certifications": req.Certifications, "active": *req.Active,
        })
}

func isValidRoleStr(r string) bool {
        switch r {
        case "administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
                return true
        }
        return false
}

func (s *Server) ReadUser(w http.ResponseWriter, r *http.Request, userID string) {
        ctx := r.Context()
        actorRole := activeRoleFrom(ctx)
        actorID := userIDFrom(ctx)
        if actorRole != "administrator" && actorRole != "dispatcher" && actorID != userID {
                writeErr(w, http.StatusForbidden, "forbidden", "")
                return
        }
        var username, email, fullName, phone string
        var active bool
        err := s.DB.QueryRow(ctx, `SELECT username, coalesce(email,''), coalesce(full_name,''), coalesce(phone,''), active FROM users WHERE id=$1`, userID).
                Scan(&username, &email, &fullName, &phone, &active)
        if err != nil {
                writeErr(w, http.StatusNotFound, "not_found", "")
                return
        }
        roles := s.fetchRoles(ctx, userID)
        quals := s.fetchQualifications(ctx, userID)
        certs := s.fetchCertifications(ctx, userID)
        writeData(w, http.StatusOK, map[string]interface{}{
