package api

import "context"

type edge struct {
        ConnectionID string
        From, To     string
        Minutes      int
        Cooled       bool
}

// shortestPath computes minimal travel-time path over active connections between active locations.
func (s *Server) shortestPath(ctx context.Context, from, to string) ([]edge, bool) {
        rows, err := s.DB.Query(ctx, `SELECT c.id, c.from_location_id, c.to_location_id, c.travel_minutes, c.cooled
                FROM connections c JOIN locations lf ON lf.id=c.from_location_id JOIN locations lt ON lt.id=c.to_location_id
                WHERE c.active=true AND lf.active=true AND lt.active=true`)
        if err != nil {
                return nil, false
        }
        adjacency := map[string][]edge{}
        for rows.Next() {
                var e edge
                _ = rows.Scan(&e.ConnectionID, &e.From, &e.To, &e.Minutes, &e.Cooled)
                adjacency[e.From] = append(adjacency[e.From], e)
        }
        rows.Close()

        if from == to {
                return []edge{}, true
        }

        dist := map[string]int{from: 0}
        prevEdge := map[string]edge{}
        visited := map[string]bool{}
        for {
                // pick unvisited node with min dist
                cur := ""
                best := -1
                for node, d := range dist {
                        if visited[node] {
                                continue
                        }
                        if best == -1 || d < best {
                                best = d
                                cur = node
                        }
                }
                if cur == "" {
                        break
                }
                if cur == to {
                        break
                }
                visited[cur] = true
                for _, e := range adjacency[cur] {
                        nd := dist[cur] + e.Minutes
                        if old, ok := dist[e.To]; !ok || nd < old {
                                dist[e.To] = nd
                                prevEdge[e.To] = e
                        }
                }
        }
        if _, ok := dist[to]; !ok {
                return nil, false
        }
        var path []edge
        cur := to
        for cur != from {
                e, ok := prevEdge[cur]
                if !ok {
                        return nil, false
                }
                path = append([]edge{e}, path...)
                cur = e.From
        }
        return path, true
}

// nearestActiveCollectionPoint finds the nearest active collection point to a coordinate.
func (s *Server) nearestActiveCollectionPoint(ctx context.Context, lat, lng float64) (string, float64, bool) {
        rows, err := s.DB.Query(ctx, `SELECT id, latitude, longitude, coverage_km FROM locations WHERE active=true AND is_collection_point=true`)
        if err != nil {
                return "", 0, false
        }
        defer rows.Close()
        bestID := ""
        bestDist := -1.0
        for rows.Next() {
                var id string
                var lat2, lng2, cov float64
                _ = rows.Scan(&id, &lat2, &lng2, &cov)
                d := haversineKm(lat, lng, lat2, lng2)
                if d <= cov && (bestDist < 0 || d < bestDist) {
                        bestDist = d
                        bestID = id
                }
        }
        if bestID == "" {
                return "", 0, false
        }
        return bestID, bestDist, true
}

