                if err == nil {
                        defer rows.Close()
                        for rows.Next() {
                                var id, status string
                                _ = rows.Scan(&id, &status)
                                samples = append(samples, map[string]interface{}{"sampleId": id, "status": status})
                        }
                }
                resp["requesterSamples"] = samples
        }
        if activeRole == "dispatcher" || activeRole == "administrator" {
                resp["operations"] = map[string]interface{}{
