package api

import (
	"context"
	"encoding/base64"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{
	CheckOrigin:  func(r *http.Request) bool { return true },
	Subprotocols: []string{"lab-logistics-v1"},
}

// StreamRealtimeEvents serves durable, resumable events for the caller's session.
// It supports both a WebSocket upgrade (subprotocol lab-logistics-v1, bearer [REDACTED] carried
// as a base64url-encoded "bearer.<token>" subprotocol entry) and a plain HTTP GET fallback
// that returns the buffered events since the given cursor.
func (s *Server) StreamRealtimeEvents(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	since := int64(0)
	if v := r.URL.Query().Get("since"); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil {
			since = n
		}
	}

	if websocket.IsWebSocketUpgrade(r) {
		s.serveEventsWebSocket(w, r, since)
		return
	}

	userID := userIDFrom(ctx)
	if userID == "" {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "")
		return
	}
	role := activeRoleFrom(ctx)
	events, cursor := s.fetchEventsSince(ctx, since, userID, role)
	writeData(w, http.StatusOK, map[string]interface{}{"events": events, "cursor": cursor})
}

// authenticateFromSubprotocol extracts a bearer [REDACTED] from the Sec-WebSocket-Protocol
// header, following the "bearer.<base64url-token>" convention, and resolves the session.
func (s *Server) authenticateFromSubprotocol(r *http.Request) (userID, role, username string, ok bool) {
	for _, proto := range websocket.Subprotocols(r) {
		if strings.HasPrefix(proto, "bearer.") {
			encoded := strings.TrimPrefix(proto, "bearer.")
			decoded, err := base64.RawURLEncoding.DecodeString(encoded)
			if err != nil {
				continue
			}
			token := string(decoded)
			ctx := r.Context()
			var active bool
			err = s.DB.QueryRow(ctx, `SELECT sessions.user_id, coalesce(sessions.active_role,''), users.username, users.active
				FROM sessions JOIN users ON users.id = sessions.user_id WHERE sessions.token=$1`, token).
				Scan(&userID, &role, &username, &active)
			if err == nil && active {
				return userID, role, username, true
			}
		}
	}
	return "", "", "", false
}

func (s *Server) serveEventsWebSocket(w http.ResponseWriter, r *http.Request, since int64) {
	userID, role, _, ok := s.authenticateFromSubprotocol(r)
	if !ok {
		writeErr(w, http.StatusUnauthorized, "unauthorized", "")
		return
	}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	ctx := r.Context()
	cursor := since
	events, newCursor := s.fetchEventsSince(ctx, cursor, userID, role)
	cursor = newCursor
	for _, e := range events {
		if conn.WriteJSON(e) != nil {
			return
		}
	}

	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			events, newCursor = s.fetchEventsSince(r.Context(), cursor, userID, role)
			cursor = newCursor
			for _, e := range events {
				if conn.WriteJSON(e) != nil {
					return
				}
			}
		case <-r.Context().Done():
			return
		}
	}
}

func (s *Server) fetchEventsSince(ctx context.Context, since int64, userID, role string) ([]map[string]interface{}, int64) {
	rows, err := s.DB.Query(ctx, `SELECT id, type, entity_type, coalesce(entity_id,''), payload, created_at
		FROM events WHERE id > $1 AND (audience_role IS NULL OR audience_role = $2) AND (audience_user_id IS NULL OR audience_user_id = $3)
		ORDER BY id ASC LIMIT 500`, since, nilIfEmpty(role), nilIfEmptyUUID(userID))
	out := []map[string]interface{}{}
	cursor := since
	if err != nil {
		return out, cursor
	}
	defer rows.Close()
	for rows.Next() {
		var id int64
		var evtType, entityType, entityID string
		var payload []byte
		var createdAt interface{}
		_ = rows.Scan(&id, &evtType, &entityType, &entityID, &payload, &createdAt)
		out = append(out, map[string]interface{}{
			"id": id, "type": evtType, "entityType": entityType, "entityId": entityID,
			"payload": jsonBytesToMap(payload), "createdAt": isoOrInterface(createdAt),
		})
		cursor = id
	}
	return out, cursor
}

