package api

import (
	"context"
	"net/http"
	"os"
	"path/filepath"
	"time"
)

// RegisterRoutes wires every documented operation onto mux, plus static frontend hosting
// and the unauthenticated readiness probe.
func RegisterRoutes(mux *http.ServeMux, s *Server) {
	auth := s.authMiddleware

	mux.HandleFunc("POST /api/authenticate-user", s.AuthenticateUser)
	mux.HandleFunc("GET /ready", s.Ready)

	mux.HandleFunc("POST /api/select-active-role", auth(s.SelectActiveRole))
	mux.HandleFunc("POST /api/create-user", auth(s.CreateUser))
	mux.HandleFunc("POST /api/update-user-access", auth(s.UpdateUserAccess))
	mux.HandleFunc("GET /api/read-user/{userId}", auth(func(w http.ResponseWriter, r *http.Request) {
		s.ReadUser(w, r, r.PathValue("userId"))
	}))

	mux.HandleFunc("POST /api/check-serviceability", auth(s.CheckServiceability))
	mux.HandleFunc("POST /api/read-serviceability-snapshot", auth(s.ReadServiceabilitySnapshot))
	mux.HandleFunc("POST /api/create-collection-request", auth(s.CreateCollectionRequest))
	mux.HandleFunc("POST /api/ingest-presealed-sample", auth(s.IngestPresealedSample))

	mux.HandleFunc("POST /api/create-sample-type", auth(s.CreateSampleType))
	mux.HandleFunc("POST /api/update-sample-type", auth(s.UpdateSampleType))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", auth(s.ConfigureLaboratoryAcceptance))
	mux.HandleFunc("POST /api/configure-capacity", auth(s.ConfigureCapacity))

	mux.HandleFunc("POST /api/create-location", auth(s.CreateLocation))
	mux.HandleFunc("POST /api/update-location", auth(s.UpdateLocation))
	mux.HandleFunc("POST /api/set-location-status", auth(s.SetLocationStatus))
	mux.HandleFunc("POST /api/set-location-function-status", auth(s.SetLocationFunctionStatus))
	mux.HandleFunc("POST /api/create-connection", auth(s.CreateConnection))
	mux.HandleFunc("POST /api/set-connection-status", auth(s.SetConnectionStatus))

	mux.HandleFunc("POST /api/accept-assignment", auth(s.AcceptAssignment))
	mux.HandleFunc("POST /api/decline-assignment", auth(s.DeclineAssignment))
	mux.HandleFunc("POST /api/record-worker-location", auth(s.RecordWorkerLocation))
	mux.HandleFunc("POST /api/set-worker-availability", auth(s.SetWorkerAvailability))
	mux.HandleFunc("POST /api/update-assignment-progress", auth(s.UpdateAssignmentProgress))

	mux.HandleFunc("POST /api/collect-and-seal-sample", auth(s.CollectAndSealSample))
	mux.HandleFunc("POST /api/record-handling-checkpoint", auth(s.RecordHandlingCheckpoint))
	mux.HandleFunc("POST /api/initiate-handoff", auth(s.InitiateHandoff))
	mux.HandleFunc("POST /api/confirm-handoff", auth(s.ConfirmHandoff))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", auth(s.ConfirmLaboratoryReceipt))
	mux.HandleFunc("POST /api/record-laboratory-exception", auth(s.RecordLaboratoryException))

	mux.HandleFunc("POST /api/cancel-journey", auth(s.CancelJourney))
	mux.HandleFunc("POST /api/reroute-journey", auth(s.RerouteJourney))
	mux.HandleFunc("POST /api/split-journey", auth(s.SplitJourney))
	mux.HandleFunc("POST /api/merge-journeys", auth(s.MergeJourneys))
	mux.HandleFunc("POST /api/edit-active-plan", auth(s.EditActivePlan))
	mux.HandleFunc("POST /api/report-disruption", auth(s.ReportDisruption))

	mux.HandleFunc("POST /api/read-journey-plan", auth(s.ReadJourneyPlan))
	mux.HandleFunc("POST /api/read-sample-lifecycle", auth(s.ReadSampleLifecycle))
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", auth(func(w http.ResponseWriter, r *http.Request) {
