package main

import (
        "context"
        "log"
        "net/http"
        "os"
        "time"

        "labsample/internal/api"
        "labsample/internal/db"
)

func main() {
        ctx := context.Background()

        if err := db.Connect(ctx); err != nil {
                log.Fatalf("failed to connect to database: %v", err)
        }

        s := &api.Server{DB: db.Pool}

        if err := s.EnsureInitialAdmin(ctx); err != nil {
                log.Fatalf("failed to ensure initial admin: %v", err)
        }
        if err := s.EnsureDefaultSampleTypes(ctx); err != nil {
                log.Fatalf("failed to ensure default sample types: %v", err)
        }

        mux := http.NewServeMux()
        api.RegisterRoutes(mux, s)

        addr := os.Getenv("LISTEN_ADDR")
        if addr == "" {
                addr = "127.0.0.1:8080"
        }

        srv := &http.Server{
                Addr:              addr,
                Handler:           mux,
                ReadHeaderTimeout: 10 * time.Second,
        }

        log.Printf("listening on %s", addr)
        if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
                log.Fatalf("server error: %v", err)
        }
}

