// Thin API client for the Lab Sample Pickup & Delivery backend.
// Every call speaks the pinned contract in contracts/openapi.contract.json.

export interface ApiError {
  error: string;
  code: string;
}

export class ApiRequestError extends Error {
  code: string;
  status: number;
  constructor(status: number, body: ApiError) {
    super(body.error || body.code || "request_failed");
    this.code = body.code;
    this.status = status;
  }
}

function getToken(): string | null {
  return localStorage.getItem("sessionToken");
}

export function setToken(token: string | null) {
  if (token) localStorage.setItem("sessionToken", token);
  else localStorage.removeItem("sessionToken");
}

async function request<T>(
  method: string,
  path: string,
  body?: unknown
): Promise<T> {
  const headers: Record<string, string> = { "Content-Type": "application/json" };
  const token = getToken();
  if (token) headers["Authorization"] = `Bearer ${token}`;

  const res = await fetch(`/api${path}`, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });

  const text = await res.text();
  const parsed = text ? JSON.parse(text) : {};

  if (!res.ok) {
    throw new ApiRequestError(res.status, parsed as ApiError);
  }
  return (parsed.data !== undefined ? parsed.data : parsed) as T;
}

export const api = {
  authenticateUser: (username: string, password: string) =>
    request<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }>(
      "POST",
      "/authenticate-user",
      { username, password }
    ),
  selectActiveRole: (role: string) =>
    request<{ activeRole: string }>("POST", "/select-active-role", { role }),
  bootstrap: () => request<any>("GET", "/ui/bootstrap"),
  checkServiceability: (body: unknown) =>
    request<any>("POST", "/check-serviceability", body),
  readServiceabilitySnapshot: () =>
    request<any>("POST", "/read-serviceability-snapshot", {}),
  createCollectionRequest: (body: unknown) =>
    request<any>("POST", "/create-collection-request", body),
  ingestPresealedSample: (body: unknown) =>
    request<any>("POST", "/ingest-presealed-sample", body),
  listRoleWork: (role?: string, status?: string) =>
    request<any>("POST", "/list-role-work", { role, status }),
  readOperationsState: (filters?: unknown) =>
    request<any>("POST", "/read-operations-state", { filters }),
  readSampleLifecycle: (sampleId: string) =>
    request<any>("POST", "/read-sample-lifecycle", { sampleId }),
  readSampleState: (sampleId: string) =>
    request<any>("GET", `/read-sample-state/${sampleId}`),
  readJourneyPlan: (journeyId: string) =>
    request<any>("POST", "/read-journey-plan", { journeyId }),
  searchAuditTrail: (body: unknown) =>
    request<any>("POST", "/search-audit-trail", body),
  acceptAssignment: (assignmentId: string, idempotencyKey: string) =>
    request<any>("POST", "/accept-assignment", { assignmentId, idempotencyKey }),
  declineAssignment: (assignmentId: string, idempotencyKey: string, reason?: string) =>
    request<any>("POST", "/decline-assignment", { assignmentId, idempotencyKey, reason }),
  recordWorkerLocation: (body: unknown) =>
    request<any>("POST", "/record-worker-location", body),
  setWorkerAvailability: (workerId: string, available: boolean, capacityUnits: number) =>
    request<any>("POST", "/set-worker-availability", { workerId, available, capacityUnits }),
  updateAssignmentProgress: (body: unknown) =>
    request<any>("POST", "/update-assignment-progress", body),
  collectAndSealSample: (body: unknown) =>
    request<any>("POST", "/collect-and-seal-sample", body),
  recordHandlingCheckpoint: (body: unknown) =>
    request<any>("POST", "/record-handling-checkpoint", body),
  initiateHandoff: (body: unknown) => request<any>("POST", "/initiate-handoff", body),
  confirmHandoff: (body: unknown) => request<any>("POST", "/confirm-handoff", body),
  confirmLaboratoryReceipt: (body: unknown) =>
    request<any>("POST", "/confirm-laboratory-receipt", body),
  recordLaboratoryException: (body: unknown) =>
    request<any>("POST", "/record-laboratory-exception", body),
  configureCapacity: (body: unknown) => request<any>("POST", "/configure-capacity", body),
  configureLaboratoryAcceptance: (body: unknown) =>
    request<any>("POST", "/configure-laboratory-acceptance", body),
  createLocation: (body: unknown) => request<any>("POST", "/create-location", body),
  updateLocation: (body: unknown) => request<any>("POST", "/update-location", body),
  setLocationStatus: (locationId: string, active: boolean) =>
    request<any>("POST", "/set-location-status", { locationId, active }),
  setLocationFunctionStatus: (locationId: string, fn: string, active: boolean) =>
    request<any>("POST", "/set-location-function-status", { locationId, function: fn, active }),
  createConnection: (body: unknown) => request<any>("POST", "/create-connection", body),
  setConnectionStatus: (connectionId: string, active: boolean) =>
    request<any>("POST", "/set-connection-status", { connectionId, active }),
  createSampleType: (body: unknown) => request<any>("POST", "/create-sample-type", body),
  updateSampleType: (body: unknown) => request<any>("POST", "/update-sample-type", body),
  createUser: (body: unknown) => request<any>("POST", "/create-user", body),
  updateUserAccess: (body: unknown) => request<any>("POST", "/update-user-access", body),
  readUser: (userId: string) => request<any>("GET", `/read-user/${userId}`),
  cancelJourney: (body: unknown) => request<any>("POST", "/cancel-journey", body),
  rerouteJourney: (body: unknown) => request<any>("POST", "/reroute-journey", body),
  splitJourney: (body: unknown) => request<any>("POST", "/split-journey", body),
  mergeJourneys: (body: unknown) => request<any>("POST", "/merge-journeys", body),
  editActivePlan: (body: unknown) => request<any>("POST", "/edit-active-plan", body),
  reportDisruption: (body: unknown) => request<any>("POST", "/report-disruption", body),
};

export function eventsUrl(since?: number): string {
  const proto = window.location.protocol === "https:" ? "wss" : "ws";
  const params = since ? `?since=${since}` : "";
  return `${proto}://${window.location.host}/api/events${params}`;
}

