  initiateHandoff: (body: unknown) => request<any>("POST", "/initiate-handoff", body),
  confirmHandoff: (body: unknown) => request<any>("POST", "/confirm-handoff", body),
  confirmLaboratoryReceipt: (body: unknown) =>
    request<any>("POST", "/confirm-laboratory-receipt", body),
  recordLaboratoryException: (body: unknown) =>
    request<any>("POST", "/record-laboratory-exception", body),
  configureCapacity: (body: unknown) => request<any>("POST", "/configure-capacity", body),
  configureLaboratoryAcceptance: (body: unknown) =>
    request<any>("POST", "/configure-laboratory-acceptance", body),
  createLocation: (body: unknown) => request<any>("POST", "/create-location", body),
  updateLocation: (body: unknown) => request<any>("POST", "/update-location", body),
  setLocationStatus: (locationId: string, active: boolean) =>
    request<any>("POST", "/set-location-status", { locationId, active }),
  setLocationFunctionStatus: (locationId: string, fn: string, active: boolean) =>
    request<any>("POST", "/set-location-function-status", { locationId, function: fn, active }),
  createConnection: (body: unknown) => request<any>("POST", "/create-connection", body),
  setConnectionStatus: (connectionId: string, active: boolean) =>
    request<any>("POST", "/set-connection-status", { connectionId, active }),
  createSampleType: (body: unknown) => request<any>("POST", "/create-sample-type", body),
  updateSampleType: (body: unknown) => request<any>("POST", "/update-sample-type", body),
  createUser: (body: unknown) => request<any>("POST", "/create-user", body),
  updateUserAccess: (body: unknown) => request<any>("POST", "/update-user-access", body),
  readUser: (userId: string) => request<any>("GET", `/read-user/${userId}`),
  cancelJourney: (body: unknown) => request<any>("POST", "/cancel-journey", body),
  rerouteJourney: (body: unknown) => request<any>("POST", "/reroute-journey", body),
  splitJourney: (body: unknown) => request<any>("POST", "/split-journey", body),
  mergeJourneys: (body: unknown) => request<any>("POST", "/merge-journeys", body),
  editActivePlan: (body: unknown) => request<any>("POST", "/edit-active-plan", body),
  reportDisruption: (body: unknown) => request<any>("POST", "/report-disruption", body),
};

export function eventsUrl(since?: number): string {
  const proto = window.location.protocol === "https:" ? "wss" : "ws";
  const params = since ? `?since=${since}` : "";
  return `${proto}://${window.location.host}/api/events${params}`;
}

