import React, { createContext, useContext, useEffect, useState } from "react";
import { api, setToken } from "./api";

export interface SessionUser {
  userId: string;
  username: string;
  fullName?: string;
  roles: string[];
  activeRole: string;
}

interface SessionContextValue {
  user: SessionUser | null;
  loading: boolean;
  login: (username: string, password: string) => Promise<void>;
  logout: () => void;
  selectRole: (role: string) => Promise<void>;
  refresh: () => Promise<void>;
}

const SessionContext = createContext<SessionContextValue | undefined>(undefined);

export function SessionProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<SessionUser | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = async () => {
    try {
      const boot = await api.bootstrap();
      const u = boot.user;
      setUser({
        userId: u.userId,
        username: u.username,
        fullName: u.fullName,
        roles: u.roles,
        activeRole: u.activeRole,
      });
    } catch {
      setUser(null);
      setToken(null);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (localStorage.getItem("sessionToken")) {
      refresh();
    } else {
      setLoading(false);
    }
  }, []);

  const login = async (username: string, password: string) => {
    const res = await api.authenticateUser(username, password);
    setToken(res.sessionToken);
    setUser({
      userId: res.userId,
      username,
      roles: res.roles,
      activeRole: res.activeRole,
    });
  };

  const logout = () => {
    setToken(null);
    setUser(null);
  };

  const selectRole = async (role: string) => {
    const res = await api.selectActiveRole(role);
    setUser((prev) => (prev ? { ...prev, activeRole: res.activeRole } : prev));
  };

  return (
    <SessionContext.Provider value={{ user, loading, login, logout, selectRole, refresh }}>
      {children}
    </SessionContext.Provider>
  );
}

export function useSession(): SessionContextValue {
  const ctx = useContext(SessionContext);
  if (!ctx) throw new Error("useSession must be used within SessionProvider");
  return ctx;
}

