import React from "react";
import { useSession } from "../lib/session";

export default function RoleSwitcher() {
  const { user, selectRole } = useSession();
  if (!user || user.roles.length < 2) {
    return (
      <span aria-label="role-switcher-single" style={{ marginRight: "1rem" }}>
        Role: {user?.activeRole}
      </span>
    );
  }
  return (
    <label style={{ display: "inline-block", marginRight: "1rem", color: "white" }}>
      Working as
      <select
        aria-label="select-active-role"
        value={user.activeRole}
        onChange={(e) => selectRole(e.target.value)}
        style={{ marginLeft: "0.5rem", width: "auto" }}
      >
        {user.roles.map((r) => (
          <option key={r} value={r}>
            {r}
          </option>
        ))}
      </select>
    </label>
  );
}

