import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useSession } from "../lib/session";
import { api } from "../lib/api";

export default function DashboardPage() {
  const { user } = useSession();
  const [work, setWork] = useState<any>(null);

  useEffect(() => {
    api.listRoleWork().then(setWork).catch(() => setWork(null));
  }, [user?.activeRole]);

  return (
    <div>
      <h1>Dashboard</h1>
      <p>
        Signed in as <strong>{user?.username}</strong>, acting as role{" "}
        <strong>{user?.activeRole}</strong>.
      </p>
      <div className="card">
        <h2>Quick links</h2>
        <ul>
          <li><Link to="/requests/new">Create a collection request</Link></li>
          <li><Link to="/serviceability">Check serviceability (dry run)</Link></li>
          <li><Link to="/work">View my current and past work</Link></li>
          <li><Link to="/monitor">Dispatcher monitoring dashboard</Link></li>
          <li><Link to="/audit">Search audit trail</Link></li>
          <li><Link to="/capacity">View / configure capacity</Link></li>
          <li><Link to="/map">Live map</Link></li>
        </ul>
      </div>
      {work && (
        <div className="card">
          <h2>Work summary for {user?.activeRole}</h2>
          <p>Pending: {work.pending?.length ?? 0}</p>
          <p>In progress: {work.inProgress?.length ?? 0}</p>
          <p>Completed: {work.completed?.length ?? 0}</p>
        </div>
      )}
    </div>
  );
}

