import React, { useState } from "react";
import { api, ApiRequestError } from "../lib/api";

export default function ServiceabilityPage() {
  const [latitude, setLatitude] = useState("12.9716");
  const [longitude, setLongitude] = useState("77.5946");
  const [sampleTypeId, setSampleTypeId] = useState("");
  const [requestedAt, setRequestedAt] = useState("");
  const [deliveryDeadline, setDeliveryDeadline] = useState("");
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setResult(null);
    setSubmitting(true);
    try {
      const res = await api.checkServiceability({
        origin: { latitude: parseFloat(latitude), longitude: parseFloat(longitude) },
        sampleTypeId,
        requestedAt: requestedAt || new Date().toISOString(),
        deliveryDeadline,
      });
      setResult(res);
    } catch (err) {
      if (err instanceof ApiRequestError) setError(err.message);
      else setError("Serviceability check failed.");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div>
      <h1>Serviceability check</h1>
      <p>
        This is a dry run — it never creates a request, sample, journey, assignment or capacity
        reservation.
      </p>
      <div className="card">
        <form onSubmit={onSubmit}>
          <label htmlFor="latitude">Latitude</label>
          <input id="latitude" value={latitude} onChange={(e) => setLatitude(e.target.value)} required />
          <label htmlFor="longitude">Longitude</label>
          <input id="longitude" value={longitude} onChange={(e) => setLongitude(e.target.value)} required />
          <label htmlFor="sampleTypeId">Sample type ID</label>
          <input
            id="sampleTypeId"
            value={sampleTypeId}
            onChange={(e) => setSampleTypeId(e.target.value)}
            required
          />
          <label htmlFor="requestedAt">Requested at</label>
          <input
            id="requestedAt"
            type="datetime-local"
            value={requestedAt}
            onChange={(e) => setRequestedAt(e.target.value)}
          />
          <label htmlFor="deliveryDeadline">Delivery deadline</label>
          <input
            id="deliveryDeadline"
            type="datetime-local"
            value={deliveryDeadline}
            onChange={(e) => setDeliveryDeadline(e.target.value)}
            required
          />
          {error && <p className="error-text" role="alert">{error}</p>}
          <button type="submit" disabled={submitting}>
            {submitting ? "Checking…" : "Check serviceability"}
          </button>
        </form>
      </div>
      {result && (
        <div className="card" aria-label="serviceability-result">
          <h2>Result: {result.serviceable ? "Serviceable" : "Not serviceable"}</h2>
          <pre>{JSON.stringify(result, null, 2)}</pre>
        </div>
      )}
    </div>
  );
}

