import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api, ApiRequestError } from "../lib/api";

function itemId(item: any): string {
  return item.assignmentId || item.sampleId || item.journeyId || item.id || "";
}

function itemLabel(item: any): string {
  if (item.kind === "sample") return `Sample ${item.sampleId}`;
  if (item.kind === "journey") return `Journey ${item.journeyId}`;
  return `${item.kind ?? "Assignment"} ${item.assignmentId ?? ""}`;
}

export default function WorkPage() {
  const [tab, setTab] = useState<"current" | "past">("current");
  const [work, setWork] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [locLat, setLocLat] = useState("");
  const [locLng, setLocLng] = useState("");
  const [locAssignmentId, setLocAssignmentId] = useState("");
  const [locMessage, setLocMessage] = useState<string | null>(null);

  const load = () => {
    api
      .listRoleWork()
      .then(setWork)
      .catch((e) => setError(e instanceof ApiRequestError ? e.message : "Failed to load work"));
  };

  useEffect(load, []);

  const respond = async (assignmentId: string, accept: boolean) => {
    setError(null);
    try {
      const key = crypto.randomUUID();
      if (accept) await api.acceptAssignment(assignmentId, key);
      else await api.declineAssignment(assignmentId, key);
      load();
    } catch (e) {
      setError(e instanceof ApiRequestError ? e.message : "Action failed");
    }
  };

  const recordLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setLocMessage(null);
    try {
      await api.recordWorkerLocation({
        assignmentId: locAssignmentId,
        coordinate: { latitude: parseFloat(locLat), longitude: parseFloat(locLng) },
        sequence: Date.now(),
        recordedAt: new Date().toISOString(),
      });
      setLocMessage("Location recorded.");
    } catch (e) {
      setLocMessage(e instanceof ApiRequestError ? e.message : "Failed to record location");
    }
  };

  const current = [...(work?.pending ?? []), ...(work?.inProgress ?? [])];
  const past = work?.completed ?? [];
  const list = tab === "current" ? current : past;

  return (
    <div>
      <h1>My work</h1>
      <div className="tabs">
        <button className={tab === "current" ? "active" : ""} onClick={() => setTab("current")}>
          Current
        </button>
        <button className={tab === "past" ? "active" : ""} onClick={() => setTab("past")}>
          Past
        </button>
      </div>
      {error && <p className="error-text" role="alert">{error}</p>}
      <div className="card">
        <table aria-label={tab === "current" ? "current-work" : "past-work"}>
          <thead>
            <tr>
              <th>Item</th>
              <th>Status</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {list.map((item: any) => (
              <tr key={itemId(item)}>
                <td>
                  {item.sampleId ? (
                    <Link to={`/samples/${item.sampleId}`}>{itemLabel(item)}</Link>
                  ) : (
                    itemLabel(item)
                  )}
                </td>
                <td>{item.status}</td>
                <td>
                  {item.kind !== "sample" && item.kind !== "journey" && item.status === "offered" && (
                    <>
                      <button onClick={() => respond(item.assignmentId, true)}>Accept</button>{" "}
                      <button onClick={() => respond(item.assignmentId, false)}>Decline</button>
                    </>
                  )}
                </td>
              </tr>
            ))}
            {list.length === 0 && (
              <tr>
                <td colSpan={3}>No work items.</td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="card">
        <h2>Record my location</h2>
        <form onSubmit={recordLocation}>
          <label htmlFor="locAssignmentId">Assignment ID</label>
          <input
            id="locAssignmentId"
            value={locAssignmentId}
            onChange={(e) => setLocAssignmentId(e.target.value)}
            required
          />
          <label htmlFor="locLat">Latitude</label>
          <input id="locLat" value={locLat} onChange={(e) => setLocLat(e.target.value)} required />
          <label htmlFor="locLng">Longitude</label>
          <input id="locLng" value={locLng} onChange={(e) => setLocLng(e.target.value)} required />
          <button type="submit">Record location</button>
        </form>
        {locMessage && <p>{locMessage}</p>}
      </div>
    </div>
  );
}

