import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { api, ApiRequestError } from "../lib/api";

export default function SampleDetailPage() {
  const { sampleId } = useParams();
  const [lifecycle, setLifecycle] = useState<any>(null);
  const [state, setState] = useState<any>(null);
  const [journey, setJourney] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!sampleId) return;
    api
      .readSampleLifecycle(sampleId)
      .then(setLifecycle)
      .catch((e) => setError(e instanceof ApiRequestError ? e.message : "Failed to load sample"));
    api.readSampleState(sampleId).then(setState).catch(() => setState(null));
  }, [sampleId]);

  useEffect(() => {
    const journeyId = lifecycle?.activeJourneyId;
    if (journeyId) {
      api.readJourneyPlan(journeyId).then(setJourney).catch(() => setJourney(null));
    }
  }, [lifecycle]);

  if (error) return <p className="error-text" role="alert">{error}</p>;
  if (!lifecycle) return <p>Loading…</p>;

  return (
    <div>
      <h1>Sample {sampleId}</h1>
      <div className="card">
        <h2>Status</h2>
        <p>Current status: <strong>{lifecycle.status}</strong></p>
        <p>Current custodian: {lifecycle.currentHolderId ?? "unassigned"}</p>
        <p>
          Latest location freshness:{" "}
          <span className={lifecycle.locationStale ? "stale" : "fresh"} aria-label="location-freshness">
            {lifecycle.locationStale ? "Stale" : "Fresh"}
          </span>
        </p>
        {lifecycle.locationRecordedAt && (
          <p>Last update: {lifecycle.locationRecordedAt}</p>
        )}
        {lifecycle.exception && (
          <p className="error-text" role="alert" aria-label="sample-exception">
            Exception: {JSON.stringify(lifecycle.exception)}
          </p>
        )}
      </div>

      {journey && (
        <div className="card" aria-label="route-progress">
          <h2>Route</h2>
          <p>Journey: {journey.journeyId} (plan v{journey.planVersion}, mode {journey.routeMode})</p>
          <table>
            <thead>
              <tr>
                <th>Sequence</th>
                <th>Location</th>
                <th>Type</th>
                <th>Estimated at</th>
                <th>Completed</th>
              </tr>
            </thead>
            <tbody>
              {(journey.orderedStops ?? []).map((s: any) => (
                <tr key={s.stopId}>
                  <td>{s.sequence}</td>
                  <td>{s.locationId}</td>
                  <td>{s.stopType}</td>
                  <td>{s.estimatedAt}</td>
                  <td>{s.completedAt ? "Yes" : "No"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div className="card" aria-label="status-timeline">
        <h2>Status history</h2>
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Action</th>
              <th>Actor role</th>
              <th>Outcome</th>
            </tr>
          </thead>
          <tbody>
            {(lifecycle.timeline ?? []).map((t: any) => (
              <tr key={t.eventId}>
                <td>{t.occurredAt}</td>
                <td>{t.action}</td>
                <td>{t.role}</td>
                <td>{t.success ? "success" : "failed"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

