import React, { useEffect, useState } from "react";
import { api, ApiRequestError } from "../lib/api";

export default function MonitorPage() {
  const [state, setState] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    api
      .readOperationsState()
      .then(setState)
      .catch((e) => setError(e instanceof ApiRequestError ? e.message : "Failed to load"));
  }, []);

  if (error) return <p className="error-text" role="alert">{error}</p>;
  if (!state) return <p>Loading…</p>;

  const categories: Array<[string, any[]]> = [
    ["Samples", state.samples ?? []],
    ["Workers", state.workers ?? []],
    ["Collection nodes & laboratories", state.locations ?? []],
    ["Routes / connections", state.connections ?? []],
    ["Exceptions", state.exceptions ?? []],
  ];

  return (
    <div>
      <h1>Monitoring dashboard</h1>
      {categories.map(([title, items]) => (
        <div className="card" key={title} aria-label={`monitor-category-${title}`}>
          <h2>{title} ({items.length})</h2>
          <table>
            <thead>
              <tr>
                <th>ID</th>
                <th>Status / Name</th>
                <th>Details</th>
              </tr>
            </thead>
            <tbody>
              {items.slice(0, 20).map((it: any, i: number) => (
                <tr key={it.sampleId || it.workerId || it.locationId || it.connectionId || i}>
                  <td>{it.sampleId || it.workerId || it.locationId || it.connectionId || i}</td>
                  <td>{it.status || it.name || (it.available !== undefined ? (it.available ? "available" : "unavailable") : "")}</td>
                  <td>
                    {it.locationStale !== undefined && (
                      <span className={it.locationStale ? "stale" : "fresh"}>
                        {it.locationStale ? "stale" : "fresh"}
                      </span>
                    )}
                  </td>
                </tr>
              ))}
              {items.length === 0 && (
                <tr><td colSpan={3}>None</td></tr>
              )}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  );
}

