import React, { useState } from "react";
import { api, ApiRequestError } from "../lib/api";

export default function AuditPage() {
  const [query, setQuery] = useState("");
  const [entityId, setEntityId] = useState("");
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [submitting, setSubmitting] = useState(false);

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setSubmitting(true);
    try {
      const res = await api.searchAuditTrail({
        query: query || undefined,
        entityId: entityId || undefined,
        limit: 50,
        offset: 0,
        order: "newest_first",
      });
      setResult(res);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Search failed");
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <div>
      <h1>Audit trail</h1>
      <div className="card">
        <form onSubmit={onSubmit}>
          <label htmlFor="query">Search text</label>
          <input id="query" value={query} onChange={(e) => setQuery(e.target.value)} />
          <label htmlFor="entityId">Entity ID (request or sample)</label>
          <input id="entityId" value={entityId} onChange={(e) => setEntityId(e.target.value)} />
          {error && <p className="error-text" role="alert">{error}</p>}
          <button type="submit" disabled={submitting}>
            {submitting ? "Searching…" : "Search"}
          </button>
        </form>
      </div>
      {result && (
        <div className="card" aria-label="audit-results">
          <p>{result.total} total, showing {result.returned}</p>
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Role</th>
                <th>Action</th>
                <th>Entity</th>
                <th>Outcome</th>
              </tr>
            </thead>
            <tbody>
              {(result.entries ?? []).map((entry: any) => (
                <tr key={entry.auditId}>
                  <td>{entry.occurredAt}</td>
                  <td>{entry.actorId}</td>
                  <td>{entry.actorRole}</td>
                  <td>{entry.action}</td>
                  <td>{entry.entityType} {entry.entityId}</td>
                  <td>{entry.success ? "success" : "failure"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

