import React, { useEffect, useState } from "react";
import { useSession } from "../lib/session";
import { api, ApiRequestError } from "../lib/api";

export default function CapacityPage() {
  const { user } = useSession();
  const [state, setState] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);
  const [resourceId, setResourceId] = useState("");
  const [capacityUnits, setCapacityUnits] = useState("");
  const [cooledCapacityUnits, setCooledCapacityUnits] = useState("");
  const [message, setMessage] = useState<string | null>(null);

  const canConfigure =
    user?.activeRole === "administrator" ||
    user?.activeRole === "node_handler" ||
    user?.activeRole === "laboratory_team";

  useEffect(() => {
    api
      .readOperationsState()
      .then(setState)
      .catch((e) => setError(e instanceof ApiRequestError ? e.message : "Failed to load"));
  }, []);

  const onSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    try {
      await api.configureCapacity({
        resourceId,
        capacityUnits: parseInt(capacityUnits, 10),
        cooledCapacityUnits: cooledCapacityUnits ? parseInt(cooledCapacityUnits, 10) : undefined,
      });
      setMessage("Capacity updated.");
    } catch (err) {
      setMessage(err instanceof ApiRequestError ? err.message : "Failed to update capacity");
    }
  };

  return (
    <div>
