import React, { useEffect, useRef, useState } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { Protocol } from "pmtiles";
import { api, ApiRequestError } from "../lib/api";

export default function MapPage() {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);

    if (!mapContainer.current) return;
    const map = new maplibregl.Map({
      container: mapContainer.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 11,
    });
    mapRef.current = map;

    map.on("load", async () => {
      try {
        const state = await api.readOperationsState();
        const locationFeatures = (state.locations ?? []).map((loc: any) => ({
          type: "Feature",
          geometry: {
            type: "Point",
            coordinates: [loc.coordinate.longitude, loc.coordinate.latitude],
          },
          properties: { name: loc.name, active: loc.active },
        }));
        map.addSource("network-locations", {
          type: "geojson",
          data: { type: "FeatureCollection", features: locationFeatures },
        });
        map.addLayer({
          id: "network-locations-layer",
          type: "circle",
          source: "network-locations",
          paint: {
            "circle-radius": 6,
            "circle-color": ["case", ["get", "active"], "#1a7a1a", "#999"],
          },
        });

        const workerFeatures = (state.workers ?? [])
          .filter((w: any) => w.latestLocation)
          .map((w: any) => ({
            type: "Feature",
            geometry: {
              type: "Point",
              coordinates: [w.latestLocation.longitude, w.latestLocation.latitude],
            },
            properties: { name: w.fullName, stale: w.locationStale },
          }));
        map.addSource("workers", {
          type: "geojson",
          data: { type: "FeatureCollection", features: workerFeatures },
        });
        map.addLayer({
          id: "workers-layer",
          type: "circle",
          source: "workers",
          paint: {
            "circle-radius": 5,
            "circle-color": ["case", ["get", "stale"], "#b00020", "#1c2b3a"],
          },
        });
      } catch (e) {
        setError(e instanceof ApiRequestError ? e.message : "Failed to load map overlay data");
      }
    });

    return () => {
      map.remove();
      maplibregl.removeProtocol("pmtiles");
    };
  }, []);

  return (
    <div>
      <h1>Live map</h1>
      {error && <p className="error-text" role="alert">{error}</p>}
      <div id="map-container" ref={mapContainer} aria-label="live-map" />
    </div>
  );
}

