import React, { useState } from "react";
import { useSession } from "../lib/session";
import { api, ApiRequestError } from "../lib/api";

export default function AdminPage() {
  const { user } = useSession();
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [username, setUsername] = useState("");
  const [initialPassword, setInitialPassword] = useState("");
  const [roles, setRoles] = useState("requester");

  const [locName, setLocName] = useState("");
  const [locLat, setLocLat] = useState("");
  const [locLng, setLocLng] = useState("");
  const [locCoverageKm, setLocCoverageKm] = useState("5");

  if (user?.activeRole !== "administrator" && user?.activeRole !== "dispatcher") {
    return <p>Only administrators and dispatchers can access this page.</p>;
  }

  const createUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setMessage(null);
    setError(null);
    try {
      await api.createUser({
        username,
        initialPassword,
        roles: roles.split(",").map((r) => r.trim()).filter(Boolean),
        active: true,
      });
      setMessage("User created.");
