package api

import (
        "context"
        "os"

        "github.com/google/uuid"
)

// EnsureInitialAdmin creates the first administrator account from ADMIN_USERNAME/ADMIN_PASSWORD
// environment variables when no users exist yet. It is idempotent: running it again after users
// already exist (including after a restart) does not create a duplicate admin or remove users.
func (s *Server) EnsureInitialAdmin(ctx context.Context) error {
        var count int
        if err := s.DB.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count); err != nil {
                return err
        }
        if count > 0 {
                return nil
        }
        username := os.Getenv("ADMIN_USERNAME")
        password := os.Getenv("ADMIN_PASSWORD")
        if username == "" || password == "" {
                return nil
        }
        hash, err := hashPassword(password)
        if err != nil {
                return err
        }
        userID := uuid.NewString()
        _, err = s.DB.Exec(ctx, `INSERT INTO users (id, username, password_hash, full_name, active) VALUES ($1,$2,$3,$4,true)
                ON CONFLICT (username) DO NOTHING`, userID, username, hash, "Administrator")
        if err != nil {
                return err
        }
        _, err = s.DB.Exec(ctx, `INSERT INTO user_roles (user_id, role) VALUES ($1,'administrator') ON CONFLICT DO NOTHING`, userID)
        return err
}

type defaultSampleType struct {
        Name                       string
        QualifiedCollectorRequired bool
        RequiredQualification      string
        ContainerType              string
        TemperatureMinC            float64
        TemperatureMaxC            float64
        RequiresCooledRoute        bool
        BatchingAllowed            bool
        TimeCritical               bool
}

// EnsureDefaultSampleTypes creates the required default named sample types (Amber, Indigo,
// Frost, Pulse) if they do not already exist. Safe to call on every startup.
func (s *Server) EnsureDefaultSampleTypes(ctx context.Context) error {
        defaults := []defaultSampleType{
                {Name: "Amber", QualifiedCollectorRequired: true, RequiredQualification: "amber", ContainerType: "standard_tube", TemperatureMinC: 15, TemperatureMaxC: 25, BatchingAllowed: true},
