                {Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "pulse", ContainerType: "standard_tube", TemperatureMinC: 15, TemperatureMaxC: 25, BatchingAllowed: false, TimeCritical: true},
        }

